program HelloWorld;

uses Std.Console;

begin
  WriteLn('Hello, world!')
end.

program SumPositiveExample;

uses Std.Console;

function SumPositive(Values: array of integer): integer;
begin
  mutable var Total: integer := 0;
  for Value: integer in Values do
  begin
    if Value > 0 then
    begin
      Total := Total + Value
    end
  end;
  return Total
end;

begin
  WriteLn(SumPositive([-2, 4, 0, 7]))
end.

program CountEvenExample;

uses Std.Console;

function CountEven(Values: array of integer): integer;
begin
  mutable var Count: integer := 0;
  for Value: integer in Values do
  begin
    if Value mod 2 = 0 then
    begin
      Count := Count + 1
    end
  end;
  return Count
end;

begin
  WriteLn(CountEven([1, 2, 4, 7]))
end.

// Immutable state and transcript formatting for the Local Chat application.
unit LocalChat.Model;

uses Std.Arrays, Std.Console, Std.Str, Std.Tui;

public type
  // Origin of one visible local chat entry.
  ChatRole = enum
    // Prompt submitted by the user.
    User;
    // Text returned by the local model.
    Assistant;
    // Error returned while processing a request.
    Failure;
  end;
  // One entry retained for display during the current process.
  ChatEntry = record
    // Origin used to label the entry.
    public Role: ChatRole;
    // Entry text displayed in the transcript.
    public Text: string;

    // Creates a user entry.
    //
    // Parameters:
    // - `Text`: Prompt text submitted by the user.
    public static function User(Text: string): ChatEntry;
    begin
      return record
        Role := ChatRole.User;
        Text := Text;
      end
    end;

    // Creates an assistant entry.
    //
    // Parameters:
    // - `Text`: Completion text returned by the model.
    public static function Assistant(Text: string): ChatEntry;
    begin
      return record
        Role := ChatRole.Assistant;
        Text := Text;
      end
    end;

    // Creates a failed-request entry.
    //
    // Parameters:
    // - `Text`: Error text returned by the request service.
    public static function Failure(Text: string): ChatEntry;
    begin
      return record
        Role := ChatRole.Failure;
        Text := Text;
      end
    end;
  end;
  // Complete immutable state supplied to the Local Chat MVU view.
  LocalChatModel = record
    // Conversation entries in display order.
    public Entries: array of ChatEntry;
    // Current prompt editor contents.
    public Draft: string;
    // Caret position inside `Draft`.
    public DraftCaret: integer;
    // Caret position inside the read-only transcript.
    public TranscriptCaret: integer;
    // Current transcript viewport offset.
    public TranscriptOffset: TuiPoint;
    // Identifier of the focused control.
    public Focus: integer;
    // Short status text shown in the footer.
    public Status: string;
    // Current terminal width in cells.
    public Width: integer;
    // Current terminal height in cells.
    public Height: integer;
  end;

// Creates an empty Local Chat model for the supplied terminal size.
//
// Parameters:
// - `Width`: Initial terminal width in cells.
// - `Height`: Initial terminal height in cells.
public function LocalChatModelCreate(Width: integer; Height: integer): LocalChatModel;
begin
  return record
    Entries := [];
    Draft := '';
    DraftCaret := 0;
    TranscriptCaret := 0;
    TranscriptOffset := TuiPoint.Create(0, 0);
    Focus := 1;
    Status := 'Ready';
    Width := Width;
    Height := Height;
  end
end;

// Wraps text at grapheme boundaries for a cell-width limit.
//
// Parameters:
// - `Text`: Text to wrap without splitting grapheme clusters.
// - `MaximumWidth`: Maximum display width of each output line.
function WrapText(Text: string; MaximumWidth: integer): string;
begin
  if MaximumWidth <= 0 then
  begin
    return ''
  end;
  mutable var Wrapped: string := '';
  mutable var LineWidth: integer := 0;
  var NewLine: string := Std.Str.Chr(10);
  for Grapheme: string in Std.Console.SplitGraphemes(Text) do
  begin
    if Grapheme = NewLine then
    begin
      Wrapped := Wrapped + NewLine;
      LineWidth := 0
    end
    else
    begin
      var GraphemeWidth: integer := Std.Console.DisplayWidth(Grapheme);
      if (LineWidth > 0) and (LineWidth + GraphemeWidth > MaximumWidth) then
      begin
        Wrapped := Wrapped + NewLine;
        LineWidth := 0
      end;

      Wrapped := Wrapped + Grapheme;
      LineWidth := LineWidth + GraphemeWidth
    end
  end;

  return Wrapped
end;

// Returns the transcript label for one chat role.
//
// Parameters:
// - `Role`: Entry origin to label.
function RoleLabel(Role: ChatRole): string;
begin
  case Role of
    ChatRole.User:
    begin
      return 'YOU'
    end;
    ChatRole.Assistant:
    begin
      return 'ASSISTANT'
    end;
    ChatRole.Failure:
    begin
      return 'ERROR'
    end
  end
end;

// Builds the width-bounded transcript displayed by the read-only transcript area.
//
// Parameters:
// - `State`: Current application state containing entries and terminal dimensions.
public function LocalChatTranscript(State: LocalChatModel): string;
begin
  if Std.Arrays.Length(State.Entries) = 0 then
  begin
    return ('No messages yet.' + Std.Str.Chr(10)) + 'Type below and press Enter.'
  end;
  mutable var MaximumWidth: integer := State.Width - 6;
  if MaximumWidth < 1 then
  begin
    MaximumWidth := 1
  end;
  mutable var Transcript: string := '';
  var NewLine: string := Std.Str.Chr(10);
  for Index: integer := 0 to Std.Arrays.Length(State.Entries) - 1 do
  begin
    if Transcript <> '' then
    begin
      Transcript := (Transcript + NewLine) + NewLine
    end;

    Transcript := ((Transcript + RoleLabel(State.Entries[Index].Role)) + NewLine) +
                  WrapText(State.Entries[Index].Text, MaximumWidth)
  end;

  return Transcript
end;

// Moves the transcript caret and viewport to the latest visible entry.
//
// Parameters:
// - `State`: Current application state to scroll.
public function LocalChatScrollToEnd(State: LocalChatModel): LocalChatModel;
begin
  mutable var Next: LocalChatModel := State;
  var Transcript: string := LocalChatTranscript(Next);
  Next.TranscriptCaret := Std.Str.Length(Transcript);
  mutable var VisibleLines: integer := Next.Height - 7;
  if VisibleLines < 1 then
  begin
    VisibleLines := 1
  end;
  var LineCount: integer := Std.Arrays.Length(Std.Str.Split(Transcript, Std.Str.Chr(10)));
  mutable var OffsetY: integer := LineCount - VisibleLines;
  if OffsetY < 0 then
  begin
    OffsetY := 0
  end;

  Next.TranscriptOffset := TuiPoint.Create(0, OffsetY);
  return Next
end;

// OpenAI-compatible request boundary for the Local Chat application.
unit LocalChat.Service;

uses LocalChat.Config, Std.Ai.OpenAi;

// Sends one independent prompt to the fixed local llama.cpp model.
//
// Parameters:
// - `Prompt`: User prompt sent as the sole chat message.
public function LocalChatRequest(Prompt: string): result of string, string;
begin
  var ClientValue: Client := Client.Create(LocalChatBaseUrl, LocalChatModelName);
  return Complete(ClientValue, [ChatMessage.User(Prompt)], ChatOptions.Default())
end;

// Color palette used by the Local Chat TUI.
unit LocalChat.Theme;

uses Std.Tui;

// Returns the dark cyan-and-amber truecolor palette shared with the Notes design language.
public function LocalChatPalette(): TuiPalette;
begin
  var Background: TuiColor := TuiColor.FromRgb(10, 15, 23);
  var Surface: TuiColor := TuiColor.FromRgb(17, 24, 35);
  var SurfaceFocused: TuiColor := TuiColor.FromRgb(24, 39, 53);
  var Text: TuiColor := TuiColor.FromRgb(216, 226, 236);
  var Muted: TuiColor := TuiColor.FromRgb(126, 145, 160);
  var Border: TuiColor := TuiColor.FromRgb(42, 61, 75);
  var Accent: TuiColor := TuiColor.FromRgb(70, 211, 196);
  var Amber: TuiColor := TuiColor.FromRgb(245, 184, 76);
  var Coral: TuiColor := TuiColor.FromRgb(244, 112, 106);
  mutable var Palette: TuiPalette := TuiPalette.Default();
  Palette.Normal := TuiStyle.FromColors(Text, Background);
  Palette.Disabled := TuiStyle.FromColors(Muted, Background);
  Palette.Focused := TuiStyle.FromColors(Text, SurfaceFocused);
  Palette.Selected := TuiStyle.FromColors(Text, SurfaceFocused);
  Palette.Shortcut := TuiStyle.Create(Accent, Background, true, false, false, false);
  Palette.Frame := TuiStyle.FromColors(Border, Background);
  Palette.Title := TuiStyle.Create(Text, Background, true, false, false, false);
  Palette.StatusNormal := TuiStyle.FromColors(Text, Surface);
  Palette.StatusShortcut := TuiStyle.Create(Accent, Surface, true, false, false, false);
  Palette.StatusSelected := TuiStyle.FromColors(Background, Accent);
  Palette.Rule := TuiStyle.FromColors(Border, Background);
  Palette.Failure := TuiStyle.FromColors(Coral, Background);
  Palette.Warning := TuiStyle.FromColors(Amber, Background);
  Palette.Accent := TuiStyle.Create(Accent, Background, true, false, false, false);
  Palette.Inputs := Palette.Inputs.WithRole(TuiStyleRole.InputNormal, TuiStyle.FromColors(Text, Surface));
  Palette.Inputs := Palette.Inputs.WithRole(TuiStyleRole.InputFocused, TuiStyle.FromColors(Text, SurfaceFocused));
  Palette.Inputs := Palette.Inputs.WithRole(TuiStyleRole.InputHint, TuiStyle.FromColors(Muted, Surface));
  Palette.Inputs := Palette.Inputs.WithRole(TuiStyleRole.InputCursor, TuiStyle.FromColors(Background, Accent));
  return Palette
end;

// MVU update logic for the Local Chat application.
unit LocalChat.Update;

uses LocalChat.Model, LocalChat.Service, Std.Arrays, Std.Console, Std.Options, Std.Str, Std.Tui;

const
  // Identifier of the prompt input control.
  PromptControl: integer := 1;
  // Action emitted when the prompt text changes.
  PromptChangedAction: integer := 1;
  // Action emitted when the transcript viewport changes.
  TranscriptChangedAction: integer := 2;
  // Action emitted by the send button.
  SendAction: integer := 10;

// Appends one entry without mutating the supplied model value.
//
// Parameters:
// - `State`: Current application state.
// - `Entry`: Entry to append to the conversation.
function AppendEntry(State: LocalChatModel; Entry: ChatEntry): LocalChatModel;
begin
  mutable var Next: LocalChatModel := State;
  mutable var Entries: array of ChatEntry := Next.Entries;
  Std.Arrays.Push(Entries, Entry);
  Next.Entries := Entries;
  return Next
end;

// Sends the current non-empty draft and records its result.
//
// Parameters:
// - `State`: Current application state containing the draft.
function SendPrompt(State: LocalChatModel): LocalChatModel;
begin
  var Prompt: string := Std.Str.Trim(State.Draft);
  if Prompt = '' then
  begin
    mutable var Empty: LocalChatModel := State;
    Empty.Status := 'Enter a message first';
    return Empty
  end;
  mutable var Next: LocalChatModel := AppendEntry(State, ChatEntry.User(Prompt));
  Next.Draft := '';
  Next.DraftCaret := 0;
  Next.Status := 'Contacting local model…';
  case LocalChatRequest(Prompt) of
    Ok(Content):
    begin
      Next := AppendEntry(Next, ChatEntry.Assistant(Content));
      Next.Status := 'Ready'
    end;
    Error(Message):
    begin
      Next := AppendEntry(Next, ChatEntry.Failure(Message));
      Next.Status := 'Request failed'
    end
  end;

  Next.Focus := PromptControl;
  return LocalChatScrollToEnd(Next)
end;

// Reports whether a key event is the Alt+X quit shortcut.
//
// Parameters:
// - `Key`: Key event to inspect.
function IsQuitShortcut(Key: TuiKeyEvent): boolean;
begin
  return ((((Key.kind = Std.Console.KeyKind.Character) and Key.alt) and (not Key.ctrl)) and (not Key.meta)) and
         ((Key.ch = 'x') or (Key.ch = 'X'))
end;

// Applies one routed TUI message to the Local Chat application model.
//
// Parameters:
// - `State`: Current immutable application state.
// - `Msg`: Routed TUI message to process.
// - `Cmd`: Command output updated when the message requests a host action.
public function LocalChatUpdate(State: LocalChatModel; Msg: TuiMsg; Cmd: TuiCmdOutput): LocalChatModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.TextChanged(Source, Action, Text, Caret):
    begin
      if Action.Value = PromptChangedAction then
      begin
        mutable var Next: LocalChatModel := State;
        Next.Draft := Text;
        Next.DraftCaret := Caret;
        Next.Status := 'Ready';
        return Next
      end;

      return State
    end;
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, Offset):
    begin
      if Action.Value = TranscriptChangedAction then
      begin
        mutable var Next: LocalChatModel := State;
        Next.TranscriptCaret := Caret;
        Next.TranscriptOffset := Offset;
        return Next
      end;

      return State
    end;
    TuiMsg.Action(Source, Action):
    begin
      if Action.Value = SendAction then
      begin
        return SendPrompt(State)
      end;

      return State
    end;
    TuiMsg.Key(Key):
    begin
      if IsQuitShortcut(Key) then
      begin
        Cmd.Set(TuiCmd.Quit)
      end;

      return State
    end;
    TuiMsg.Resize(Size):
    begin
      mutable var Next: LocalChatModel := State;
      Next.Width := Size.Width;
      Next.Height := Size.Height;
      return LocalChatScrollToEnd(Next)
    end;
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(CurrentId):
        begin
          mutable var Next: LocalChatModel := State;
          Next.Focus := CurrentId.Value;
          return Next
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.QuitRequested:
    begin
      return State
    end;
    TuiMsg.Pointer(Pointer):
    begin
      return State
    end;
    TuiMsg.Tick(Delta):
    begin
      return State
    end;
    TuiMsg.SelectionChanged(Source, Action, Selected):
    begin
      return State
    end;
    TuiMsg.CheckChanged(CheckSource, CheckAction, Checked):
    begin
      return State
    end;
    TuiMsg.ScrollChanged(ScrollSource, ScrollAction, ScrollOffset):
    begin
      return State
    end;
    TuiMsg.MenuChanged(MenuSource, MenuAction, MenuState):
    begin
      return State
    end
    else
    begin
      return State
    end
  end
end;

// Responsive TUI element construction for the Local Chat application.
unit LocalChat.View;

uses LocalChat.Model, Std.Options, Std.Tui;

const
  // Identifier of the prompt input control.
  PromptControl: integer := 1;
  // Identifier of the transcript text area.
  TranscriptControl: integer := 2;
  // Action emitted when the prompt text changes.
  PromptChangedAction: integer := 1;
  // Action emitted when the transcript viewport changes.
  TranscriptChangedAction: integer := 2;
  // Action emitted by the send button.
  SendAction: integer := 10;

// Wraps one child in an expanding layout element.
//
// Parameters:
// - `Child`: Element placed inside the layout wrapper.
// - `Stretch`: Relative space assigned by the parent layout.
function Expanding(Child: TuiElement; Stretch: integer): TuiElement;
begin
  return TuiElementBuilders.MakeLayout(TuiLayoutSettings.Create(TuiMargins.Uniform(0), TuiSizePolicy.Expanding(), TuiAlignment.Fill(), Stretch), Child)
end;

// Builds the application header rule.
function Header(): TuiElement;
begin
  return TuiElementBuilders.MakeRule(' LOCAL CHAT  ·  llama.cpp  ·  one prompt per request ')
end;

// Builds the read-only transcript panel.
//
// Parameters:
// - `State`: Current application state rendered by the panel.
function Transcript(State: LocalChatModel): TuiElement;
begin
  var Content: TuiElement := TuiElementBuilders.MakeTextArea(TuiControlId.Create(TranscriptControl), LocalChatTranscript(State), State.TranscriptCaret, State.TranscriptOffset, TuiAction.Create(TranscriptChangedAction));
  return TuiElementBuilders.MakePanel('Conversation', [Expanding(Content, 1)])
end;

// Builds the prompt input and send-button panel.
//
// Parameters:
// - `State`: Current application state rendered by the composer.
function Composer(State: LocalChatModel): TuiElement;
begin
  var Prompt: TuiElement := TuiElementBuilders.MakeInputWithHint(TuiControlId.Create(PromptControl), State.Draft, State.DraftCaret, 'Message the local model…', TuiAction.Create(PromptChangedAction));
  var Send: TuiElement := TuiElementBuilders.MakeDefaultButton(TuiControlId.Create(3), 'Send', 'S', TuiAction.Create(SendAction));
  return TuiElementBuilders.MakePanel('Message', [
                                                   TuiElementBuilders.MakeRow([Expanding(Prompt, 1), Send])
                                                 ])
end;

// Builds the footer status line and keyboard hints.
//
// Parameters:
// - `State`: Current application state providing status text.
function Status(State: LocalChatModel): TuiElement;
begin
  return TuiElementBuilders.MakeStatusLine([
                                             TuiStatusItemBuilders.MakeHint(State.Status),
                                             TuiStatusItemBuilders.MakeKeyHint('Enter', 'send'),
                                             TuiStatusItemBuilders.MakeKeyHint('Tab', 'focus'),
                                             TuiStatusItemBuilders.MakeKeyHint('Alt+X', 'quit')
                                           ])
end;

// Builds the responsive Local Chat element tree for one model state.
//
// Parameters:
// - `State`: Current application state to render.
public function LocalChatView(State: LocalChatModel): TuiElement;
begin
  if (State.Width < 50) or (State.Height < 14) then
  begin
    return TuiElementBuilders.MakeDesktop(None, [
                                                  TuiElementBuilders.MakePanel('Local Chat', [
                                                                                               TuiElementBuilders.MakeLabel('Terminal too small'),
                                                                                               TuiElementBuilders.MakeLabel('Use at least 50 × 14 cells.')
                                                                                             ])
                                                ])
  end;

  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(State.Focus)), [
                                                                                  TuiElementBuilders.MakeColumn([
                                                                                                                  Header(),
                                                                                                                  Expanding(Transcript(State), 1),
                                                                                                                  Composer(State),
                                                                                                                  Status(State)
                                                                                                                ])
                                                                                ])
end;

// Starts the fixed-endpoint Local Chat terminal application.
program LocalChat;

uses LocalChat.Model, LocalChat.Theme, LocalChat.Update, LocalChat.View, Std.Console, Std.Tui;

begin
  var Initial: LocalChatModel := LocalChatModelCreate(Std.Console.ScreenWidth(), Std.Console.ScreenHeight());
  TuiApplication.RunWithPalette(Initial, LocalChatUpdate, LocalChatView, LocalChatPalette())
end.

// Controlled text proposals and selection updates for Notes.
unit Notes.Editing;

uses Notes.Model, Std.Arrays, Std.Conv, Std.Tui;

const
  SearchChangedAction: integer := 1;
  TitleChangedAction: integer := 3;
  TagsChangedAction: integer := 4;
  BodyChangedAction: integer := 5;

// Reports whether the selection refers to an existing note.
public function NotesHasSelection(State: NotesModel): boolean;
begin
  return (State.Selected >= 0) and (State.Selected < Std.Arrays.Length(State.Notes))
end;

// Replaces one note while preserving the remaining model state.
public function NotesWithNote(State: NotesModel; Index: integer; NoteValue: Note): NotesModel;
begin
  mutable var Notes: array of Note := State.Notes;
  Notes[Index] := NoteValue;
  mutable var Next: NotesModel := State;
  Next.Notes := Notes;
  return Next
end;

function SameTags(Left: array of string; Right: array of string): boolean;
begin
  if Std.Arrays.Length(Left) <> Std.Arrays.Length(Right) then
  begin
    return false
  end;

  for Index: integer := 0 to Std.Arrays.Length(Left) - 1 do
  begin
    if Left[Index] <> Right[Index] then
    begin
      return false
    end
  end;

  return true
end;

// Applies a single-line proposal, preserving clean state for caret-only changes.
public function NotesEditText(State: NotesModel; Action: integer; Text: string; Caret: integer): NotesModel;
begin
  mutable var Next: NotesModel := State;
  if Action = SearchChangedAction then
  begin
    Next.Search := Text;
    Next.SearchCaret := Caret;
    Next.Status := IntToStr(Std.Arrays.Length(NotesFilteredIndices(Next.Notes, Text))) +
                   ' matching note(s)';
    return Next
  end;

  if (Action = TitleChangedAction) and NotesHasSelection(Next) then
  begin
    mutable var NoteValue: Note := Next.Notes[Next.Selected];
    Next.TitleCaret := Caret;
    if NoteValue.Title = Text then
    begin
      return Next
    end;

    NoteValue.Title := Text;
    Next := NotesWithNote(Next, Next.Selected, NoteValue);
    Next.Dirty := true;
    Next.Status := 'Unsaved changes';
    return Next
  end;

  if (Action = TagsChangedAction) and NotesHasSelection(Next) then
  begin
    Next.TagsText := Text;
    Next.TagsCaret := Caret;
    mutable var NoteValue: Note := Next.Notes[Next.Selected];
    var Tags: array of string := NoteTagsFromText(Text);
    if SameTags(NoteValue.Tags, Tags) then
    begin
      return Next
    end;

    NoteValue.Tags := Tags;
    Next := NotesWithNote(Next, Next.Selected, NoteValue);
    Next.Dirty := true;
    Next.Status := 'Unsaved changes';
    return Next
  end;

  return Next
end;

// Applies body text, caret and viewport changes independently.
public function NotesEditBody(
  State: NotesModel;
  Action: integer;
  Text: string;
  Caret: integer;
  Offset: TuiPoint
): NotesModel;
begin
  mutable var Next: NotesModel := State;
  if (Action = BodyChangedAction) and NotesHasSelection(Next) then
  begin
    mutable var NoteValue: Note := Next.Notes[Next.Selected];
    Next.BodyCaret := Caret;
    Next.BodyOffset := Offset;
    if NoteValue.Body = Text then
    begin
      return Next
    end;

    NoteValue.Body := Text;
    Next := NotesWithNote(Next, Next.Selected, NoteValue);
    Next.Dirty := true;
    Next.Status := 'Unsaved changes'
  end;

  return Next
end;

unit Notes.Format;

uses
  Notes.Model, Std.Arrays, Std.Conv, Std.Dictionaries, Std.Options, Std.Results, Std.Str, Std.Toml;

const
  NoteFormatVersion: integer := 1;

function MissingField(Name: string): string;
begin
  return ('Missing required note field `' + Name) + '`'
end;

function FieldString(Fields: dict of string to TomlValue; Name: string): result of string, string;
begin
  case Std.Dictionaries.Get(Fields, Name) of
    Some(Value):
    begin
      case Value of
        TomlValue.String(Text):
        begin
          return Ok(Text)
        end
        else
        begin
          return Error(('Note field `' + Name) + '` must be a string')
        end
      end
    end;
    None:
    begin
      return Error(MissingField(Name))
    end
  end
end;

function FieldInteger(Fields: dict of string to TomlValue; Name: string): result of integer, string;
begin
  case Std.Dictionaries.Get(Fields, Name) of
    Some(Value):
    begin
      case Value of
        TomlValue.Integer(Number):
        begin
          return Ok(Number)
        end
        else
        begin
          return Error(('Note field `' + Name) + '` must be an integer')
        end
      end
    end;
    None:
    begin
      return Error(MissingField(Name))
    end
  end
end;

function FieldBoolean(Fields: dict of string to TomlValue; Name: string): result of boolean, string;
begin
  case Std.Dictionaries.Get(Fields, Name) of
    Some(Value):
    begin
      case Value of
        TomlValue.Boolean(Flag):
        begin
          return Ok(Flag)
        end
        else
        begin
          return Error(('Note field `' + Name) + '` must be a boolean')
        end
      end
    end;
    None:
    begin
      return Error(MissingField(Name))
    end
  end
end;

function FieldTags(Fields: dict of string to TomlValue): result of array of string, string;
begin
  case Std.Dictionaries.Get(Fields, 'tags') of
    Some(Value):
    begin
      case Value of
        TomlValue.ArrayValue(Items):
        begin
          mutable var Tags: array of string := [];
          for Index: integer := 0 to Std.Arrays.Length(Items) - 1 do
          begin
            case Items[Index] of
              TomlValue.String(Tag):
              begin
                Std.Arrays.Push(Tags, Tag)
              end
              else
              begin
                return Error('Every note tag must be a string')
              end
            end
          end;

          return Ok(Tags)
        end
        else
        begin
          return Error('Note field `tags` must be an array')
        end
      end
    end;
    None:
    begin
      return Error(MissingField('tags'))
    end
  end
end;

function ParseFields(Fields: dict of string to TomlValue; Body: string): result of Note, string;
begin
  var Version: integer := try FieldInteger(Fields, 'format');
  if Version <> NoteFormatVersion then
  begin
    return Error(('Unsupported note format version ' + IntToStr(Version)) + '; expected 1')
  end;
  var Id: string := try FieldString(Fields, 'id');
  if Std.Str.Trim(Id) = '' then
  begin
    return Error('Note field `id` must not be empty')
  end;
  var Title: string := try FieldString(Fields, 'title');
  var Created: integer := try FieldInteger(Fields, 'created_ms');
  var Updated: integer := try FieldInteger(Fields, 'updated_ms');
  if (Created < 0) or (Updated < 0) then
  begin
    return Error('Note timestamps must not be negative')
  end;

  return Ok(record
    Id := Id;
    Title := Title;
    CreatedMillis := Created;
    UpdatedMillis := Updated;
    Tags := try FieldTags(Fields);
    Pinned := try FieldBoolean(Fields, 'pinned');
    Archived := try FieldBoolean(Fields, 'archived');
    Body := Body;
    Path := '';
  end)
end;

// Parses one UTF-8 `.note` document with TOML frontmatter.
public function NoteParse(Text: string): result of Note, string;
begin
  var NewLine: string := Std.Str.Chr(10);
  var Source: string := Std.Str.Replace(Std.Str.Replace(Text, Std.Str.Chr(13) + NewLine, NewLine), Std.Str.Chr(13), NewLine);
  var Prefix: string := '+++' + NewLine;
  if not Std.Str.StartsWith(Source, Prefix) then
  begin
    return Error('A .note file must start with a `+++` TOML header')
  end;
  var Remaining: string := Std.Str.Substring(Source, Std.Str.Length(Prefix), Std.Str.Length(Source) -
                                                                             Std.Str.Length(Prefix));
  var Boundary: string := (NewLine + '+++') + NewLine;
  var BoundaryIndex: integer := Std.Str.IndexOf(Remaining, Boundary);
  if BoundaryIndex < 0 then
  begin
    return Error('A .note file must close its TOML header with `+++`')
  end;
  var Header: string := Std.Str.Substring(Remaining, 0, BoundaryIndex);
  var BodyStart: integer := BoundaryIndex + Std.Str.Length(Boundary);
  var Body: string := Std.Str.Substring(Remaining, BodyStart, Std.Str.Length(Remaining) - BodyStart);
  case Std.Toml.Parse(Header) of
    Ok(Value):
    begin
      case Value of
        TomlValue.Table(Fields):
        begin
          return ParseFields(Fields, Body)
        end
        else
        begin
          return Error('The .note metadata root must be a TOML table')
        end
      end
    end;
    Error(Message):
    begin
      return Error('Invalid .note TOML header: ' + Message)
    end
  end
end;

// Encodes one note as deterministic TOML frontmatter and Markdown body text.
public function NoteStringify(NoteValue: Note): string;
begin
  mutable var TagValues: array of TomlValue := [];
  for Index: integer := 0 to Std.Arrays.Length(NoteValue.Tags) - 1 do
  begin
    Std.Arrays.Push(TagValues, TomlValue.String(NoteValue.Tags[Index]))
  end;
  var Header: TomlValue := TomlValue.Table(['format': TomlValue.Integer(NoteFormatVersion), 'id': TomlValue.String(NoteValue.Id), 'title': TomlValue.String(NoteValue.Title), 'created_ms': TomlValue.Integer(NoteValue.CreatedMillis), 'updated_ms': TomlValue.Integer(NoteValue.UpdatedMillis), 'tags': TomlValue.ArrayValue(TagValues), 'pinned': TomlValue.Boolean(NoteValue.Pinned), 'archived': TomlValue.Boolean(NoteValue.Archived)]);
  var NewLine: string := Std.Str.Chr(10);
  return ((((('+++' + NewLine) + Std.Str.TrimRight(Std.Toml.Stringify(Header))) + NewLine) + '+++') + NewLine) +
         NoteValue.Body
end;

unit Notes.Model;

uses Std.Arrays, Std.Console, Std.Conv, Std.Str, Std.Tui;

public type
  // One persisted `.note` document and its source path.
  Note = record
    public Id: string;
    public Title: string;
    public CreatedMillis: integer;
    public UpdatedMillis: integer;
    public Tags: array of string;
    public Pinned: boolean;
    public Archived: boolean;
    public Body: string;
    public Path: string;
  end;
  // One note file that could not be read or parsed.
  NoteIssue = record
    public Path: string;
    public Message: string;
  end;
  // Complete result of loading one notes directory.
  NotesLoad = record
    public Notes: array of Note;
    public Issues: array of NoteIssue;
  end;
  // Visible pane in a narrow terminal.
  NotesPane = enum
    List;
    Editor;
  end;
  // Active modal layer, if any.
  NotesOverlay = enum
    Closed;
    Commands;
    Help;
    QuitConfirmation;
    SaveFailure;
  end;
  // Complete immutable application state supplied to the MVU view.
  NotesModel = record
    public Directory: string;
    public Notes: array of Note;
    public Issues: array of NoteIssue;
    public Selected: integer;
    public Search: string;
    public SearchCaret: integer;
    public TitleCaret: integer;
    public TagsText: string;
    public TagsCaret: integer;
    public BodyCaret: integer;
    public BodyOffset: TuiPoint;
    public Focus: integer;
    public Pane: NotesPane;
    public Overlay: NotesOverlay;
    public Dirty: boolean;
    public Status: string;
    public ErrorMessage: string;
    public Width: integer;
    public Height: integer;
  end;

// Creates a new unsaved note with stable identity and timestamps.
public function NoteCreate(Id: string; TimestampMillis: integer): Note;
begin
  return record
    Id := Id;
    Title := 'Untitled note';
    CreatedMillis := TimestampMillis;
    UpdatedMillis := TimestampMillis;
    Tags := [];
    Pinned := false;
    Archived := false;
    Body := '';
    Path := '';
  end
end;

// Creates initial application state from a directory load result.
public function NotesModelCreate(Directory: string; Loaded: NotesLoad): NotesModel;
begin
  mutable var Selected: integer := -1;
  mutable var Focus: integer := 1;
  mutable var Pane: NotesPane := NotesPane.List;
  mutable var Status: string := 'Ready';
  mutable var TitleCaret: integer := 0;
  mutable var TagsText: string := '';
  mutable var TagsCaret: integer := 0;
  if Std.Arrays.Length(Loaded.Notes) > 0 then
  begin
    Selected := 0;
    Focus := 3;
    Pane := NotesPane.Editor;
    TitleCaret := Std.Str.Length(Loaded.Notes[0].Title);
    TagsText := Std.Str.Join(Loaded.Notes[0].Tags, ', ');
    TagsCaret := Std.Str.Length(TagsText)
  end;

  if Std.Arrays.Length(Loaded.Issues) > 0 then
  begin
    Status := IntToStr(Std.Arrays.Length(Loaded.Issues)) + ' invalid note file(s)'
  end;

  return record
    Directory := Directory;
    Notes := Loaded.Notes;
    Issues := Loaded.Issues;
    Selected := Selected;
    Search := '';
    SearchCaret := 0;
    TitleCaret := TitleCaret;
    TagsText := TagsText;
    TagsCaret := TagsCaret;
    BodyCaret := 0;
    BodyOffset := TuiPoint.Create(0, 0);
    Focus := Focus;
    Pane := Pane;
    Overlay := NotesOverlay.Closed;
    Dirty := false;
    Status := Status;
    ErrorMessage := '';
    Width := 100;
    Height := 30;
  end
end;

// Formats a note's tags for the controlled metadata input.
public function NoteTagsText(NoteValue: Note): string;
begin
  return Std.Str.Join(NoteValue.Tags, ', ')
end;

// Parses, trims, and deduplicates comma-separated tags.
public function NoteTagsFromText(Text: string): array of string;
begin
  mutable var Tags: array of string := [];
  var Parts: array of string := Std.Str.Split(Text, ',');
  for Index: integer := 0 to Std.Arrays.Length(Parts) - 1 do
  begin
    var Tag: string := Std.Str.Trim(Parts[Index]);
    if (Tag <> '') and (not Std.Arrays.Contains(Tags, Tag)) then
    begin
      Std.Arrays.Push(Tags, Tag)
    end
  end;

  return Tags
end;

// Reports whether an active note matches a case-insensitive query.
public function NoteMatches(NoteValue: Note; Search: string): boolean;
begin
  var Query: string := Std.Str.ToLower(Std.Str.Trim(Search));
  if Query = '' then
  begin
    return not NoteValue.Archived
  end;

  if NoteValue.Archived then
  begin
    return false
  end;

  return (Std.Str.Contains(Std.Str.ToLower(NoteValue.Title), Query) or Std.Str.Contains(Std.Str.ToLower(NoteValue.Body), Query)) or
         Std.Str.Contains(Std.Str.ToLower(NoteTagsText(NoteValue)), Query)
end;

// Returns source-array indices for all visible filtered notes.
public function NotesFilteredIndices(Notes: array of Note; Search: string): array of integer;
begin
  mutable var Indices: array of integer := [];
  for Index: integer := 0 to Std.Arrays.Length(Notes) - 1 do
  begin
    if NoteMatches(Notes[Index], Search) then
    begin
      Std.Arrays.Push(Indices, Index)
    end
  end;

  return Indices
end;

function ClipListText(Text: string; MaximumWidth: integer): string;
begin
  if MaximumWidth <= 0 then
  begin
    return ''
  end;

  if Std.Console.DisplayWidth(Text) <= MaximumWidth then
  begin
    return Text
  end;

  if MaximumWidth = 1 then
  begin
    return '…'
  end;
  mutable var Clipped: string := '';
  mutable var Width: integer := 0;
  var ContentWidth: integer := MaximumWidth - 1;
  for Grapheme: string in Std.Console.SplitGraphemes(Text) do
  begin
    var GraphemeWidth: integer := Std.Console.DisplayWidth(Grapheme);
    if Width + GraphemeWidth > ContentWidth then
    begin
      return Clipped + '…'
    end;

    Clipped := Clipped + Grapheme;
    Width := Width + GraphemeWidth
  end;

  return Clipped
end;

// Builds width-bounded list labels for all visible filtered notes.
public function NotesListItems(Notes: array of Note; Search: string; MaximumWidth: integer): array of string;
begin
  mutable var Items: array of string := [];
  var Indices: array of integer := NotesFilteredIndices(Notes, Search);
  for Index: integer := 0 to Std.Arrays.Length(Indices) - 1 do
  begin
    var NoteValue: Note := Notes[Indices[Index]];
    mutable var Prefix: string := '  ';
    if NoteValue.Pinned then
    begin
      Prefix := '★ '
    end;
    mutable var Tags: string := NoteTagsText(NoteValue);
    if Tags <> '' then
    begin
      Tags := '  ·  ' + Tags
    end;

    Std.Arrays.Push(Items, ClipListText((Prefix + NoteValue.Title) + Tags, MaximumWidth))
  end;

  return Items
end;

unit Notes.Repository;

uses
  Notes.Format, Notes.Model, Std.Arrays, Std.Conv, Std.Fs, Std.Path, Std.Random, Std.Results,
  Std.Str, Std.Time;

// Creates the notes directory or validates that it already exists.
public function NotesEnsureDirectory(Directory: string): result of boolean, string;
begin
  if Std.Fs.Exists(Directory) then
  begin
    if Std.Fs.IsDir(Directory) then
    begin
      return Ok(true)
    end;

    return Error('Notes path exists but is not a directory: ' + Directory)
  end;

  return Std.Fs.CreateDir(Directory)
end;

// Resolves a note's existing or identity-derived `.note` path.
public function NoteFilePath(Directory: string; NoteValue: Note): string;
begin
  if NoteValue.Path <> '' then
  begin
    return NoteValue.Path
  end;

  return Std.Path.Join([Directory, NoteValue.Id + '.note'])
end;

function NoteComesBefore(Left: Note; Right: Note): boolean;
begin
  if Left.Pinned <> Right.Pinned then
  begin
    return Left.Pinned
  end;

  return Left.UpdatedMillis > Right.UpdatedMillis
end;

// Sorts pinned notes first and then by descending update timestamp.
public function NotesSort(Notes: array of Note): array of Note;
begin
  mutable var Sorted: array of Note := Notes;
  for Left: integer := 0 to Std.Arrays.Length(Sorted) - 1 do
  begin
    for Right: integer := Left + 1 to Std.Arrays.Length(Sorted) - 1 do
    begin
      if NoteComesBefore(Sorted[Right], Sorted[Left]) then
      begin
        var Previous: Note := Sorted[Left];
        Sorted[Left] := Sorted[Right];
        Sorted[Right] := Previous
      end
    end
  end;

  return Sorted
end;

// Loads valid notes and preserves invalid files as visible issues.
public function NotesLoadDirectory(Directory: string): result of NotesLoad, string;
begin
  var DirectoryReady: boolean := try NotesEnsureDirectory(Directory);
  var Paths: array of string := try Std.Fs.Glob(Std.Path.Join([Directory, '*.note']));
  mutable var Notes: array of Note := [];
  mutable var Issues: array of NoteIssue := [];
  for Index: integer := 0 to Std.Arrays.Length(Paths) - 1 do
  begin
    var Path: string := Paths[Index];
    case Std.Fs.ReadText(Path) of
      Ok(Text):
      begin
        case NoteParse(Text) of
          Ok(NoteValue):
          begin
            mutable var Loaded: Note := NoteValue;
            Loaded.Path := Path;
            Std.Arrays.Push(Notes, Loaded)
          end;
          Error(Message):
          begin
            Std.Arrays.Push(Issues, record
              Path := Path;
              Message := Message;
            end)
          end
        end
      end;
      Error(Message):
      begin
        Std.Arrays.Push(Issues, record
          Path := Path;
          Message := Message;
        end)
      end
    end
  end;

  return Ok(record
    Notes := NotesSort(Notes);
    Issues := Issues;
  end)
end;

// Atomically writes one note to its stable file path.
public function NotesSave(Directory: string; NoteValue: Note): result of boolean, string;
begin
  var DirectoryReady: boolean := try NotesEnsureDirectory(Directory);
  return Std.Fs.WriteTextAtomic(NoteFilePath(Directory, NoteValue), NoteStringify(NoteValue))
end;

// Generates an unused timestamp-and-random identity in one directory.
public function NotesCreateId(Directory: string; TimestampMillis: integer): string;
begin
  mutable var Candidate: string := '';
  repeat
    Candidate := (IntToStr(TimestampMillis) + '-') + IntToStr(Std.Random.RandomInt(100000, 999999))
  until not Std.Fs.Exists(Std.Path.Join([Directory, Candidate + '.note']));
  return Candidate
end;

// Creates an in-memory draft with a new identity and current timestamp.
public function NotesCreateDraft(Directory: string): Note;
begin
  var Now: integer := Std.Time.TimestampMillis();
  return NoteCreate(NotesCreateId(Directory, Now), Now)
end;

program Notes;

uses
  Notes.Model, Notes.Repository, Notes.Theme, Notes.Update, Notes.View, Std.Args, Std.Console,
  Std.Random, Std.Tui;

function NotesDirectory(): string;
begin
  if Std.Args.ParamCount() > 0 then
  begin
    return Std.Args.ParamStr(0)
  end;

  return 'notes'
end;

begin
  Std.Random.Randomize();
  var Directory: string := NotesDirectory();
  case NotesLoadDirectory(Directory) of
    Ok(Loaded):
    begin
      mutable var Initial: NotesModel := NotesModelCreate(Directory, Loaded);
      Initial.Width := Std.Console.ScreenWidth();
      Initial.Height := Std.Console.ScreenHeight();
      TuiApplication.RunWithPalette(Initial, NotesUpdate, NotesView, NotesPalette())
    end;
    Error(Message):
    begin
      Std.Console.WriteLn('Could not open notes: ' + Message)
    end
  end
end.

# First program

## A first taste

```pascal
program Greet;

uses
  Std.Console;

function Greet(Name: string): string;
begin
  return 'Hello, ' + Name + '!';
end;

begin
  var Message: string := Greet('Pascal');
  WriteLn(Message);
end.
```

## Program structure

Every Functional Pascal program starts with a `program` declaration, optional `uses` clauses, then declarations and the main block:

```pascal
program MyApp;

uses
  Std.Console;

// constant declarations
const
  MaxItems: integer := 100;

// variable declarations
var
  Counter: integer := 0;

// function declarations
function Add(A: integer; B: integer): integer;
begin
  return A + B;
end;

// main block
begin
  WriteLn(Add(3, 4));
end.
```

The first segment `Std` in a unit name is reserved for the standard library. User-defined units use another root segment (for example `MyApp.Utils`); see [Units](../program-structure/units.md) and [Standard library](../std/README.md) for `uses` rules.

## See also

- [Functions](../language/functions/README.md)
- [Basics](../language/basics/README.md)
- [Hello world](hello-world.md)

# Fork-join

The idiomatic way to run parallel work is to spawn one task per unit of work and then wait for all results:

```pascal
program ParallelSum;
uses Std.Console, Std.Task;

function Compute(N: integer): integer;
begin
  return N * N
end;

begin
  var T1: task := go Compute(3);
  var T2: task := go Compute(4);
  WriteLn(Wait(T1) + Wait(T2))
end.
```

The Mandelbrot showcase project in `examples/math/mandelbrot/` demonstrates this pattern: one task per row, all collected in order via `Wait`, combined with a live terminal UI.

## See also

- [`go`](go.md)
- [Task handles](task-handles.md)

# Case of intro

The `case` expression may have any of the following types:

- an ordinal type: `integer`, `boolean`, `string`, or an `enum`
- `string`
- `Result of T, E` or `Option of T`

Formal syntax: [`grammar.ebnf`](../../../specs/grammar.ebnf) (`case_stmt`, `case_label`).

Simple scalar matching (integers, chars, strings, booleans, simple enums) is shown below. Guard clauses (`label if cond:`), destructuring patterns (`Ok(x)`, `Error(e)`, `Some(x)`, `None`), data-carrying enum patterns, and exhaustiveness rules are documented in [Pattern matching](../pattern-matching/README.md) and [Error handling](../error-handling/README.md).

```pascal
case Day of
  'Monday':    WriteLn('Start of week');
  'Friday':    WriteLn('Almost weekend');
  'Saturday',
  'Sunday':    WriteLn('Weekend');
else
  WriteLn('Midweek');
end;
```

With ranges:

```pascal
case Score of
  0..59:    Grade := 'F';
  60..69:   Grade := 'D';
  70..79:   Grade := 'C';
  80..89:   Grade := 'B';
  90..100:  Grade := 'A';
end;
```

## See also

- [Pattern matching](../pattern-matching/README.md)
- [Error handling](../error-handling/README.md)

# Combinators

`Std.Results` and `Std.Options` provide `Map`, `AndThen`, and `OrElse` for transforming and chaining values without manual `case` destructuring. See [`Std.Results`](../../std/result/result.md) and [`Std.Options`](../../std/result/option.md) for full API details.

```pascal
uses Std.Results, Std.Conv;

function DoubleToString(V: integer): string;
begin
  return IntToStr(V * 2)
end;

var R: Result of integer, string := Ok(21);
var M: Result of string, string := Map(R, DoubleToString);
// M = Ok('42')
```

```pascal
uses Std.Options, Std.Conv;

function PositiveToString(V: integer): Option of string;
begin
  if V > 0 then return Some(IntToStr(V))
  else return None
end;

var O: Option of integer := Some(5);
var M: Option of string := AndThen(O, PositiveToString);
// M = Some('5')
```

| Combinator | Result | Option |
|------------|--------|--------|
| `Map(V, F)` | Transform `Ok` value | Transform `Some` value |
| `AndThen(V, F)` | Chain fallible operation | Chain optional lookup |
| `OrElse(V, F)` | Recover from `Error` | Provide fallback for `None` |

## See also

- [Result](result.md)
- [Option](option.md)

# Option

`Option of T` represents a value that may be absent:

```pascal
var O: Option of integer := Some(42);
var N: Option of integer := None;
```

## Using Option

```pascal
function FindIndex(Items: array of integer; Target: integer): Option of integer;
begin
  for I: integer := 0 to Length(Items) - 1 do
    if Items[I] = Target then
      return Some(I);
  return None
end;
```

## Handling with case

```pascal
var Idx: Option of integer := FindIndex([10, 20, 30], 20);
case Idx of
  Some(I): WriteLn('Found at ' + IntToStr(I));
  None:    WriteLn('Not found');
end;
```

## See also

- [Types — Result and Option](../types/result-option-types.md)
- [Pattern matching — Result and Option](../pattern-matching/result-option-patterns.md)
- [Try operator](try.md)
- [`Std.Options`](../../std/result/option.md)

# Result

`Result of T, E` represents either a success (`Ok`) or a failure (`Error`):

```pascal
var R: Result of integer, string := Ok(42);
var E: Result of integer, string := Error('not found');
```

## Returning errors

```pascal
function Divide(A: integer; B: integer): Result of integer, string;
begin
  if B = 0 then
    return Error('Division by zero')
  else
    return Ok(A div B)
end;
```

## Handling with case

Use `case of` with destructuring to handle both branches:

```pascal
var R: Result of integer, string := Divide(10, 0);
case R of
  Ok(V):  WriteLn('Value: ' + IntToStr(V));
  Error(E): WriteLn('Error: ' + E);
end;
```

The binding variable (`V`, `E`) is scoped to its arm body.

## See also

- [Types — Result and Option](../types/result-option-types.md)
- [Pattern matching — Result and Option](../pattern-matching/result-option-patterns.md)
- [Try operator](try.md)
- [`Std.Results`](../../std/result/result.md)

# Try operator

`try` propagates errors automatically. If the expression is `Error` (for `Result`) or `None` (for `Option`), the enclosing function returns that value immediately. Otherwise, the inner value is unwrapped:

Formal syntax: [`grammar.ebnf`](../../../specs/grammar.ebnf) (`try` expression).

```pascal
function Process(A: integer; B: integer): Result of string, string;
begin
  var Quotient: integer := try Divide(A, B);
  return Ok(IntToStr(Quotient))
end;
```

`try` also works with `Option`:

```pascal
function FirstPositive(Items: array of integer): Option of integer;
begin
  var Idx: integer := try FindIndex(Items, 1);
  return Some(Items[Idx])
end;
```

## See also

- [Result](result.md)
- [Option](option.md)
- [Operators — `try` precedence](../basics/operators.md#operator-precedence)

# Declarations

Formal syntax: [`grammar.ebnf`](../../../specs/grammar.ebnf) (`function_decl`, `procedure_decl`).

## Declaration shape

```text
function Name [<T>] ( [ params ] ) : RetType ;
  // nested function | nested procedure
begin
  ...
end;

procedure Name [<T>] ( [ params ] ) ;
  // nested function | nested procedure
begin
  ...
end;
```

- The header ends with `;` before the body. The body ends with `end;` (including top-level declarations in a program or unit).
- Use `()` when there are no parameters: `function Pi(): real;`.
- Parameter lists use `;` between parameters; call sites use `,`.
- Calls always include parentheses, including calls without arguments: `Pi()` or
  `SayHello()`. A bare routine name is not call syntax.

## Functions

A function returns a value using `return`:

```pascal
function Add(A: integer; B: integer): integer;
begin
  return A + B;
end;
```

## Procedures

A procedure performs an action but returns no value:

```pascal
procedure SayHello(Name: string);
begin
  WriteLn('Hello, ' + Name + '!');
end;
```

Procedures use bare `return` to exit early without a value:

```pascal
procedure LogIfPositive(mutable Count: integer; Value: integer);
begin
  if Value <= 0 then
    return;
  Count := Count + 1;
  WriteLn('logged ', Value);
end;
```

## See also

- [Parameters](parameters.md)
- [Early return](early-return.md)

# First-class functions

Functions can be assigned to variables and passed as arguments:

```pascal
function Apply(F: function(X: integer): integer; Value: integer): integer;
begin
  return F(Value);
end;

function Double(X: integer): integer;
begin
  return X * 2;
end;

begin
  var R: integer := Apply(Double, 5);  // 10
  var Op: function(X: integer): integer := Double;
  WriteLn(Op(7));                      // 14
end.
```

Call sites pass a **named** function or procedure, a **closure expression**, a
**bound record method**, or a **variable** whose type is a function or procedure
type. Qualified routines work the same way: `Std.Console.WriteLn(...)`.

```pascal
type
  Counter = record
    Base: integer;

    function Add(Self: Counter; Value: integer): integer;
    begin
      return Self.Base + Value
    end;
  end;

begin
  var C: Counter := record Base := 10; end;
  var AddTen: function(Value: integer): integer := C.Add;
  WriteLn(AddTen(5));           // 15
  WriteLn(Apply(AddTen, 7));    // 17
end.
```

`C.Add` captures `C` by value once; calling `AddTen` supplies only the remaining
parameters. See [Record methods](../types/record-methods.md#bound-methods-as-values).

## See also

- [Function types](function-types.md)
- [Capturing closures](closures.md)
- [Record methods](../types/record-methods.md)
