program JuliaShowcase;

uses Std.Console, Std.Conv, Std.Math, Std.Options, Std.Str, Julia.Color, Julia.Render;

type
  ExplorerState = record
    CenterX: real;
    CenterY: real;
    SpanY: real;
    Jr: real;
    Ji: real;
    MaxIter: integer;
    Palette: PaletteKind;

    static function Default(): ExplorerState;
    begin
      return record
        CenterX := 0.0;
        CenterY := 0.0;
        SpanY := 2.4;
        Jr := -0.8;
        Ji := 0.156;
        MaxIter := 96;
        Palette := PaletteKind.DeepOcean;
      end
    end;

    function SpanX(Self: ExplorerState; Width: integer; Height: integer): real;
    begin
      var SafeWidth: integer := Max(Width, 1);
      var SafeHeight: integer := Max(Height, 1);
      return (Self.SpanY * (IntToReal(SafeWidth) / IntToReal(SafeHeight))) * 0.5
    end;

    function XMin(Self: ExplorerState; Width: integer; Height: integer): real;
    begin
      return Self.CenterX - (Self.SpanX(Width, Height) * 0.5)
    end;

    function XMax(Self: ExplorerState; Width: integer; Height: integer): real;
    begin
      return Self.CenterX + (Self.SpanX(Width, Height) * 0.5)
    end;

    function YMin(Self: ExplorerState): real;
    begin
      return Self.CenterY - (Self.SpanY * 0.5)
    end;

    function YMax(Self: ExplorerState): real;
    begin
      return Self.CenterY + (Self.SpanY * 0.5)
    end;

    function GetZoom(Self: ExplorerState): real;
    begin
      return 2.4 / Self.SpanY
    end;

    property Zoom: real read GetZoom;
  end;

function RenderWidth(): integer;
begin
  return Max(ScreenWidth(), 1)
end;

function RenderHeight(): integer;
begin
  return Max(ScreenHeight() - 3, 1)
end;

function ViewportCX(State: ExplorerState; W: integer; H: integer; CellX: integer): real;
begin
  var Wr: integer := Max(W - 1, 1);
  return State.XMin(W, H) +
         (IntToReal(CellX - 1) / IntToReal(Wr)) * (State.XMax(W, H) - State.XMin(W, H))
end;

function ViewportCY(State: ExplorerState; W: integer; H: integer; CellY: integer): real;
begin
  var Hr: integer := Max(H - 1, 1);
  return State.YMax() - (IntToReal(CellY - 1) / IntToReal(Hr)) * (State.YMax() - State.YMin())
end;

procedure WriteHudText(Text: string; Width: integer);
begin
  if Width > 0 then
  begin
    var TextLength: integer := Min(Std.Str.Length(Text), Width);
    if TextLength > 0 then
    begin
      WriteText(Substring(Text, 0, TextLength))
    end
  end
end;

procedure DrawHud(S: ExplorerState; Width: integer; Height: integer);
begin
  Window(1, 1, ScreenWidth(), ScreenHeight());
  var HudTop: integer := Max(ScreenHeight() - 2, 1);
  Window(1, HudTop, ScreenWidth(), ScreenHeight());
  NormVideo();
  ClrScr();
  GotoXY(1, 1);
  TextColorRGB(255, 220, 120);
  var Title: string := 'Functional Pascal Julia';
  WriteHudText(Title, Width);
  TextColorRGB(156, 204, 255);
  WriteHudText('  tasks | units | records | postfix | truecolor', Max(Width - Std.Str.Length(Title), 0));
  if ScreenHeight() >= 2 then
  begin
    GotoXY(1, 2);
    NormVideo();
    WriteHudText(Format('size=%dx%d  c=(%f,%f)  jr=%f  ji=%f  zoom=%f  iter=%d  pal=%s', Width, Height, S.CenterX, S.CenterY, S.Jr, S.Ji, S.Zoom, S.MaxIter, PaletteName(S.Palette)), Width)
  end;

  if ScreenHeight() >= 3 then
  begin
    GotoXY(1, 3);
    NormVideo();
    WriteHudText('WASD=const  click  wheel  arrows  +/-  PgUp/Dn  1/2/3  R  Esc', Width)
  end;

  NormVideo();
  Window(1, 1, Width, Height)
end;

mutable var
  State: ExplorerState := ExplorerState.Default();
  RenderW: integer := 1;
  RenderH: integer := 1;
  NeedsRedraw: boolean := true;
  Quit: boolean := false;
  ActiveRender: option of RenderJob := None;

procedure RequestRedraw();
begin
  NeedsRedraw := true
end;

procedure PaintFrame();
begin
  case ActiveRender of
    Some(Job):
    begin
      StopRender(Job)
    end;
    None:
    begin
    end
  end;

  RenderW := RenderWidth();
  RenderH := RenderHeight();
  BeginFrame();
  FillRect(record
    x := 1;
    y := 1;
    width := ScreenWidth();
    height := ScreenHeight();
  end, record
    glyph := ' ';
    foreground := RgbColor(0, 0, 0);
    background := RgbColor(0, 0, 0);
  end);
  ActiveRender := Some(StartRender(State.XMin(RenderW, RenderH), State.XMax(RenderW, RenderH), State.YMin(), State.YMax(), RenderW, RenderH, State.MaxIter, State.Palette, State.Jr, State.Ji));
  DrawHud(State, RenderW, RenderH);
  Present()
end;

function HandleKey(Key: KeyEvent): boolean;
begin
  var StepX: real := State.SpanX(RenderW, RenderH) * 0.14;
  var StepY: real := State.SpanY * 0.14;
  if Key.kind = KeyKind.Escape then
  begin
    Quit := true;
    return true
  end
  else if Key.kind = KeyKind.Left then
  begin
    State.CenterX := State.CenterX - StepX;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Right then
  begin
    State.CenterX := State.CenterX + StepX;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Up then
  begin
    State.CenterY := State.CenterY + StepY;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Down then
  begin
    State.CenterY := State.CenterY - StepY;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.PageUp then
  begin
    State.MaxIter := Min(State.MaxIter + 32, 2048);
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.PageDown then
  begin
    State.MaxIter := Max(State.MaxIter - 32, 32);
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Character then
  begin
    case Key.ch of
      '+', '=':
      begin
        State.SpanY := Max(State.SpanY * 0.82, 0.000001);
        RequestRedraw();
        return true
      end;
      '-':
      begin
        State.SpanY := Min(State.SpanY / 0.82, 3.5);
        RequestRedraw();
        return true
      end;
      '1':
      begin
        State.Palette := PaletteKind.DeepOcean;
        RequestRedraw();
        return true
      end;
      '2':
      begin
        State.Palette := PaletteKind.Ember;
        RequestRedraw();
        return true
      end;
      '3':
      begin
        State.Palette := PaletteKind.Aurora;
        RequestRedraw();
        return true
      end;
      'a', 'A':
      begin
        State.Jr := State.Jr - 0.02;
        RequestRedraw();
        return true
      end;
      'd', 'D':
      begin
        State.Jr := State.Jr + 0.02;
        RequestRedraw();
        return true
      end;
      'w', 'W':
      begin
        State.Ji := State.Ji + 0.02;
        RequestRedraw();
        return true
      end;
      's', 'S':
      begin
        State.Ji := State.Ji - 0.02;
        RequestRedraw();
        return true
      end;
      'r', 'R':
      begin
        State := ExplorerState.Default();
        RequestRedraw();
        return true
      end
    end
  end;

  return false
end;

procedure HandleMouse(InputEvent: ConsoleEvent);
begin
  var InView: boolean := (((InputEvent.mouse_x >= 1) and (InputEvent.mouse_x <= RenderW)) and (InputEvent.mouse_y >= 1)) and
                         (InputEvent.mouse_y <= RenderH);
  if InputEvent.mouse_action = MouseAction.ScrollUp then
  begin
    State.SpanY := Max(State.SpanY * 0.88, 0.000001);
    RequestRedraw()
  end
  else if InputEvent.mouse_action = MouseAction.ScrollDown then
  begin
    State.SpanY := Min(State.SpanY / 0.88, 3.5);
    RequestRedraw()
  end
  else if InView and (InputEvent.mouse_action = MouseAction.Down) then
  begin
    if InputEvent.mouse_button = MouseButton.Left then
    begin
      State.CenterX := ViewportCX(State, RenderW, RenderH, InputEvent.mouse_x);
      State.CenterY := ViewportCY(State, RenderW, RenderH, InputEvent.mouse_y);
      RequestRedraw()
    end
    else if InputEvent.mouse_button = MouseButton.Middle then
    begin
      State := ExplorerState.Default();
      RequestRedraw()
    end
  end
end;

procedure HandleResize(Width: integer; Height: integer);
begin
  var NewW: integer := Max(Width, 1);
  var NewH: integer := Max(Height - 3, 1);
  if (NewW <> RenderW) or (NewH <> RenderH) then
  begin
    RenderW := NewW;
    RenderH := NewH;
    RequestRedraw()
  end
end;

procedure HandleEvent(E: ConsoleEvent);
begin
  if E.kind = EventKind.Key then
  begin
    HandleKey(E.key)
  end
  else if E.kind = EventKind.Mouse then
  begin
    HandleMouse(E)
  end
  else if E.kind = EventKind.Resize then
  begin
    HandleResize(E.width, E.height)
  end
end;

procedure ShutdownTerminal();
begin
  CursorOn();
  DisablePaste();
  DisableFocus();
  DisableMouse();
  DisableRawMode();
  LeaveAltScreen()
end;

begin
  EnableRawMode();
  EnterAltScreen();
  EnableMouse();
  EnableFocus();
  EnablePaste();
  CursorOff();
  RenderW := RenderWidth();
  RenderH := RenderHeight();
  NeedsRedraw := true;
  while not Quit do
  begin
    if NeedsRedraw then
    begin
      PaintFrame();
      NeedsRedraw := false
    end;

    case ActiveRender of
      Some(Job):
      begin
        BeginFrame();
        PollRender(Job);
        Present()
      end;
      None:
      begin
      end
    end;

    case ReadEventTimeout(16) of
      Some(E):
      begin
        HandleEvent(E)
      end;
      None:
      begin
      end
    end
  end;

  case ActiveRender of
    Some(Job):
    begin
      StopRender(Job)
    end;
    None:
    begin
    end
  end;

  ShutdownTerminal()
end.

unit Julia.Compute;

uses Std.Task, Std.Math, Std.Conv, Std.Arrays;

type
  Complex = record
    public Re: real;
    public Im: real;

    public static function Create(Re: real; Im: real): Complex;
    begin
      return record
        Re := Re;
        Im := Im;
      end
    end;

    public function Sq(Self: Complex): Complex;
    begin
      return record
        Re := Self.Re * Self.Re - Self.Im * Self.Im;
        Im := (2.0 * Self.Re) * Self.Im;
      end
    end;

    public function Add(Self: Complex; Other: Complex): Complex;
    begin
      return record
        Re := Self.Re + Other.Re;
        Im := Self.Im + Other.Im;
      end
    end;

    public function MagSq(Self: Complex): real;
    begin
      return Self.Re * Self.Re + Self.Im * Self.Im
    end;
  end;

public type
  PixelSample = record
    public IsInside: boolean;
    public EscapeValue: real;
  end;

function Iterate(Z0: Complex; C: Complex; MaxIter: integer; Token: CancellationToken): PixelSample;
begin
  var EscapeRadiusSq: real := 256.0;
  mutable var Z: Complex := Z0;
  mutable var N: integer := 0;
  while (N < MaxIter) and (Z.MagSq() <= EscapeRadiusSq) do
  begin
    if (N mod 32 = 0) and IsCancellationRequested(Token) then
    begin
      break
    end;

    Z := Z.Sq().Add(C);
    N := N + 1
  end;

  if N >= MaxIter then
  begin
    return record
      IsInside := true;
      EscapeValue := 0.0;
    end
  end;
  var MagnitudeSq: real := Max(Z.MagSq(), 4.0);
  var Smooth: real := (IntToReal(N) + 1.0) - (Log(Log(MagnitudeSq) * 0.5) / Log(2.0));
  return record
    IsInside := false;
    EscapeValue := Smooth;
  end
end;

// Compute one row, returning an empty array when cancellation is observed.
public function ComputeRow(
  Py: integer;
  Width: integer;
  Height: integer;
  XMin: real;
  XMax: real;
  YMin: real;
  YMax: real;
  MaxIter: integer;
  Jr: real;
  Ji: real;
  Token: CancellationToken
): array of PixelSample;
begin
  mutable var WidthRange: integer := Width - 1;
  mutable var HeightRange: integer := Height - 1;
  if WidthRange < 1 then
  begin
    WidthRange := 1
  end;

  if HeightRange < 1 then
  begin
    HeightRange := 1
  end;
  var Wr: real := IntToReal(WidthRange);
  var Hr: real := IntToReal(HeightRange);
  var cy: real := YMax - (Py / Hr) * (YMax - YMin);
  var C: Complex := Complex.Create(Jr, Ji);
  mutable var Row: array of PixelSample := [];
  for Px: integer := 0 to Width - 1 do
  begin
    if IsCancellationRequested(Token) then
    begin
      return []
    end;
    var cx: real := XMin + (Px / Wr) * (XMax - XMin);
    Push(Row, Iterate(Complex.Create(cx, cy), C, MaxIter, Token))
  end;

  if IsCancellationRequested(Token) then
  begin
    return []
  end;

  return Row
end;

unit Julia.Render;

uses
  Std.Console, Std.Task, Std.Arrays, Std.Conv, Std.Math, Std.Str, Std.Results, Julia.Color,
  Julia.Compute;

public type
  RenderRow = record
    public Y: integer;
    public Samples: array of PixelSample;
  end;

function EscapeGlyph(EscapeValue: real): string;
begin
  var Ramp: string := ' ░▒▓█';
  var Count: integer := Std.Str.Length(Ramp);
  var Phase: real := Frac(EscapeValue * 0.08);
  var Index: integer := Clamp(Trunc(Phase * IntToReal(Count)), 0, Count - 1);
  return CharAt(Ramp, Index)
end;

function RenderCell(Sample: PixelSample; Palette: PaletteKind): Cell;
begin
  if Sample.IsInside then
  begin
    var CellShade: Color := InsideColor();
    return record
      glyph := ' ';
      foreground := CellShade;
      background := CellShade;
    end
  end;

  return record
    glyph := EscapeGlyph(Sample.EscapeValue);
    foreground := EscapeColor(Palette, Sample.EscapeValue);
    background := RgbColor(0, 0, 0);
  end
end;

procedure DrawRow(Row: array of PixelSample; Width: integer; Y: integer; Palette: PaletteKind);
begin
  var CurrentWidth: integer := ScreenWidth();
  mutable var DrawWidth: integer := Width;
  if DrawWidth > CurrentWidth then
  begin
    DrawWidth := CurrentWidth
  end;

  if DrawWidth < 1 then
  begin
    return
  end;
  mutable var Cells: array of Cell := [];
  for Px: integer := 0 to DrawWidth - 1 do
  begin
    Push(Cells, RenderCell(Row[Px], Palette))
  end;

  WriteCells(1, Y, Cells)
end;

public type
  // A render owns four workers and at most four queued rows.
  RenderJob = record
    public Group: TaskGroup;
    public Rows: channel of RenderRow;
    public Width: integer;
    public Palette: PaletteKind;
  end;

// Start a bounded render. Each worker owns every fourth row.
public function StartRender(
  XMin: real;
  XMax: real;
  YMin: real;
  YMax: real;
  Width: integer;
  Height: integer;
  MaxIter: integer;
  Palette: PaletteKind;
  Jr: real;
  Ji: real
): RenderJob;
begin
  var Group: TaskGroup := CreateTaskGroup();
  var Rows: channel of RenderRow := CreateChannel(4);
  for Worker: integer := 0 to 3 do
  begin
    StartTaskInGroup(Group, procedure(Token: CancellationToken) begin
      mutable var Py: integer := Worker;
      while (Py < Height) and not IsCancellationRequested(Token) do
      begin
        var Samples: array of PixelSample := ComputeRow(Py, Width, Height, XMin, XMax, YMin, YMax, MaxIter, Jr, Ji, Token);
        if IsCancellationRequested(Token) then
        begin
          return
        end;
        var Row: RenderRow := record
          Y := Py;
          Samples := Samples;
        end;

        if IsError(SendWithCancellation(Rows, Row, Token)) then
        begin
          return
        end;

        Py := Py + 4
      end
    end)
  end;

  return record
    Group := Group;
    Rows := Rows;
    Width := Width;
    Palette := Palette;
  end
end;

// Draw a bounded batch on the terminal-owning task without waiting for workers.
public procedure PollRender(Job: RenderJob);
begin
  for Index: integer := 1 to 4 do
  begin
    case Std.Results.Unwrap(TryReceive(Job.Rows)) of
      Some(Row):
      begin
        if (Row.Y + 1) <= Max(ScreenHeight() - 3, 1) then
        begin
          DrawRow(Row.Samples, Job.Width, Row.Y + 1, Job.Palette)
        end
      end;
      None:
      begin
        return
      end
    end
  end
end;

// Cancel CPU work and blocked sends before releasing the old queue.
// Joining first prevents old rows from appearing in a replacement render.
public procedure StopRender(Job: RenderJob);
begin
  var Failures: array of TaskFailure := CloseTaskGroup(Job.Group);
  CloseChannel(Job.Rows);
  if Std.Arrays.Length(Failures) <> 0 then
  begin
    panic(Failures[0].Message)
  end
end;

