        State.Palette := PaletteKind.DeepOcean;
        RequestRedraw();
        return true
      end;
      '2':
      begin
        State.Palette := PaletteKind.Ember;
        RequestRedraw();
        return true
      end;
      '3':
      begin
        State.Palette := PaletteKind.Aurora;
        RequestRedraw();
        return true
      end;
      'r', 'R':
      begin
        State := ExplorerState.Default();
        RequestRedraw();
        return true
      end
    end
  end;

  return false
end;

procedure HandleMouse(InputEvent: ConsoleEvent);
begin
  var InView: boolean := (((InputEvent.mouse_x >= 1) and (InputEvent.mouse_x <= RenderW)) and (InputEvent.mouse_y >= 1)) and
                         (InputEvent.mouse_y <= RenderH);
  if InputEvent.mouse_action = MouseAction.ScrollUp then
  begin
    State.SpanY := Max(State.SpanY * 0.88, 0.000001);
    RequestRedraw()
  end
  else if InputEvent.mouse_action = MouseAction.ScrollDown then
  begin
    State.SpanY := Min(State.SpanY / 0.88, 4.0);
    RequestRedraw()
  end
  else if InView and (InputEvent.mouse_action = MouseAction.Down) then
  begin
    if InputEvent.mouse_button = MouseButton.Left then
    begin
      State.CenterX := ViewportCX(State, RenderW, RenderH, InputEvent.mouse_x);
      State.CenterY := ViewportCY(State, RenderW, RenderH, InputEvent.mouse_y);
      RequestRedraw()
    end
    else if InputEvent.mouse_button = MouseButton.Middle then
    begin
      State := ExplorerState.Default();
      RequestRedraw()
    end
  end
end;

procedure HandleResize(Width: integer; Height: integer);
begin
  var NewW: integer := Max(Width, 1);
  var NewH: integer := Max(Height - 2, 1);
  if (NewW <> RenderW) or (NewH <> RenderH) then
  begin
    RenderW := NewW;
    RenderH := NewH;
    RequestRedraw()
  end
end;

procedure HandleEvent(E: ConsoleEvent);
begin
  if E.kind = EventKind.Key then
  begin
    HandleKey(E.key)
  end
  else if E.kind = EventKind.Mouse then
  begin
    HandleMouse(E)
  end
  else if E.kind = EventKind.Resize then
  begin
    HandleResize(E.width, E.height)
  end
end;

procedure ShutdownTerminal();
begin
  CursorOn();
  DisablePaste();
  DisableFocus();
  DisableMouse();
  DisableRawMode();
  LeaveAltScreen()
end;

begin
  EnableRawMode();
  EnterAltScreen();
  EnableMouse();
  EnableFocus();
  EnablePaste();
  CursorOff();
  RenderW := RenderWidth();
  RenderH := RenderHeight();
  NeedsRedraw := true;
  while not Quit do
  begin
    if NeedsRedraw then
    begin
      PaintFrame();
      NeedsRedraw := false
    end;

    case ReadEventTimeout(16) of
      Some(E):
      begin
        HandleEvent(E)
      end;
      None:
      begin
      end
    end
  end;

  ShutdownTerminal()
end.

// Built only via tricorn.fpasprj — not a standalone program.

unit Tricorn.Render;

uses Std.Console, Std.Task, Std.Arrays, Std.Conv, Std.Math, Std.Str, Tricorn.Color;

type
  Complex = record
    public Re: real;
    public Im: real;

    public static function Zero(): Complex;
    begin
      return record
        Re := 0.0;
        Im := 0.0;
      end
    end;

    public static function Create(Re: real; Im: real): Complex;
    begin
      return record
        Re := Re;
        Im := Im;
      end
    end;

    public function Conj(Self: Complex): Complex;
    begin
      return record
        Re := Self.Re;
        Im := - Self.Im;
      end
    end;

    public function Sq(Self: Complex): Complex;
    begin
      return record
        Re := Self.Re * Self.Re - Self.Im * Self.Im;
        Im := (2.0 * Self.Re) * Self.Im;
      end
    end;

    public function Add(Self: Complex; Other: Complex): Complex;
    begin
      return record
        Re := Self.Re + Other.Re;
        Im := Self.Im + Other.Im;
      end
    end;

    public function MagSq(Self: Complex): real;
    begin
      return Self.Re * Self.Re + Self.Im * Self.Im
    end;
  end;
  PixelSample = record
    public IsInside: boolean;
    public EscapeValue: real;
  end;

function Iterate(C: Complex; MaxIter: integer): PixelSample;
begin
  var EscapeRadiusSq: real := 256.0;
  mutable var Z: Complex := Complex.Zero();
  mutable var N: integer := 0;
  while (N < MaxIter) and (Z.MagSq() <= EscapeRadiusSq) do
  begin
    Z := Z.Conj().Sq().Add(C);
    N := N + 1
  end;

  if N >= MaxIter then
  begin
    return record
      IsInside := true;
      EscapeValue := 0.0;
    end
  end;
  var MagnitudeSq: real := Max(Z.MagSq(), 4.0);
  var Smooth: real := (IntToReal(N) + 1.0) - (Log(Log(MagnitudeSq) * 0.5) / Log(2.0));
  return record
    IsInside := false;
    EscapeValue := Smooth;
  end
end;

function ComputeRow(
  Py: integer;
  Width: integer;
  Height: integer;
  XMin: real;
  XMax: real;
  YMin: real;
  YMax: real;
  MaxIter: integer
): array of PixelSample;
begin
  mutable var WidthRange: integer := Width - 1;
  mutable var HeightRange: integer := Height - 1;
  if WidthRange < 1 then
  begin
    WidthRange := 1
  end;

  if HeightRange < 1 then
  begin
    HeightRange := 1
  end;
  var Wr: real := IntToReal(WidthRange);
  var Hr: real := IntToReal(HeightRange);
  var cy: real := YMax - (Py / Hr) * (YMax - YMin);
  mutable var Row: array of PixelSample := [];
  for Px: integer := 0 to Width - 1 do
  begin
    var cx: real := XMin + (Px / Wr) * (XMax - XMin);
    Push(Row, Iterate(Complex.Create(cx, cy), MaxIter))
  end;

  return Row
end;

function EscapeGlyph(EscapeValue: real): string;
begin
  var Ramp: string := ' ░▒▓█';
  var Count: integer := Std.Str.Length(Ramp);
  var Phase: real := Frac(EscapeValue * 0.08);
  var Index: integer := Clamp(Trunc(Phase * IntToReal(Count)), 0, Count - 1);
  return CharAt(Ramp, Index)
end;

function RenderCell(Sample: PixelSample; Palette: PaletteKind): Cell;
begin
  if Sample.IsInside then
  begin
    var CellShade: Color := InsideColor();
    return record
      glyph := ' ';
      foreground := CellShade;
      background := CellShade;
    end
  end;

  return record
    glyph := EscapeGlyph(Sample.EscapeValue);
    foreground := EscapeColor(Palette, Sample.EscapeValue);
    background := RgbColor(0, 0, 0);
  end
end;

procedure DrawRow(Row: array of PixelSample; Width: integer; Y: integer; Palette: PaletteKind);
begin
  var CurrentWidth: integer := ScreenWidth();
  mutable var DrawWidth: integer := Width;
  if DrawWidth > CurrentWidth then
  begin
    DrawWidth := CurrentWidth
  end;

  if DrawWidth < 1 then
  begin
    return
  end;
  mutable var Cells: array of Cell := [];
  for Px: integer := 0 to DrawWidth - 1 do
  begin
    Push(Cells, RenderCell(Row[Px], Palette))
  end;

  WriteCells(1, Y, Cells)
end;

public procedure Render(
  XMin: real;
  XMax: real;
  YMin: real;
  YMax: real;
  Width: integer;
  Height: integer;
  MaxIter: integer;
  Palette: PaletteKind
);
begin
  mutable var Tasks: array of task := [];
  for Py: integer := 0 to Height - 1 do
  begin
    Push(Tasks, go ComputeRow(Py, Width, Height, XMin, XMax, YMin, YMax, MaxIter))
  end;

  for Py: integer := 0 to Height - 1 do
  begin
    var Row: array of PixelSample := Wait(Tasks[Py]);
    if (Py + 1) <= Max(ScreenHeight() - 2, 1) then
    begin
      DrawRow(Row, Width, Py + 1, Palette)
    end
  end
end;

// Sends buffered and streaming HTTP requests to the local example server.
program NetworkHttpClient;

uses Std.Args, Std.Arrays, Std.Conv, Std.Console, Std.Http, Std.Net.Utf8;

// Prints one buffered response after validating its UTF-8 body.
//
// Parameters:
// - `LabelText`: Short operation label written before the response.
// - `ResponseValue`: Buffered HTTP response to display.
procedure PrintBuffered(LabelText: string; ResponseValue: Response);
begin
  case BodyText(ResponseValue) of
    Ok(Text):
    begin
      WriteLn((((LabelText + ' ') + IntToStr(ResponseValue.StatusCode)) + ': ') + Text)
    end;
    Error(Message):
    begin
      panic(Message)
    end
  end
end;

// Sends one buffered request and prints its response.
//
// Parameters:
// - `LabelText`: Short operation label written before the response.
// - `RequestValue`: Complete request to send.
procedure RunBuffered(LabelText: string; RequestValue: Request);
begin
  case Send(RequestValue) of
    Ok(ResponseValue):
    begin
      PrintBuffered(LabelText, ResponseValue)
    end;
    Error(Message):
    begin
      panic(Message)
    end
  end
end;

// Reads an entire bounded response stream and validates its UTF-8 body.
//
// Parameters:
// - `StreamValue`: Open HTTP response-body stream.
function ReadAll(StreamValue: BodyStream): string;
begin
  mutable var Bytes: array of integer := [];
  mutable var Reading: boolean := true;
  while Reading do
  begin
    case ReadStream(StreamValue, 5) of
      Ok(Part):
      begin
        if Std.Arrays.Length(Part) = 0 then
        begin
          Reading := false
        end
        else
        begin
          Bytes := Std.Arrays.Concat(Bytes, Part)
        end
      end;
      Error(Message):
      begin
        panic(Message)
      end
    end
  end;

  case Std.Net.Utf8.Decode(Bytes) of
    Ok(Text):
    begin
      return Text
    end;
    Error(Message):
    begin
      panic(Message)
    end
  end
end;

begin
  mutable var Port: integer := 18080;
  if ParamCount() = 1 then
  begin
    Port := StrToInt(ParamStr(0))
  end
  else if ParamCount() <> 0 then
  begin
    panic('usage: http_client.fpas -- [PORT]')
  end;
  var BaseUrl: string := 'http://127.0.0.1:' + IntToStr(Port);
  RunBuffered('GET', Request.Get(BaseUrl + '/hello'));
  mutable var PostRequest: Request := Request.Post(BaseUrl + '/echo');
  PostRequest.Headers := [Header.Create('Content-Type', 'text/plain; charset=utf-8')];
  PostRequest.Body := Std.Net.Utf8.Encode('hello from client');
  RunBuffered('POST', PostRequest);
  case OpenStream(Request.Get(BaseUrl + '/stream')) of
    Ok(ResponseValue):
    begin
      WriteLn((('STREAM ' + IntToStr(ResponseValue.StatusCode)) + ': ') +
              ReadAll(ResponseValue.Body))
    end;
    Error(Message):
    begin
      panic(Message)
    end
  end
end.

// Serves three local HTTP requests and then exits.
program NetworkHttpServer;

uses Std.Args, Std.Conv, Std.Console, Std.Http, Std.Net, Std.Net.Utf8;

// Creates a UTF-8 text response with one content-type field.
//
// Parameters:
// - `StatusCode`: HTTP status code to return.
// - `ReasonPhrase`: HTTP reason phrase to return.
// - `Text`: UTF-8 response body.
function TextResponse(StatusCode: integer; ReasonPhrase: string; Text: string): ServerResponse;
begin
  mutable var ResponseValue: ServerResponse := ServerResponse.Create(StatusCode, ReasonPhrase);
  ResponseValue.Headers := [Header.Create('Content-Type', 'text/plain; charset=utf-8')];
  ResponseValue.Body := Std.Net.Utf8.Encode(Text);
  return ResponseValue
end;

// Routes the three requests issued by `http_client.fpas`.
//
// Parameters:
// - `RequestValue`: Validated request accepted by the server loop.
function Handle(RequestValue: ServerRequest): ServerResponse;
begin
  if (RequestValue.Method = 'GET') and (RequestValue.Target = '/hello') then
  begin
    return TextResponse(200, 'OK', 'Hello from FPAS')
  end;

  if (RequestValue.Method = 'POST') and (RequestValue.Target = '/echo') then
  begin
    case Std.Net.Utf8.Decode(RequestValue.Body) of
      Ok(Text):
      begin
        return TextResponse(200, 'OK', 'Echo: ' + Text)
      end;
      Error(Message):
      begin
        return TextResponse(400, 'Bad Request', Message)
      end
    end
  end;

  if (RequestValue.Method = 'GET') and (RequestValue.Target = '/stream') then
  begin
    return TextResponse(200, 'OK', 'streamed in small reads')
  end;

  return TextResponse(404, 'Not Found', 'No route for ' + RequestValue.Target)
end;

begin
  mutable var Port: integer := 18080;
