program SelectEvents;

uses Std.Task, Std.Console, Std.Results;

begin
  var Messages: channel of string := CreateChannel(4);
  Send(Messages, 'hello from the queue');
  var Message: WaitCase := ReceiveCase(Messages, procedure(Outcome: result of string, string) begin
    case Outcome of
      Ok(Text):
      begin
        WriteLn(Text)
      end;
      Error(Reason):
      begin
        WriteLn(Reason)
      end
    end
  end);
  var Timeout: WaitCase := TimerCase(100, procedure() begin
    WriteLn('no message before the deadline')
  end);
  Select([Message, Timeout]);
  // Both cases are now consumed; a second selection needs new cases.
  CloseChannel(Messages)
end.

program SupervisedWorker;

uses Std.Task, Std.Console, Std.Results;

begin
  var Workers: TaskGroup := CreateTaskGroup();
  // This queue models a transient failure followed by a successful operation.
  var Outcomes: channel of boolean := CreateChannel(2);
  Send(Outcomes, false);
  Send(Outcomes, true);
  var Worker: task := StartSupervisedTask(Workers, function(Token: CancellationToken): result of string, string begin
    WriteLn('Starting an attempt');
    if not Unwrap(Receive(Outcomes)) then
    begin
      return Error('temporary failure')
    end;

    return Ok('Worker completed')
  end, 2, 10);
  // Wait retrieves the final result; intermediate failures remain inside the supervisor.
  WriteLn(Unwrap(Wait(Worker)));
  CloseTaskGroup(Workers);
  CloseChannel(Outcomes)
end.

// Build first: cargo build --release -p fpas-cli
// Baseline: target/release/fpas run this-file.fpas -- 20000
// Guard: target/release/fpas run this-file.fpas -- 20000 MAX_MILLIS

program TaskArrayCallbacksBenchmark;

uses Std.Args, Std.Arrays, Std.Console, Std.Conv, Std.Task, Std.Time;

const
  WarmupIterations: integer := 20;
  ArraySize: integer := 64;
  CallbacksPerElement: integer := 3;

function Double(Value: integer): integer;
begin
  return Value * 2
end;

function IsEven(Value: integer): boolean;
begin
  return Value mod 2 = 0
end;

function Sum(Acc: integer; Value: integer): integer;
begin
  return Acc + Value
end;

function MakeValues(): array of integer;
begin
  mutable var Values: array of integer := [];
  for Index: integer := 1 to ArraySize do
  begin
    Std.Arrays.Push(Values, Index)
  end;

  return Values
end;

function RunCallbacks(Values: array of integer; Iterations: integer): integer;
begin
  mutable var Total: integer := 0;
  for Index: integer := 1 to Iterations do
  begin
    var Mapped: array of integer := Std.Arrays.Map(Values, Double);
    var Filtered: array of integer := Std.Arrays.Filter(Mapped, IsEven);
    Total := Total + Std.Arrays.Reduce(Filtered, 0, Sum)
  end;

  return Total
end;

function RunTask(Values: array of integer; Iterations: integer): integer;
begin
  var Job: task := go RunCallbacks(Values, Iterations);
  return Wait(Job)
end;

begin
  if (ParamCount() < 1) or (ParamCount() > 2) then
  begin
    panic('usage: task_array_callbacks_benchmark.fpas -- ITERATIONS [MAX_MILLIS]')
  end;
  var Iterations: integer := StrToInt(ParamStr(0));
  if Iterations < 1 then
  begin
    panic('ITERATIONS must be positive')
  end;
  mutable var MaxMillis: integer := 0;
  if ParamCount() = 2 then
  begin
    MaxMillis := StrToInt(ParamStr(1));
    if MaxMillis < 1 then
    begin
      panic('MAX_MILLIS must be positive')
    end
  end;
  var Values: array of integer := MakeValues();
  mutable var Total: integer := RunTask(Values, WarmupIterations);
  var Started: integer := MonotonicMillis();
  Total := RunTask(Values, Iterations);
  var Elapsed: integer := ElapsedMillis(Started);
  var Callbacks: integer := (Iterations * ArraySize) * CallbacksPerElement;
  mutable var OpsPerSecond: integer := 0;
  if Elapsed > 0 then
  begin
    OpsPerSecond := (Callbacks * 1000) div Elapsed
  end;

  WriteLn((('iterations: ' + IntToStr(Iterations)) + ', callbacks: ') + IntToStr(Callbacks));
  WriteLn(('elapsed: ' + IntToStr(Elapsed)) + ' ms');
  if Elapsed > 0 then
  begin
    WriteLn(('throughput: ' + IntToStr(OpsPerSecond)) + ' callbacks/s')
  end
  else
  begin
    WriteLn('throughput: unavailable (elapsed time is 0 ms)')
  end;

  WriteLn('checksum: ' + IntToStr(Total));
  if (MaxMillis > 0) and (Elapsed > MaxMillis) then
  begin
    panic(((('task-array-callbacks benchmark regression: ' + IntToStr(Elapsed)) + ' ms exceeds limit ') + IntToStr(MaxMillis)) +
          ' ms')
  end
end.

// Model a cleanup operation that needs an explicit release after cancellation.
program TaskGroupCloseTimeout;

uses Std.Task, Std.Results, Std.Console, Std.Arrays;

begin
  var Release: channel of integer := CreateChannel(1);
  var Group: TaskGroup := CreateTaskGroup();
  StartTaskInGroup(Group, procedure(Token: CancellationToken) begin
    // Intentionally not cancellable: the owner must release this cleanup gate.
    Unwrap(Receive(Release))
  end);
  case CloseTaskGroupWithTimeout(Group, 0) of
    Error(Message):
    begin
      WriteLn(Message)
    end;
    Ok(_):
    begin
      panic('Cleanup gate was not released')
    end
  end;

  Unwrap(Send(Release, 1));
  var Failures: array of TaskFailure := CloseTaskGroup(Group);
  CloseChannel(Release);
  if Length(Failures) <> 0 then
  begin
    panic('Cleanup failed')
  end;

  WriteLn('Cleanup joined; ownership released')
end.

