// HTTP orchestration for OpenAI-compatible chat completions.
unit Std.Ai.OpenAi.Client;

uses Std.Ai.OpenAi.Json, Std.Ai.OpenAi.Types, Std.Arrays, Std.Conv, Std.Http, Std.Net.Utf8, Std.Str;

// Appends the chat-completions path to a base API URL.
//
// Parameters:
// - `BaseUrl`: Base API URL with or without a trailing slash.
function CompletionUrl(BaseUrl: string): string;
begin
  if Std.Str.EndsWith(BaseUrl, '/') then
  begin
    return BaseUrl + 'chat/completions'
  end;

  return BaseUrl + '/chat/completions'
end;

// Validates, sends, and decodes one non-streaming chat completion.
//
// Parameters:
// - `ClientValue`: Endpoint, model, authorization, and response-limit settings.
// - `Messages`: Conversation messages sent in order.
// - `Options`: Optional generation controls for this completion.
public function Complete(ClientValue: Client; Messages: array of ChatMessage; Options: ChatOptions): result of string, string;
begin
  if ClientValue.BaseUrl = '' then
  begin
    return Error('OpenAI-compatible BaseUrl must not be empty')
  end;

  if ClientValue.Model = '' then
  begin
    return Error('OpenAI-compatible model name must not be empty')
  end;

  if Std.Arrays.Length(Messages) = 0 then
  begin
    return Error('OpenAI-compatible chat requires at least one message')
  end;
  mutable var Headers: array of Header := [
                                            Header.Create('Content-Type', 'application/json'),
                                            Header.Create('Accept', 'application/json')
                                          ];
  case ClientValue.ApiKey of
    Some(Value):
    begin
      if Value <> '' then
      begin
        Std.Arrays.Push(Headers, Header.Create('Authorization', 'Bearer ' + Value))
      end
    end;
    None:
    begin
    end
  end;
  mutable var RequestValue: Request := Request.Create('POST', CompletionUrl(ClientValue.BaseUrl));
  RequestValue.Headers := Headers;
  RequestValue.Body := Std.Net.Utf8.Encode(Std.Ai.OpenAi.Json.EncodeRequest(ClientValue.Model, Messages, Options));
  RequestValue.TimeoutMillis := ClientValue.TimeoutMillis;
  RequestValue.MaxResponseBytes := ClientValue.MaxResponseBytes;
  case Std.Http.Send(RequestValue) of
    Ok(ResponseValue):
    begin
      case Std.Http.BodyText(ResponseValue) of
        Ok(Text):
        begin
          if (ResponseValue.StatusCode < 200) or (ResponseValue.StatusCode >= 300) then
          begin
            return Error((('OpenAI-compatible endpoint returned HTTP ' + Std.Conv.IntToStr(ResponseValue.StatusCode)) + ': ') +
                         Text)
          end;

          return Std.Ai.OpenAi.Json.DecodeResponse(Text)
        end;
        Error(Message):
        begin
          return Error('OpenAI-compatible response body is not UTF-8: ' + Message)
        end
      end
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// JSON encoding and decoding for OpenAI-compatible chat completions.
unit Std.Ai.OpenAi.Json;

uses Std.Ai.OpenAi.Types, Std.Arrays, Std.Conv, Std.Dictionaries, Std.Json, Std.Options;

// Encodes one non-streaming chat-completion request body.
//
// Parameters:
// - `Model`: Model identifier placed in the request.
// - `Messages`: Conversation messages encoded in order.
// - `Options`: Optional generation controls to include.
public function EncodeRequest(Model: string; Messages: array of ChatMessage; Options: ChatOptions): string;
begin
  mutable var MessageValues: array of JsonValue := [];
  for Index: integer := 0 to Std.Arrays.Length(Messages) - 1 do
  begin
    Std.Arrays.Push(MessageValues, JsonValue.Object(['role': JsonValue.String(Messages[Index].Role), 'content': JsonValue.String(Messages[Index].Content)]))
  end;
  mutable var Fields: dict of string to JsonValue := ['model': JsonValue.String(Model), 'messages': JsonValue.ArrayValue(MessageValues), 'stream': JsonValue.Bool(false)];
  case Options.Temperature of
    Some(Value):
    begin
      Fields['temperature'] := JsonValue.Number(Value)
    end;
    None:
    begin
    end
  end;

  case Options.MaxTokens of
    Some(Value):
    begin
      Fields['max_tokens'] := JsonValue.Number(Std.Conv.IntToReal(Value))
    end;
    None:
    begin
    end
  end;

  return Std.Json.Stringify(JsonValue.Object(Fields))
end;

// Returns a required object field or an actionable error.
//
// Parameters:
// - `Fields`: JSON object fields to inspect.
// - `Name`: Required field name.
function RequiredField(Fields: dict of string to JsonValue; Name: string): result of JsonValue, string;
begin
  case Std.Dictionaries.Get(Fields, Name) of
    Some(Value):
    begin
      return Ok(Value)
    end;
    None:
    begin
      return Error('OpenAI-compatible response is missing field ' + Name)
    end
  end
end;

// Decodes the first assistant content value from a completion response.
//
// Parameters:
// - `Text`: Complete JSON response text.
public function DecodeResponse(Text: string): result of string, string;
begin
  case Std.Json.Parse(Text) of
    Ok(Root):
    begin
      case Root of
        JsonValue.Object(RootFields):
        begin
          case RequiredField(RootFields, 'choices') of
            Ok(ChoicesValue):
            begin
              case ChoicesValue of
                JsonValue.ArrayValue(Choices):
                begin
                  if Std.Arrays.Length(Choices) = 0 then
                  begin
                    return Error('OpenAI-compatible response contains no choices')
                  end;

                  case Choices[0] of
                    JsonValue.Object(ChoiceFields):
                    begin
                      case RequiredField(ChoiceFields, 'message') of
                        Ok(MessageValue):
                        begin
                          case MessageValue of
                            JsonValue.Object(MessageFields):
                            begin
                              case RequiredField(MessageFields, 'content') of
                                Ok(ContentValue):
                                begin
                                  case ContentValue of
                                    JsonValue.String(Content):
                                    begin
                                      return Ok(Content)
                                    end
                                    else
                                    begin
                                      return Error('OpenAI-compatible message content is not text')
                                    end
                                  end
                                end;
                                Error(Message):
                                begin
                                  return Error(Message)
                                end
                              end
                            end
                            else
                            begin
                              return Error('OpenAI-compatible choice message is not an object')
                            end
                          end
                        end;
                        Error(Message):
                        begin
                          return Error(Message)
                        end
                      end
                    end
                    else
                    begin
                      return Error('OpenAI-compatible choice is not an object')
                    end
                  end
                end
                else
                begin
                  return Error('OpenAI-compatible choices field is not an array')
                end
              end
            end;
            Error(Message):
            begin
              return Error(Message)
            end
          end
        end
        else
        begin
          return Error('OpenAI-compatible response root is not an object')
        end
      end
    end;
    Error(Message):
    begin
      return Error('Invalid OpenAI-compatible JSON response: ' + Message)
    end
  end
end;

