// Bounded HTTP response-head reading and informational-response handling.
unit Std.Http.Head;

uses Std.Arrays, Std.Http.Types, Std.Http.Wire, Std.Net;

const
  // Maximum informational responses accepted before the final response.
  MaxInterimResponses: integer := 8;

public type
  // One final response head plus bytes already read from its body.
  FinalHead = record
    // Parsed final response metadata.
    public Head: ResponseHead;
    // Body bytes read together with the response head.
    public InitialBody: array of integer;
    // Total network bytes consumed so far.
    public BytesReceived: integer;
  end;

// Reads bounded response heads and skips supported informational responses.
//
// Parameters:
// - `Connection`: Open HTTP transport connection.
// - `MaxHeaderBytes`: Maximum size of each response head.
// - `MaxResponseBytes`: Maximum total response bytes.
public function ReadFinal(
  Connection: Std.Net.Connection;
  MaxHeaderBytes: integer;
  MaxResponseBytes: integer
): result of FinalHead, string;
begin
  mutable var Buffer: array of integer := [];
  mutable var BytesReceived: integer := 0;
  mutable var InterimResponses: integer := 0;
  while true do
  begin
    mutable var Separator: integer := Std.Http.Wire.FindSeparator(Buffer, 0);
    while Separator < 0 do
    begin
      if Std.Arrays.Length(Buffer) >= MaxHeaderBytes then
      begin
        return Error('HTTP response headers exceed MaxHeaderBytes')
      end;
      var ResponseAvailable: integer := MaxResponseBytes - BytesReceived;
      if ResponseAvailable < 1 then
      begin
        return Error('HTTP response exceeds MaxResponseBytes')
      end;
      mutable var ReadMaximum: integer := MaxHeaderBytes - Std.Arrays.Length(Buffer);
      if ResponseAvailable < ReadMaximum then
      begin
        ReadMaximum := ResponseAvailable
      end;

      if ReadMaximum > 65536 then
      begin
        ReadMaximum := 65536
      end;

      case Std.Net.ReceiveBytes(Connection, ReadMaximum) of
        Ok(Bytes):
        begin
          if Std.Arrays.Length(Bytes) = 0 then
          begin
            return Error('HTTP response is missing the header terminator')
          end;

          BytesReceived := BytesReceived + Std.Arrays.Length(Bytes);
          Buffer := Std.Arrays.Concat(Buffer, Bytes)
        end;
        Error(Message):
        begin
          return Error(Message)
        end
      end;

      Separator := Std.Http.Wire.FindSeparator(Buffer, 0)
    end;

    if Separator + 4 > MaxHeaderBytes then
    begin
      return Error('HTTP response headers exceed MaxHeaderBytes')
    end;

    case Std.Http.Wire.ParseResponseHead(Buffer) of
      Ok(Head):
      begin
        if (Head.StatusCode >= 100) and (Head.StatusCode < 200) then
        begin
          if Head.StatusCode = 101 then
          begin
            return Error('HTTP 101 Switching Protocols is not supported')
          end;

          InterimResponses := InterimResponses + 1;
          if InterimResponses > MaxInterimResponses then
          begin
            return Error('HTTP response contains too many informational responses')
          end;

          Buffer := Std.Arrays.Slice(Buffer, Head.BodyOffset, Std.Arrays.Length(Buffer) -
                                                              Head.BodyOffset)
        end
        else
        begin
          var Output: FinalHead := record
            Head := Head;
            InitialBody := Std.Arrays.Slice(Buffer, Head.BodyOffset, Std.Arrays.Length(Buffer) -
                                                                     Head.BodyOffset);
            BytesReceived := BytesReceived;
          end;

          return Ok(Output)
        end
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end;

  return Error('HTTP response head loop ended unexpectedly')
end;

// Case-insensitive HTTP field lookup and unsafe-text checks.
unit Std.Http.Headers;

uses Std.Arrays, Std.Http.Types, Std.Str;

// Compares two HTTP field names without case sensitivity.
//
// Parameters:
// - `Name`: Field name to compare.
// - `Expected`: Expected field name.
public function IsName(Name: string; Expected: string): boolean;
begin
  return Std.Str.ToLower(Name) = Std.Str.ToLower(Expected)
end;

// Returns the first value for a case-insensitive field name.
//
// Parameters:
// - `Headers`: Fields to search in wire order.
// - `Name`: Case-insensitive field name.
public function Find(Headers: array of Header; Name: string): option of string;
begin
  for Index: integer := 0 to Std.Arrays.Length(Headers) - 1 do
  begin
    if IsName(Headers[Index].Name, Name) then
    begin
      return Some(Headers[Index].Value)
    end
  end;

  return None
end;

// Reports whether text contains carriage-return or line-feed characters.
//
// Parameters:
// - `Text`: Text to inspect before writing it into an HTTP head.
public function ContainsUnsafeText(Text: string): boolean;
begin
  return Std.Str.Contains(Text, #13) or Std.Str.Contains(Text, #10)
end;

// Bounded byte transfers for HTTP transports.
unit Std.Http.Io;

uses Std.Arrays, Std.Net;

// Materializes ordered response or request fragments as one byte array.
public function JoinChunks(Chunks: array of array of integer): array of integer;
begin
  return Std.Arrays.FlatMap(Chunks, function(Chunk: array of integer): array of integer begin
    return Chunk
  end)
end;

// Reads within the remaining response budget, probing only for EOF at its boundary.
public function ReadResponseBytes(Connection: Std.Net.Connection; Available: integer): result of array of integer, string;
begin
  if Available < 0 then
  begin
    return Error('HTTP response exceeds MaxResponseBytes')
  end;
  mutable var Count: integer := Available;
  if Count > 65536 then
  begin
    Count := 65536
  end;

  if Count = 0 then
  begin
    Count := 1
  end;

  case Std.Net.ReceiveBytes(Connection, Count) of
    Ok(Bytes):
    begin
      if Std.Arrays.Length(Bytes) > Available then
      begin
        return Error('HTTP response exceeds MaxResponseBytes')
      end;

      return Ok(Bytes)
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// Writes every byte or reports when the connection stops making progress.
//
// Parameters:
// - `Connection`: Open TCP or TLS connection.
// - `Bytes`: Complete byte sequence to write.
public function WriteAll(Connection: Std.Net.Connection; Bytes: array of integer): result of boolean, string;
begin
  mutable var Offset: integer := 0;
  while Offset < Std.Arrays.Length(Bytes) do
  begin
    mutable var Count: integer := Std.Arrays.Length(Bytes) - Offset;
    if Count > 1048576 then
    begin
      Count := 1048576
    end;
    var Remaining: array of integer := Std.Arrays.Slice(Bytes, Offset, Count);
    case Std.Net.SendBytes(Connection, Remaining) of
      Ok(Count):
      begin
