        begin
          return Error('Network connection stopped while writing HTTP bytes')
        end;

        Offset := Offset + Count
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end;

  return Ok(true)
end;

// HTTP method and field-name token validation.
