  for Index: integer := 0 to Std.Str.Length(Method) - 1 do
  begin
    var Code: integer := Std.Str.Ord(Std.Str.CharAt(Method, Index));
    if (((Code >= 48) and (Code <= 57)) or ((Code >= 65) and (Code <= 90))) or
       ((Code >= 97) and (Code <= 122)) then
    begin
      continue
    end;

    case Code of
      33, 35, 36, 37, 38, 39, 42, 43, 45, 46, 94, 95, 96, 124, 126:
      begin
      end
      else
      begin
        return false
      end
    end
  end;

  return true
end;

// Bounded HTTP/1.x request parsing and HTTP/1.1 response writing.
unit Std.Http.Server;

uses
  Std.Arrays, Std.Conv, Std.Http.BodyFraming, Std.Http.Fields, Std.Http.Headers, Std.Http.Io,
  Std.Http.Method, Std.Http.Types, Std.Http.Wire, Std.Net, Std.Net.Utf8, Std.Str;

// Reads through the HTTP head terminator within a byte limit.
//
// Parameters:
// - `Connection`: Accepted TCP or TLS connection.
// - `Maximum`: Maximum request-head size in bytes.
function ReadHead(Connection: Std.Net.Connection; Maximum: integer): result of array of integer, string;
begin
  mutable var Bytes: array of integer := [];
  while Std.Http.Wire.FindSeparator(Bytes, 0) < 0 do
  begin
    if Std.Arrays.Length(Bytes) >= Maximum then
    begin
      return Error('HTTP request headers exceed MaxHeaderBytes')
    end;
    mutable var ReadMaximum: integer := Maximum - Std.Arrays.Length(Bytes);
    if ReadMaximum > 65536 then
    begin
      ReadMaximum := 65536
    end;

    case Std.Net.ReceiveBytes(Connection, ReadMaximum) of
      Ok(Chunk):
      begin
        if Std.Arrays.Length(Chunk) = 0 then
        begin
          return Error('HTTP request is missing the header terminator')
        end;

        Bytes := Std.Arrays.Concat(Bytes, Chunk)
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end;

  return Ok(Bytes)
end;

// Parses and validates an HTTP/1.0 or HTTP/1.1 request line.
//
// Parameters:
// - `Line`: Decoded request line.
function ParseRequestLine(Line: string): result of array of string, string;
begin
  var Parts: array of string := Std.Str.Split(Line, ' ');
  if Std.Arrays.Length(Parts) <> 3 then
  begin
    return Error('HTTP request line must contain method, target, and version')
  end;

  if not Std.Http.Method.IsValidToken(Parts[0]) then
  begin
    return Error('HTTP request method must be a non-empty RFC 9110 token')
  end;

  if ((((not Std.Str.StartsWith(Parts[1], '/')) or Std.Http.Headers.ContainsUnsafeText(Parts[1])) or Std.Str.Contains(Parts[1], #9)) or Std.Str.Contains(Parts[1], '#')) or
     (not Std.Http.Fields.IsValidValue(Parts[1])) then
  begin
    return Error('HTTP server supports only safe origin-form request targets')
  end;

  if (Parts[2] <> 'HTTP/1.0') and (Parts[2] <> 'HTTP/1.1') then
  begin
    return Error('HTTP server supports only HTTP/1.0 and HTTP/1.1 requests')
  end;

  return Ok(Parts)
end;

// Counts fields with a case-insensitive name.
//
// Parameters:
// - `Headers`: Parsed request fields.
// - `Name`: Case-insensitive field name to count.
function HeaderCount(Headers: array of Header; Name: string): integer;
begin
  mutable var Count: integer := 0;
  for Index: integer := 0 to Std.Arrays.Length(Headers) - 1 do
  begin
    if Std.Http.Headers.IsName(Headers[Index].Name, Name) then
    begin
      Count := Count + 1
    end
  end;

  return Count
end;

// Reads exactly one Content-Length request body.
//
// Parameters:
// - `Connection`: Accepted TCP or TLS connection.
// - `Initial`: Body bytes already read with the request head.
// - `Length`: Declared complete body length.
function ReadBody(Connection: Std.Net.Connection; Initial: array of integer; Length: integer): result of array of integer, string;
begin
  mutable var InitialLength: integer := Std.Arrays.Length(Initial);
  if Length < InitialLength then
  begin
    InitialLength := Length
  end;
  mutable var Chunks: array of array of integer := [Std.Arrays.Slice(Initial, 0, InitialLength)];
  mutable var Received: integer := InitialLength;
  while Received < Length do
  begin
    mutable var ReadMaximum: integer := Length - Received;
    if ReadMaximum > 1048576 then
    begin
      ReadMaximum := 1048576
    end;

    case Std.Net.ReceiveBytes(Connection, ReadMaximum) of
      Ok(Chunk):
      begin
        if Std.Arrays.Length(Chunk) = 0 then
        begin
          return Error('HTTP request body is shorter than Content-Length')
        end;

        Std.Arrays.Push(Chunks, Chunk);
        Received := Received + Std.Arrays.Length(Chunk)
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end;

  return Ok(Std.Http.Io.JoinChunks(Chunks))
end;

// Reads and validates one bounded HTTP/1.x request from a connected client.
//
// Parameters:
// - `Connection`: Accepted TCP or TLS connection.
// - `MaxHeaderBytes`: Maximum request-head size in bytes.
// - `MaxBodyBytes`: Maximum request-body size in bytes.
public function ReadRequest(Connection: Std.Net.Connection; MaxHeaderBytes: integer; MaxBodyBytes: integer): result of ServerRequest, string;
begin
  if MaxHeaderBytes < 1 then
  begin
    return Error('HTTP server MaxHeaderBytes must be positive')
  end;

  if MaxBodyBytes < 0 then
  begin
    return Error('HTTP server MaxBodyBytes must not be negative')
  end;
  mutable var Bytes: array of integer := [];
  case ReadHead(Connection, MaxHeaderBytes) of
    Ok(Value):
    begin
      Bytes := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  var Separator: integer := Std.Http.Wire.FindSeparator(Bytes, 0);
  var HeadBytes: array of integer := Std.Arrays.Slice(Bytes, 0, Separator);
  mutable var HeadText: string := '';
  case Std.Net.Utf8.Decode(HeadBytes) of
    Ok(Value):
    begin
      HeadText := Value
    end;
    Error(Message):
    begin
      return Error('HTTP request headers are not valid UTF-8: ' + Message)
    end
  end;
  var Lines: array of string := Std.Str.Split(HeadText, #13 + #10);
  if Std.Arrays.Length(Lines) = 0 then
  begin
    return Error('HTTP request line is missing')
  end;
  mutable var RequestLine: array of string := [];
  case ParseRequestLine(Lines[0]) of
    Ok(Value):
    begin
      RequestLine := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  mutable var Headers: array of Header := [];
  case Std.Http.Fields.Parse(HeadText, 'request') of
    Ok(Value):
    begin
      Headers := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;

  if (RequestLine[2] = 'HTTP/1.1') and (HeaderCount(Headers, 'Host') <> 1) then
  begin
    return Error('HTTP/1.1 request must contain exactly one Host header')
  end;

  if RequestLine[2] = 'HTTP/1.1' then
  begin
    case Std.Http.Headers.Find(Headers, 'Host') of
      Some(Value):
      begin
        if Std.Str.Trim(Value) = '' then
        begin
          return Error('HTTP/1.1 Host header must not be empty')
        end
      end;
      None:
      begin
      end
    end
  end;
  mutable var BodyLength: integer := 0;
  case Std.Http.BodyFraming.Select(Headers) of
    Ok(Framing):
    begin
      if Framing.Mode = 2 then
      begin
        return Error('HTTP server does not support chunked request bodies')
      end;

      if Framing.Mode = 1 then
      begin
        BodyLength := Framing.Remaining
      end
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;

  if BodyLength > MaxBodyBytes then
  begin
    return Error('HTTP request body exceeds MaxBodyBytes')
  end;
  var InitialBody: array of integer := Std.Arrays.Slice(Bytes, Separator + 4, (Std.Arrays.Length(Bytes) - Separator) -
                                                                              4);
  mutable var Body: array of integer := [];
  case ReadBody(Connection, InitialBody, BodyLength) of
    Ok(Value):
    begin
      Body := Value
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  var Output: ServerRequest := record
    Method := RequestLine[0];
    Target := RequestLine[1];
    Headers := Headers;
    Body := Body;
  end;

  return Ok(Output)
end;

// Validates and serializes one complete HTTP/1.1 response.
//
// Parameters:
// - `ResponseValue`: Complete response to encode.
function EncodeResponse(ResponseValue: ServerResponse): result of array of integer, string;
begin
  if (ResponseValue.StatusCode < 100) or (ResponseValue.StatusCode > 599) then
  begin
    return Error('HTTP response status code must be in 100..599')
  end;

  if (not Std.Http.Fields.IsValidValue(ResponseValue.ReasonPhrase)) or
     Std.Http.Headers.ContainsUnsafeText(ResponseValue.ReasonPhrase) then
  begin
    return Error('HTTP response reason phrase contains an invalid control character')
  end;
  mutable var Head: string := (((('HTTP/1.1 ' + Std.Conv.IntToStr(ResponseValue.StatusCode)) + ' ') + ResponseValue.ReasonPhrase) + #13) +
                              #10;
  Head := ((Head + 'Connection: close') + #13) + #10;
  Head := (((Head + 'Content-Length: ') + Std.Conv.IntToStr(Std.Arrays.Length(ResponseValue.Body))) + #13) +
          #10;
  for Index: integer := 0 to Std.Arrays.Length(ResponseValue.Headers) - 1 do
  begin
    var Field: Header := ResponseValue.Headers[Index];
    if (not Std.Http.Method.IsValidToken(Field.Name)) or
       (not Std.Http.Fields.IsValidValue(Field.Value)) then
    begin
      return Error('HTTP response contains an invalid header')
    end;

    if ((Std.Http.Headers.IsName(Field.Name, 'Content-Length') or Std.Http.Headers.IsName(Field.Name, 'Transfer-Encoding')) or Std.Http.Headers.IsName(Field.Name, 'Connection')) then
    begin
      return Error('Content-Length, Transfer-Encoding, and Connection are managed by Std.Http')
    end;

    Head := ((((Head + Field.Name) + ': ') + Field.Value) + #13) + #10
  end;

  Head := (Head + #13) + #10;
  return Ok(Std.Arrays.Concat(Std.Net.Utf8.Encode(Head), ResponseValue.Body))
end;

// Writes one complete HTTP/1.1 response without closing the connection.
//
// Parameters:
// - `Connection`: Accepted TCP or TLS connection.
// - `ResponseValue`: Complete response to serialize and write.
public function WriteResponse(Connection: Std.Net.Connection; ResponseValue: ServerResponse): result of boolean, string;
begin
  case EncodeResponse(ResponseValue) of
    Ok(Bytes):
    begin
      return Std.Http.Io.WriteAll(Connection, Bytes)
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// Bounded concurrent HTTP server-loop orchestration.
unit Std.Http.ServerLoop;

uses Std.Arrays, Std.Http.Server, Std.Http.Types, Std.Net, Std.Task;

// Validates all server-loop limits before accepting a connection.
//
// Parameters:
// - `Options`: Server-loop limits to validate.
function ValidateOptions(Options: ServerOptions): result of boolean, string;
begin
  if Options.MaxHeaderBytes < 1 then
  begin
    return Error('HTTP server MaxHeaderBytes must be positive')
  end;

  if Options.MaxBodyBytes < 0 then
  begin
    return Error('HTTP server MaxBodyBytes must not be negative')
  end;

  if Options.ConnectionTimeoutMillis < 1 then
  begin
    return Error('HTTP server ConnectionTimeoutMillis must be positive')
  end;

  if Options.MaxConcurrentRequests < 1 then
  begin
    return Error('HTTP server MaxConcurrentRequests must be positive')
  end;

  if Options.MaxRequests < 0 then
  begin
    return Error('HTTP server MaxRequests must not be negative')
  end;

  return Ok(true)
end;

// Closes a connection while deliberately ignoring close errors.
//
// Parameters:
// - `Connection`: Connection to close.
procedure CloseQuietly(Connection: Std.Net.Connection);
begin
  case Std.Net.Close(Connection) of
    Ok(_):
    begin
    end;
    Error(_):
    begin
    end
  end
end;

// Attempts to write an empty 400 response without propagating failures.
//
// Parameters:
// - `Connection`: Connection that supplied a malformed request.
procedure WriteBadRequestQuietly(Connection: Std.Net.Connection);
begin
  var ResponseValue: ServerResponse := ServerResponse.Create(400, 'Bad Request');
  case Std.Http.Server.WriteResponse(Connection, ResponseValue) of
    Ok(_):
    begin
    end;
    Error(_):
    begin
    end
  end
end;

// Serves and closes one accepted connection.
//
// Parameters:
// - `Connection`: Accepted TCP or TLS connection.
// - `Options`: Request and connection limits.
// - `Handler`: Callback that maps the parsed request to a response.
function ServeConnection(
  Connection: Std.Net.Connection;
  Options: ServerOptions;
  Handler: RequestHandler
): boolean;
begin
  case Std.Net.SetTimeout(Connection, Options.ConnectionTimeoutMillis) of
    Ok(_):
    begin
    end;
    Error(_):
    begin
      CloseQuietly(Connection);
      return false
    end
  end;
  mutable var RequestValue: ServerRequest := record
    Method := '';
    Target := '';
    Headers := [];
    Body := [];
  end;

  case Std.Http.Server.ReadRequest(Connection, Options.MaxHeaderBytes, Options.MaxBodyBytes) of
    Ok(Value):
    begin
      RequestValue := Value
    end;
    Error(_):
    begin
      WriteBadRequestQuietly(Connection);
      CloseQuietly(Connection);
      return false
    end
  end;
  var ResponseValue: ServerResponse := Handler(RequestValue);
  mutable var Succeeded: boolean := false;
  case Std.Http.Server.WriteResponse(Connection, ResponseValue) of
    Ok(_):
    begin
      Succeeded := true
    end;
    Error(_):
    begin
    end
  end;

  CloseQuietly(Connection);
  return Succeeded
end;

// Reports whether the current batch may accept another connection.
//
// Parameters:
// - `Options`: Server-loop concurrency and request limits.
// - `Accepted`: Total accepted connections.
// - `BatchLength`: Connections already present in the current batch.
function HasCapacity(Options: ServerOptions; Accepted: integer; BatchLength: integer): boolean;
begin
  return (BatchLength < Options.MaxConcurrentRequests) and
         ((Options.MaxRequests = 0) or (Accepted < Options.MaxRequests))
end;

// Accepts requests in bounded concurrent batches and dispatches each one to Handler.
//
// Parameters:
// - `Listener`: Open TCP or TLS listener.
// - `Options`: Request limits and server-loop bounds.
// - `Handler`: Callback that maps each accepted request to a response.
public function Serve(Listener: Std.Net.Listener; Options: ServerOptions; Handler: RequestHandler): result of boolean, string;
begin
  case ValidateOptions(Options) of
    Ok(_):
    begin
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end;
  mutable var Accepted: integer := 0;
  while (Options.MaxRequests = 0) or (Accepted < Options.MaxRequests) do
  begin
    mutable var Tasks: array of task := [];
    while HasCapacity(Options, Accepted, Std.Arrays.Length(Tasks)) do
    begin
      case Std.Net.Accept(Listener) of
        Ok(Connection):
        begin
          Std.Arrays.Push(Tasks, go ServeConnection(Connection, Options, Handler));
          Accepted := Accepted + 1
        end;
        Error(Message):
        begin
          Std.Task.WaitAll(Tasks);
          return Error(Message)
        end
      end
    end;

    Std.Task.WaitAll(Tasks)
  end;

  return Ok(true)
end;

// Incremental bounded Server-Sent Events decoding.
unit Std.Http.Sse;

uses Std.Arrays, Std.Http.Handles, Std.Http.Types, Std.Net.Utf8, Std.Str;

type
  // Mutable parsing state retained for one decoder handle.
  DecoderState = record
    // Incomplete input bytes not yet terminated by a line ending.
    Buffer: array of integer;
    // Joined data fields for the current event.
    Data: string;
    // Optional event field for the current event.
    EventType: string;
    // Most recently observed event identifier.
    LastEventId: string;
    // Bytes accumulated for the current event.
    EventBytes: integer;
    // Maximum bytes allowed for one event.
    Maximum: integer;
    // Whether the decoder has consumed its final input.
    Finished: boolean;
  end;
  // Result of processing every complete line currently buffered.
  DecoderProcess = record
    // Updated decoder state.
    State: DecoderState;
    // Complete events emitted while processing.
    Events: array of SseEvent;
  end;

// Reserves and stores one state in the hosted HTTP registry.
function ReserveState(State: DecoderState): integer;
begin
  return 0
end;

// Tests whether one hosted SSE-decoder state exists.
function HasState(Slot: integer): boolean;
begin
  return false
end;

// Loads one state from the hosted HTTP registry.
function LoadState(Slot: integer): DecoderState;
begin
  panic('internal SSE decoder state intrinsic was not lowered')
end;

// Replaces one state in the hosted HTTP registry.
procedure StoreState(Slot: integer; State: DecoderState);
begin
end;

// Resolves and validates an opaque decoder handle.
//
// Parameters:
// - `Decoder`: Decoder handle to resolve.
function DecoderIndex(Decoder: Std.Http.Types.SseDecoder): result of integer, string;
begin
  var Slot: integer := Std.Http.Handles.SseDecoderSlot(Decoder);
  if (Slot < 1) or (not HasState(Slot)) then
  begin
    return Error('SSE decoder handle is invalid')
  end;

  return Ok(Slot)
end;

// Finds the next supported line ending and its byte width.
//
// Parameters:
// - `Bytes`: Buffered bytes to scan from the beginning.
function LineEnd(Bytes: array of integer; Final: boolean): array of integer;
begin
  for Index: integer := 0 to Std.Arrays.Length(Bytes) - 1 do
  begin
    if Bytes[Index] = 10 then
    begin
      return [Index, 1]
    end;

    if Bytes[Index] = 13 then
    begin
      if Index + 1 >= Std.Arrays.Length(Bytes) then
      begin
        if Final then
        begin
          return [Index, 1]
        end;

        return [-1, 0]
      end;

      if Bytes[Index + 1] = 10 then
      begin
        return [Index, 2]
      end;

      return [Index, 1]
    end
  end;

  if Final and (Std.Arrays.Length(Bytes) > 0) then
  begin
    return [Std.Arrays.Length(Bytes), 0]
  end;

  return [-1, 0]
end;

// Appends the pending event without adding input bytes.
function EmitEvent(State: DecoderState; mutable Events: array of SseEvent): array of SseEvent;
begin
  if State.Data <> '' then
  begin
    mutable var EventType: string := State.EventType;
    if EventType = '' then
    begin
      EventType := 'message'
    end;

    Std.Arrays.Push(Events, record
      EventType := EventType;
      Data := Std.Str.Substring(State.Data, 0, Std.Str.Length(State.Data) - 1);
      Id := State.LastEventId;
    end)
  end;

  return Events
end;

// Consumes complete SSE lines and returns updated state plus emitted events.
//
// Parameters:
// - `State`: Decoder state updated while parsing buffered lines.
function Process(mutable State: DecoderState; Final: boolean): result of DecoderProcess, string;
begin
  mutable var Events: array of SseEvent := [];
  mutable var EndValue: array of integer := LineEnd(State.Buffer, Final);
  while EndValue[0] >= 0 do
  begin
    var LineBytes: array of integer := Std.Arrays.Slice(State.Buffer, 0, EndValue[0]);
    State.EventBytes := (State.EventBytes + EndValue[0]) + EndValue[1];
    if State.EventBytes > State.Maximum then
    begin
      return Error('SSE event exceeds MaxEventBytes')
    end;

    State.Buffer := Std.Arrays.Slice(State.Buffer, EndValue[0] + EndValue[1], (Std.Arrays.Length(State.Buffer) - EndValue[0]) -
                                                                              EndValue[1]);
    case Std.Net.Utf8.Decode(LineBytes) of
      Ok(Line):
      begin
        if Line = '' then
        begin
          Events := EmitEvent(State, Events);
          State.Data := '';
          State.EventType := '';
          State.EventBytes := 0
        end
        else if not Std.Str.StartsWith(Line, ':') then
        begin
          mutable var Name: string := Line;
          mutable var Value: string := '';
          var Colon: integer := Std.Str.IndexOf(Line, ':');
          if Colon >= 0 then
          begin
            Name := Std.Str.Substring(Line, 0, Colon);
            Value := Std.Str.Substring(Line, Colon + 1, (Std.Str.Length(Line) - Colon) - 1);
            if Std.Str.StartsWith(Value, ' ') then
            begin
              Value := Std.Str.Substring(Value, 1, Std.Str.Length(Value) - 1)
            end
          end;

          if Name = 'data' then
          begin
            State.Data := (State.Data + Value) + #10
          end
          else if Name = 'event' then
          begin
            State.EventType := Value
          end
          else if (Name = 'id') and (not Std.Str.Contains(Value, #0)) then
          begin
            State.LastEventId := Value
          end
        end
      end;
      Error(Message):
      begin
        return Error('SSE line is not valid UTF-8: ' + Message)
      end
    end;

    EndValue := LineEnd(State.Buffer, Final)
  end;

  if State.EventBytes + Std.Arrays.Length(State.Buffer) > State.Maximum then
  begin
    return Error('SSE event exceeds MaxEventBytes')
  end;

  if Final then
  begin
    Events := EmitEvent(State, Events);
    State.Data := '';
    State.EventType := '';
    State.EventBytes := 0;
    State.Finished := true
  end;
  var Output: DecoderProcess := record
    State := State;
    Events := Events;
  end;

  return Ok(Output)
end;

// Creates an incremental decoder with a bounded event buffer.
//
// Parameters:
// - `MaxEventBytes`: Maximum buffered bytes for one incomplete event.
public function Create(MaxEventBytes: integer): result of Std.Http.Types.SseDecoder, string;
begin
  if MaxEventBytes < 1 then
  begin
    return Error('SSE MaxEventBytes must be positive')
  end;
  var State: DecoderState := record
    Buffer := [];
    Data := '';
    EventType := '';
    LastEventId := '';
    EventBytes := 0;
    Maximum := MaxEventBytes;
    Finished := false;
  end;
  var Slot: integer := ReserveState(State);
  return Ok(Std.Http.Handles.NewSseDecoder(Slot))
end;

// Feeds one byte fragment and returns every complete decoded event.
//
// Parameters:
// - `Decoder`: Open incremental SSE decoder.
// - `Bytes`: Next response-body byte fragment.
public function Feed(Decoder: Std.Http.Types.SseDecoder; Bytes: array of integer): result of array of SseEvent, string;
begin
  case DecoderIndex(Decoder) of
    Ok(Index):
    begin
      mutable var State: DecoderState := LoadState(Index);
      if State.Finished then
      begin
        return Error('SSE decoder is already finished')
      end;

      State.Buffer := Std.Arrays.Concat(State.Buffer, Bytes);
      case Process(State, false) of
        Ok(Output):
        begin
          StoreState(Index, Output.State);
          return Ok(Output.Events)
        end;
        Error(Message):
        begin
          StoreState(Index, State);
          return Error(Message)
        end
      end
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// Flushes the final SSE line and prevents further input.
//
// Parameters:
// - `Decoder`: Open incremental SSE decoder to finish.
public function Finish(Decoder: Std.Http.Types.SseDecoder): result of array of SseEvent, string;
begin
  case DecoderIndex(Decoder) of
    Ok(Index):
    begin
      var State: DecoderState := LoadState(Index);
      if State.Finished then
      begin
        return Error('SSE decoder is already finished')
      end;

      case Process(State, true) of
        Ok(Output):
        begin
          StoreState(Index, Output.State);
          return Ok(Output.Events)
        end;
        Error(Message):
        begin
          return Error(Message)
        end
      end
    end;
    Error(Message):
    begin
      return Error(Message)
    end
  end
end;

// HTTP request, response, server, streaming, and SSE data types.
unit Std.Http.Types;

uses Std.Http.Handles;

public type
  // One HTTP field name and value.
  Header = record
    // Field name with original casing.
    public Name: string;
    // Field value without surrounding whitespace.
    public Value: string;

    // Creates one HTTP field.
    //
    // Parameters:
    // - `Name`: HTTP field name.
