// Absolute HTTP and HTTPS URI parsing for network clients.
unit Std.Net.Uri;

uses Std.Parse, Std.Str;

public type
  // Parsed absolute network URI used by protocol clients.
  Uri = record
    // Lowercase URI scheme.
    public Scheme: string;
    // Host name or unbracketed IPv6 address.
    public Host: string;
    // Explicit or scheme-default TCP port.
    public Port: integer;
    // Origin-form path including an optional query.
    public Path: string;
  end;

// Returns the default port for a supported URI scheme.
//
// Parameters:
// - `Scheme`: Lowercase URI scheme.
function DefaultPort(Scheme: string): result of integer, string;
begin
  if Scheme = 'http' then
  begin
    return Ok(80)
  end;

  if Scheme = 'https' then
  begin
    return Ok(443)
  end;

  return Error('Unsupported URI scheme: ' + Scheme)
end;

// Parses and validates a decimal TCP port.
//
// Parameters:
// - `Text`: Decimal port text.
function ParsePort(Text: string): result of integer, string;
begin
  case Std.Parse.TryInt(Text) of
    Ok(Port):
    begin
      if (Port >= 1) and (Port <= 65535) then
      begin
        return Ok(Port)
      end;

      return Error('URI port must be in 1..65535')
    end;
    Error(Message):
    begin
      return Error('Invalid URI port: ' + Message)
    end
  end
end;

// Parses one authority and constructs the final URI value.
//
// Parameters:
// - `Scheme`: Lowercase supported URI scheme.
// - `Authority`: Host and optional port text.
// - `Path`: Origin-form path including an optional query.
function BuildUri(Scheme: string; Authority: string; Path: string): result of Uri, string;
begin
  if Authority = '' then
  begin
    return Error('URI host must not be empty')
  end;

  if Std.Str.Contains(Authority, '@') then
  begin
    return Error('URI user information is not supported')
  end;
  mutable var Host: string := Authority;
  mutable var PortText: string := '';
  if Std.Str.StartsWith(Authority, '[') then
  begin
    var Closing: integer := Std.Str.IndexOf(Authority, ']');
    if Closing < 0 then
    begin
      return Error('IPv6 URI host is missing closing bracket')
    end;

    Host := Std.Str.Substring(Authority, 1, Closing - 1);
    var Remainder: string := Std.Str.Substring(Authority, Closing + 1, (Std.Str.Length(Authority) - Closing) -
                                                                       1);
    if Remainder <> '' then
    begin
      if not Std.Str.StartsWith(Remainder, ':') then
      begin
        return Error('Unexpected text after IPv6 URI host')
      end;

      PortText := Std.Str.Substring(Remainder, 1, Std.Str.Length(Remainder) - 1)
    end
  end
  else
  begin
    var Colon: integer := Std.Str.LastIndexOf(Authority, ':');
    if Colon >= 0 then
    begin
      Host := Std.Str.Substring(Authority, 0, Colon);
      PortText := Std.Str.Substring(Authority, Colon + 1, (Std.Str.Length(Authority) - Colon) - 1)
    end
  end;

  if Host = '' then
  begin
    return Error('URI host must not be empty')
  end;
  mutable var Port: integer := 0;
  if PortText = '' then
  begin
    case DefaultPort(Scheme) of
      Ok(Value):
      begin
        Port := Value
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end
  else
  begin
    case ParsePort(PortText) of
      Ok(Value):
      begin
        Port := Value
      end;
      Error(Message):
      begin
        return Error(Message)
      end
    end
  end;

  return Ok(record
    Scheme := Scheme;
    Host := Host;
    Port := Port;
    Path := Path;
  end)
end;

// Parses an absolute HTTP or HTTPS URI.
//
// Parameters:
// - `Text`: Absolute URI text to parse.
public function Parse(Text: string): result of Uri, string;
begin
  var SchemeEnd: integer := Std.Str.IndexOf(Text, '://');
  if SchemeEnd <= 0 then
  begin
    return Error('URI must be absolute and include ://')
  end;
  var Scheme: string := Std.Str.ToLower(Std.Str.Substring(Text, 0, SchemeEnd));
  mutable var Rest: string := Std.Str.Substring(Text, SchemeEnd + 3, (Std.Str.Length(Text) - SchemeEnd) -
                                                                     3);
  var FragmentStart: integer := Std.Str.IndexOf(Rest, '#');
  if FragmentStart >= 0 then
  begin
    Rest := Std.Str.Substring(Rest, 0, FragmentStart)
  end;
  mutable var PathStart: integer := Std.Str.IndexOf(Rest, '/');
  var QueryStart: integer := Std.Str.IndexOf(Rest, '?');
  if (PathStart < 0) or ((QueryStart >= 0) and (QueryStart < PathStart)) then
  begin
    PathStart := QueryStart
  end;
  mutable var Authority: string := Rest;
  mutable var Path: string := '/';
  if PathStart >= 0 then
  begin
    Authority := Std.Str.Substring(Rest, 0, PathStart);
    Path := Std.Str.Substring(Rest, PathStart, Std.Str.Length(Rest) - PathStart);
    if Std.Str.StartsWith(Path, '?') then
    begin
      Path := '/' + Path
    end
  end;

  return BuildUri(Scheme, Authority, Path)
end;

// Validated conversion between FPAS strings and UTF-8 byte arrays.
unit Std.Net.Utf8;

uses Std.Arrays, Std.Conv, Std.Str;

// Encodes one FPAS string as UTF-8 bytes.
//
// Parameters:
// - `Text`: String to encode.
public function Encode(Text: string): array of integer;
begin
  mutable var Bytes: array of integer := [];
  for Index: integer := 0 to Std.Str.Length(Text) - 1 do
  begin
    var CodePoint: integer := Std.Str.Ord(Std.Str.CharAt(Text, Index));
    if CodePoint <= 127 then
    begin
      Std.Arrays.Push(Bytes, CodePoint)
    end
    else if CodePoint <= 2047 then
    begin
      Std.Arrays.Push(Bytes, 192 + CodePoint div 64);
      Std.Arrays.Push(Bytes, 128 + CodePoint mod 64)
    end
    else if CodePoint <= 65535 then
    begin
      Std.Arrays.Push(Bytes, 224 + CodePoint div 4096);
      Std.Arrays.Push(Bytes, 128 + (CodePoint div 64) mod 64);
      Std.Arrays.Push(Bytes, 128 + CodePoint mod 64)
    end
    else
    begin
      Std.Arrays.Push(Bytes, 240 + CodePoint div 262144);
      Std.Arrays.Push(Bytes, 128 + (CodePoint div 4096) mod 64);
      Std.Arrays.Push(Bytes, 128 + (CodePoint div 64) mod 64);
      Std.Arrays.Push(Bytes, 128 + CodePoint mod 64)
    end
  end;

  return Bytes
end;

// Builds a byte-indexed UTF-8 validation error.
//
// Parameters:
// - `Index`: Byte offset where validation failed.
// - `Message`: Reason the byte sequence is invalid.
function Invalid(Index: integer; Message: string): result of string, string;
begin
  return Error((('Invalid UTF-8 at byte ' + Std.Conv.IntToStr(Index)) + ': ') + Message)
end;

// Reports whether an integer is a UTF-8 continuation byte.
//
// Parameters:
// - `ByteValue`: Integer byte value to inspect.
function IsContinuation(ByteValue: integer): boolean;
begin
  return (ByteValue >= 128) and (ByteValue <= 191)
end;

// Decodes validated UTF-8 bytes into one FPAS string.
//
// Parameters:
// - `Bytes`: Integer byte values in `0..255`.
public function Decode(Bytes: array of integer): result of string, string;
begin
  mutable var Text: string := '';
  mutable var Index: integer := 0;
  while Index < Std.Arrays.Length(Bytes) do
  begin
    var First: integer := Bytes[Index];
    if (First < 0) or (First > 255) then
    begin
      return Invalid(Index, 'byte must be in 0..255')
    end;
    mutable var CodePoint: integer := 0;
    mutable var Width: integer := 0;
    if First <= 127 then
    begin
      CodePoint := First;
      Width := 1
    end
    else if (First >= 194) and (First <= 223) then
    begin
      Width := 2
    end
    else if (First >= 224) and (First <= 239) then
    begin
      Width := 3
    end
    else if (First >= 240) and (First <= 244) then
    begin
      Width := 4
    end
    else
    begin
      return Invalid(Index, 'invalid leading byte')
    end;

    if Index + Width > Std.Arrays.Length(Bytes) then
    begin
      return Invalid(Index, 'truncated sequence')
    end;

    if Width >= 2 then
    begin
      var Second: integer := Bytes[Index + 1];
      if not IsContinuation(Second) then
      begin
        return Invalid(Index + 1, 'expected continuation byte')
      end;

      CodePoint := ((First - 192) * 64 + Second) - 128
    end;

    if Width >= 3 then
    begin
      var Third: integer := Bytes[Index + 2];
      if not IsContinuation(Third) then
      begin
        return Invalid(Index + 2, 'expected continuation byte')
      end;

      CodePoint := (((First - 224) * 4096 + (Bytes[Index + 1] - 128) * 64) + Third) - 128;
      if (CodePoint < 2048) or ((CodePoint >= 55296) and (CodePoint <= 57343)) then
      begin
        return Invalid(Index, 'overlong or surrogate sequence')
      end
    end;

    if Width = 4 then
    begin
      var Fourth: integer := Bytes[Index + 3];
      if not IsContinuation(Fourth) then
      begin
        return Invalid(Index + 3, 'expected continuation byte')
      end;

      CodePoint := ((((First - 240) * 262144 + (Bytes[Index + 1] - 128) * 4096) + (Bytes[Index + 2] - 128) * 64) + Fourth) -
                   128;
      if (CodePoint < 65536) or (CodePoint > 1114111) then
      begin
        return Invalid(Index, 'overlong or out-of-range sequence')
      end
    end;

    Text := Text + Std.Str.Chr(CodePoint);
    Index := Index + Width
  end;

  return Ok(Text)
end;

unit Std.Tui.Cells.ButtonPalette;

uses Std.Tui.Cells.Style, Std.Tui.Cells.StyleRole;

public type
  // Concrete styles for every flat button state.
  TuiButtonPalette = record
    // Style used for normal content.
    public Normal: TuiStyle;
    // Style used for the default state.
    public Default: TuiStyle;
    // Selected item index or style.
    public Selected: TuiStyle;
    // Style used for disabled content.
    public Disabled: TuiStyle;
    // Shortcut text, gesture, or style.
    public Shortcut: TuiStyle;
    // Shortcut style used by a default button.
    public DefaultShortcut: TuiStyle;
    // Shortcut style used by a selected button.
    public SelectedShortcut: TuiStyle;

    // Creates a complete button palette.
    //
    // Parameters:
    // - `Normal`: Normal-state style.
    // - `Default`: Fallback value used when no value is available.
    // - `Selected`: Selected item index.
    // - `Disabled`: Whether the control is disabled.
    // - `Shortcut`: Shortcut gesture or display text.
    // - `DefaultShortcut`: Fallback shortcut displayed for the item.
    // - `SelectedShortcut`: Shortcut displayed for the selected item.
    public static function Create(
  Normal: TuiStyle;
  Default: TuiStyle;
  Selected: TuiStyle;
  Disabled: TuiStyle;
  Shortcut: TuiStyle;
  DefaultShortcut: TuiStyle;
  SelectedShortcut: TuiStyle
): TuiButtonPalette;
    begin
      return record
        Normal := Normal;
        Default := Default;
        Selected := Selected;
        Disabled := Disabled;
        Shortcut := Shortcut;
        DefaultShortcut := DefaultShortcut;
        SelectedShortcut := SelectedShortcut;
      end
    end;

    // Resolves one button role.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Role`: Semantic style role used by the operation.
    public function ForRole(Self: TuiButtonPalette; Role: TuiStyleRole): TuiStyle;
    begin
      case Role of
        TuiStyleRole.ButtonNormal:
        begin
          return Self.Normal
        end;
        TuiStyleRole.ButtonDefault:
        begin
          return Self.Default
        end;
        TuiStyleRole.ButtonSelected:
        begin
          return Self.Selected
        end;
        TuiStyleRole.ButtonDisabled:
        begin
          return Self.Disabled
        end;
        TuiStyleRole.ButtonShortcut:
        begin
          return Self.Shortcut
        end;
        TuiStyleRole.ButtonDefaultShortcut:
        begin
          return Self.DefaultShortcut
        end;
        TuiStyleRole.ButtonSelectedShortcut:
        begin
          return Self.SelectedShortcut
        end
        else
        begin
          panic('Tui button palette requires a button style role')
        end
      end
    end;

    // Returns a copy with one button role replaced.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Role`: Semantic style role used by the operation.
    // - `Style`: Concrete terminal style.
    public function WithRole(Self: TuiButtonPalette; Role: TuiStyleRole; Style: TuiStyle): TuiButtonPalette;
    begin
      mutable var Updated: TuiButtonPalette := Self;
      case Role of
        TuiStyleRole.ButtonNormal:
        begin
          Updated.Normal := Style
        end;
        TuiStyleRole.ButtonDefault:
        begin
          Updated.Default := Style
        end;
        TuiStyleRole.ButtonSelected:
        begin
          Updated.Selected := Style
        end;
        TuiStyleRole.ButtonDisabled:
        begin
          Updated.Disabled := Style
        end;
        TuiStyleRole.ButtonShortcut:
        begin
          Updated.Shortcut := Style
        end;
        TuiStyleRole.ButtonDefaultShortcut:
        begin
          Updated.DefaultShortcut := Style
        end;
        TuiStyleRole.ButtonSelectedShortcut:
        begin
          Updated.SelectedShortcut := Style
        end
        else
        begin
          panic('Tui button palette requires a button style role')
        end
      end;

      return Updated
    end;
  end;

unit Std.Tui.Cells.Cell;

uses Std.Tui.Cells.Glyph, Std.Tui.Cells.Style, Std.Tui.Cells.StyleRole;

public type
  // One validated renderable grapheme with a semantic or concrete style.
  TuiCell = record
    // Single renderable grapheme.
    public Glyph: string;
    // Semantic style role of the cell.
    public Role: TuiStyleRole;
    // Optional concrete style overriding semantic role resolution.
    public ConcreteStyle: option of TuiStyle;
    // Display width of the glyph in terminal cells.
    public Columns: integer;

    // Creates a theme-resolved cell; the glyph must be one non-zero-width grapheme cluster.
    //
    // Parameters:
    // - `Glyph`: Single renderable grapheme.
    // - `Role`: Semantic style role used by the operation.
    public static function Create(Glyph: string; Role: TuiStyleRole): TuiCell;
    begin
      return record
        Glyph := Glyph;
        Role := Role;
        ConcreteStyle := None;
        Columns := TuiGlyphWidth(Glyph);
      end
    end;

    // Creates a cell with a concrete style that bypasses theme lookup.
    //
    // Parameters:
    // - `Glyph`: Single renderable grapheme.
    // - `Style`: Concrete terminal style.
    public static function Styled(Glyph: string; Style: TuiStyle): TuiCell;
    begin
      return record
        Glyph := Glyph;
        Role := TuiStyleRole.Normal;
        ConcreteStyle := Some(Style);
        Columns := TuiGlyphWidth(Glyph);
      end
    end;

    // Returns the terminal-column width of the cell glyph (`1` or `2`).
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Width(Self: TuiCell): integer;
    begin
      return Self.Columns
    end;
  end;

unit Std.Tui.Cells.Color;

public type
  // Color representation kind for terminal painting.
  TuiColorKind = enum
    // Represents the `Crt` variant of `TuiColorKind`.
    Crt;
    // Represents the `Ansi256` variant of `TuiColorKind`.
    Ansi256;
    // Represents the `Rgb` variant of `TuiColorKind`.
    Rgb;
  end;

function TuiColorRequireRange(Value: integer; Minimum: integer; Maximum: integer; Name: string): integer;
begin
  if (Value < Minimum) or (Value > Maximum) then
  begin
    panic(('Tui ' + Name) + ' is outside its supported range')
  end;

  return Value
end;

public type
  // Validated CRT, ANSI-256, or RGB color value.
  TuiColor = record
    // Variant kind represented by the value.
    public Kind: TuiColorKind;
    // Palette or collection index.
    public Index: integer;
    // Red RGB channel.
    public Red: integer;
    // Green RGB channel.
    public Green: integer;
    // Blue RGB channel.
    public Blue: integer;

    // Creates a CRT color (`0..15`).
    //
    // Parameters:
    // - `Index`: Zero-based index used by the operation.
    public static function FromCrt(Index: integer): TuiColor;
    begin
      TuiColorRequireRange(Index, 0, 15, 'CRT color index');
      return record
        Kind := TuiColorKind.Crt;
        Index := Index;
        Red := 0;
        Green := 0;
        Blue := 0;
      end
    end;

    // Creates an ANSI-256 color (`0..255`).
    //
    // Parameters:
    // - `Index`: Zero-based index used by the operation.
    public static function FromAnsi256(Index: integer): TuiColor;
    begin
      TuiColorRequireRange(Index, 0, 255, 'ANSI-256 color index');
      return record
        Kind := TuiColorKind.Ansi256;
        Index := Index;
        Red := 0;
        Green := 0;
        Blue := 0;
      end
    end;

    // Creates an RGB color; each channel is `0..255`.
    //
    // Parameters:
    // - `Red`: Red RGB channel in the range `0..255`.
    // - `Green`: Green RGB channel in the range `0..255`.
    // - `Blue`: Blue RGB channel in the range `0..255`.
    public static function FromRgb(Red: integer; Green: integer; Blue: integer): TuiColor;
    begin
      TuiColorRequireRange(Red, 0, 255, 'red channel');
      TuiColorRequireRange(Green, 0, 255, 'green channel');
      TuiColorRequireRange(Blue, 0, 255, 'blue channel');
      return record
        Kind := TuiColorKind.Rgb;
        Index := 0;
        Red := Red;
        Green := Green;
        Blue := Blue;
      end
    end;
  end;

unit Std.Tui.Cells.Glyph;

