unit Std.Tui.Layout.Frame;

uses Std.Arrays, Std.Tui.Geometry.Rect;

public type
  // One private arranged-frame entry for a preorder element visit.
  TuiArrangedEntry = record
    // Index of the parent arranged entry.
    public ParentIndex: integer;
    // Rectangle occupied by the value.
    public Bounds: TuiRect;
    // Clipping rectangle in surface coordinates.
    public Clip: TuiRect;
  end;

mutable var
  TuiFrameEntries: array of array of TuiArrangedEntry := [];

function TuiFrameRequire(Slot: integer): integer;
begin
  if (Slot < 1) or (Slot > Std.Arrays.Length(TuiFrameEntries)) then
  begin
    panic('Tui arranged frame handle is invalid')
  end;

  return Slot
end;

public type
  // Host-owned arranged-frame index for one painted tree.
  TuiArrangedFrame = record
    // Opaque backing-storage slot.
    public Slot: integer;

    // Allocates an empty arranged frame.
    public static function Create(): TuiArrangedFrame;
    begin
      mutable var Empty: array of TuiArrangedEntry := [];
      TuiFrameEntries := Std.Arrays.Concat(TuiFrameEntries, [Empty]);
      return record
        Slot := Std.Arrays.Length(TuiFrameEntries);
      end
    end;

    // Clears all entries before a fresh arrange pass.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public procedure Clear(Self: TuiArrangedFrame);
    begin
      var Slot: integer := TuiFrameRequire(Self.Slot);
      mutable var Empty: array of TuiArrangedEntry := [];
      TuiFrameEntries[Slot - 1] := Empty
    end;

    // Appends one preorder entry and returns its index.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `ParentIndex`: Index of the parent arranged entry.
    // - `Bounds`: Rectangle affected by the operation.
    // - `Clip`: Clipping rectangle for drawing.
    public function Push(Self: TuiArrangedFrame; ParentIndex: integer; Bounds: TuiRect; Clip: TuiRect): integer;
    begin
      var Slot: integer := TuiFrameRequire(Self.Slot);
      mutable var Entries: array of TuiArrangedEntry := TuiFrameEntries[Slot - 1];
      var Index: integer := Std.Arrays.Length(Entries);
      TuiFrameEntries[Slot - 1] := [];
      Std.Arrays.Push(Entries, record
        ParentIndex := ParentIndex;
        Bounds := Bounds;
        Clip := Clip;
      end);
      TuiFrameEntries[Slot - 1] := Entries;
      return Index
    end;

    // Drop the shared slot handle before Push so copy-on-write stays unique.
    // Replaces every entry atomically after a successful arrange pass.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Entries`: Arranged entries replacing the current frame contents.
    public procedure ReplaceEntries(Self: TuiArrangedFrame; Entries: array of TuiArrangedEntry);
    begin
      var Slot: integer := TuiFrameRequire(Self.Slot);
      TuiFrameEntries[Slot - 1] := Entries
    end;

    // Returns the number of arranged entries.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Count(Self: TuiArrangedFrame): integer;
    begin
      var Slot: integer := TuiFrameRequire(Self.Slot);
      return Std.Arrays.Length(TuiFrameEntries[Slot - 1])
    end;

    // Returns one arranged entry by preorder index.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Index`: Zero-based index used by the operation.
    public function EntryAt(Self: TuiArrangedFrame; Index: integer): TuiArrangedEntry;
    begin
      var Slot: integer := TuiFrameRequire(Self.Slot);
      var Entries: array of TuiArrangedEntry := TuiFrameEntries[Slot - 1];
      if (Index < 0) or (Index >= Std.Arrays.Length(Entries)) then
      begin
        panic('Tui arranged frame index is out of range')
      end;

      return Entries[Index]
    end;
  end;

unit Std.Tui.Layout.LayoutSettings;

uses Std.Tui.Layout.Alignment, Std.Tui.Layout.Margins, Std.Tui.Layout.SizePolicy;

function TuiLayoutSettingsRequireNonNegativeStretch(Value: integer): integer;
begin
  if Value < 0 then
  begin
    panic('Tui layout stretch must not be negative')
  end;

  return Value
end;

public type
  // Immutable layout inputs attached to a single-child layout wrapper.
  TuiLayoutSettings = record
    // Outer margins applied during layout.
    public Margins: TuiMargins;
    // Horizontal and vertical size policy.
    public SizePolicy: TuiSizePolicy;
    // Alignment applied within the allocated area.
    public Alignment: TuiAlignment;
    // Whether the item stretches across the available extent.
    public Stretch: integer;
    // Width in terminal cells.
    public Width: option of integer;
    // Height in terminal cells.
    public Height: option of integer;

    // Creates validated layout settings.
    //
    // Parameters:
    // - `Margins`: Outer margins applied during layout.
    // - `SizePolicy`: Horizontal and vertical size policy.
    // - `Alignment`: Alignment applied within the available area.
    // - `Stretch`: Whether the element stretches across the available extent.
    public static function Create(
  Margins: TuiMargins;
  SizePolicy: TuiSizePolicy;
  Alignment: TuiAlignment;
  Stretch: integer
): TuiLayoutSettings;
    begin
      return record
        Margins := Margins;
        SizePolicy := SizePolicy;
        Alignment := Alignment;
        Stretch := TuiLayoutSettingsRequireNonNegativeStretch(Stretch);
        Width := None;
        Height := None;
      end
    end;

    // Returns a copy constrained to one total width; negative widths panic.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Width`: Width in terminal cells.
    public function WithFixedWidth(Self: TuiLayoutSettings; Width: integer): TuiLayoutSettings;
    begin
      if Width < 0 then
      begin
        panic('Tui fixed layout width must not be negative')
      end;

      return record
        Margins := Self.Margins;
        SizePolicy := Self.SizePolicy;
        Alignment := Self.Alignment;
        Stretch := Self.Stretch;
        Width := Some(Width);
        Height := Self.Height;
      end
    end;

    // Returns a copy constrained to one total height; negative heights panic.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Height`: Height in terminal cells.
    public function WithFixedHeight(Self: TuiLayoutSettings; Height: integer): TuiLayoutSettings;
    begin
      if Height < 0 then
      begin
        panic('Tui fixed layout height must not be negative')
      end;

      return record
        Margins := Self.Margins;
        SizePolicy := Self.SizePolicy;
        Alignment := Self.Alignment;
        Stretch := Self.Stretch;
        Width := Self.Width;
        Height := Some(Height);
      end
    end;

    // Zero margins, preferred policy, fill alignment, and stretch zero.
    public static function Default(): TuiLayoutSettings;
    begin
      return TuiLayoutSettings.Create(TuiMargins.Uniform(0), TuiSizePolicy.Preferred(), TuiAlignment.Fill(), 0)
    end;
  end;

unit Std.Tui.Layout.Margins;

function TuiMarginsRequireNonNegative(Value: integer; Name: string): integer;
begin
  if Value < 0 then
  begin
    panic(('Tui layout margin ' + Name) + ' must not be negative')
  end;

  return Value
end;

public type
  // Non-negative outer margins around a laid-out child.
  TuiMargins = record
    // Left margin in terminal cells.
    public Left: integer;
    // Top margin in terminal cells.
    public Top: integer;
    // Right margin in terminal cells.
    public Right: integer;
    // Bottom margin in terminal cells.
    public Bottom: integer;

    // Creates validated margins.
    //
    // Parameters:
    // - `Left`: Left input value or edge.
    // - `Top`: Top edge or margin.
    // - `Right`: Right input value or edge.
    // - `Bottom`: Bottom edge or margin.
    public static function Create(Left: integer; Top: integer; Right: integer; Bottom: integer): TuiMargins;
    begin
      return record
        Left := TuiMarginsRequireNonNegative(Left, 'left');
        Top := TuiMarginsRequireNonNegative(Top, 'top');
        Right := TuiMarginsRequireNonNegative(Right, 'right');
        Bottom := TuiMarginsRequireNonNegative(Bottom, 'bottom');
      end
    end;

    // Creates equal margins on every side.
    //
    // Parameters:
    // - `Value`: Value used to create or update the result.
    public static function Uniform(Value: integer): TuiMargins;
    begin
      return TuiMargins.Create(Value, Value, Value, Value)
    end;

    // Creates symmetric horizontal and vertical margins.
    //
    // Parameters:
    // - `Horizontal`: Horizontal policy, alignment, or extent.
    // - `Vertical`: Vertical policy, alignment, or extent.
    public static function Symmetric(Horizontal: integer; Vertical: integer): TuiMargins;
    begin
      return TuiMargins.Create(Horizontal, Vertical, Horizontal, Vertical)
    end;

    // Returns left plus right.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Horizontal(Self: TuiMargins): integer;
    begin
      return Self.Left + Self.Right
    end;

    // Returns top plus bottom.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Vertical(Self: TuiMargins): integer;
    begin
      return Self.Top + Self.Bottom
    end;
  end;

unit Std.Tui.Layout.MeasureAxis;

uses Std.Tui.Layout.MeasureConstraint;

public const
  // Largest integer used for checked layout-axis calculations.
  TuiMeasureAxisIntegerMax: integer := 9223372036854775807;

public type
  // Preferred and maximum extents after applying one axis constraint.
  TuiMeasureAxisResult = record
    // Preferred size.
    public Preferred: integer;
    // Maximum value or size.
    public Maximum: integer;
  end;
  // Integer helpers for layout measurement.
  TuiMeasureAxis = record
    // Returns the lesser of two extents.
    //
    // Parameters:
    // - `Left`: Left input value or edge.
    // - `Right`: Right input value or edge.
    public static function Min(Left: integer; Right: integer): integer;
    begin
      if Left < Right then
      begin
        return Left
      end;

      return Right
    end;

    // Returns the greater of two extents.
    //
    // Parameters:
    // - `Left`: Left input value or edge.
    // - `Right`: Right input value or edge.
    public static function Max(Left: integer; Right: integer): integer;
    begin
      if Left > Right then
      begin
        return Left
      end;

      return Right
    end;

    // Adds two extents and rejects overflow.
    //
    // Parameters:
    // - `Left`: Left input value or edge.
    // - `Right`: Right input value or edge.
    public static function Add(Left: integer; Right: integer): integer;
    begin
      if Left > TuiMeasureAxisIntegerMax - Right then
      begin
        panic('Tui layout measurement overflows integer extents')
      end;

      return Left + Right
    end;

    // Constrains preferred and maximum extents by an axis constraint.
    //
    // Parameters:
    // - `Minimum`: Minimum accepted value or extent.
    // - `Preferred`: Preferred size or focus identifier.
    // - `Maximum`: Maximum accepted value or extent.
    // - `Constraint`: Measurement constraint applied to the axis.
    public static function Apply(
  Minimum: integer;
  Preferred: integer;
  Maximum: integer;
  Constraint: TuiMeasureConstraint
): TuiMeasureAxisResult;
    begin
      if not Constraint.IsBounded() then
      begin
        return record
          Preferred := Preferred;
          Maximum := Maximum;
        end
      end;
      var ConstrainedPreferred: integer := TuiMeasureAxis.Max(Minimum, TuiMeasureAxis.Min(Preferred, Constraint.Limit));
      var ConstrainedMaximum: integer := TuiMeasureAxis.Max(ConstrainedPreferred, TuiMeasureAxis.Min(Maximum, Constraint.Limit));
      return record
        Preferred := ConstrainedPreferred;
        Maximum := ConstrainedMaximum;
      end
    end;
  end;

unit Std.Tui.Layout.MeasureSpec;

uses Std.Tui.Geometry.Size, Std.Tui.Layout.MeasureConstraint;

public type
  // Width and height measurement constraints for one element.
  TuiMeasureSpec = record
    // Width in terminal cells.
    public Width: TuiMeasureConstraint;
    // Height in terminal cells.
    public Height: TuiMeasureConstraint;

    // Creates a two-axis measure specification.
    //
    // Parameters:
    // - `Width`: Width in terminal cells.
    // - `Height`: Height in terminal cells.
    public static function Create(Width: TuiMeasureConstraint; Height: TuiMeasureConstraint): TuiMeasureSpec;
    begin
      return record
        Width := Width;
        Height := Height;
      end
    end;

    // Both axes unbounded.
    public static function Unbounded(): TuiMeasureSpec;
    begin
      return TuiMeasureSpec.Create(TuiMeasureConstraint.Unbounded(), TuiMeasureConstraint.Unbounded())
    end;

    // Both axes capped by the given size.
    //
    // Parameters:
    // - `Size`: Size in terminal cells.
    public static function AtMost(Size: TuiSize): TuiMeasureSpec;
    begin
      return TuiMeasureSpec.Create(TuiMeasureConstraint.AtMost(Size.Width), TuiMeasureConstraint.AtMost(Size.Height))
    end;
  end;

unit Std.Tui.Layout.SizePolicy;

public type
  // Per-axis growth and shrink policy for layout.
  TuiSizePolicyKind = enum
    // Represents the `Fixed` variant of `TuiSizePolicyKind`.
    Fixed;
    // Represents the `Minimum` variant of `TuiSizePolicyKind`.
    Minimum;
    // Represents the `Maximum` variant of `TuiSizePolicyKind`.
    Maximum;
    // Represents the `Preferred` variant of `TuiSizePolicyKind`.
    Preferred;
    // Represents the `Expanding` variant of `TuiSizePolicyKind`.
    Expanding;
  end;
  // Independent horizontal and vertical size policies.
  TuiSizePolicy = record
    // Horizontal policy, alignment, or extent.
    public Horizontal: TuiSizePolicyKind;
    // Vertical policy, alignment, or extent.
    public Vertical: TuiSizePolicyKind;

    // Creates a mixed-axis size policy.
    //
    // Parameters:
    // - `Horizontal`: Horizontal policy, alignment, or extent.
    // - `Vertical`: Vertical policy, alignment, or extent.
    public static function Create(Horizontal: TuiSizePolicyKind; Vertical: TuiSizePolicyKind): TuiSizePolicy;
    begin
      return record
        Horizontal := Horizontal;
        Vertical := Vertical;
      end
    end;

    // Both axes fixed to preferred size.
    public static function Fixed(): TuiSizePolicy;
    begin
      return TuiSizePolicy.Create(TuiSizePolicyKind.Fixed, TuiSizePolicyKind.Fixed)
    end;

    // Both axes use preferred as the minimum.
    public static function Minimum(): TuiSizePolicy;
    begin
      return TuiSizePolicy.Create(TuiSizePolicyKind.Minimum, TuiSizePolicyKind.Minimum)
    end;

    // Both axes use preferred as the maximum.
    public static function Maximum(): TuiSizePolicy;
    begin
      return TuiSizePolicy.Create(TuiSizePolicyKind.Maximum, TuiSizePolicyKind.Maximum)
    end;

    // Both axes treat preferred as ideal with grow and shrink.
    public static function Preferred(): TuiSizePolicy;
    begin
      return TuiSizePolicy.Create(TuiSizePolicyKind.Preferred, TuiSizePolicyKind.Preferred)
    end;

    // Both axes request additional space beyond preferred.
    public static function Expanding(): TuiSizePolicy;
    begin
      return TuiSizePolicy.Create(TuiSizePolicyKind.Expanding, TuiSizePolicyKind.Expanding)
    end;
  end;

unit Std.Tui.Layout.Spacer;

public type
  // Whether a spacer has a fixed extent or expands.
  TuiSpacerKind = enum
    // Represents the `Fixed` variant of `TuiSpacerKind`.
    Fixed;
    // Represents the `Expanding` variant of `TuiSpacerKind`.
    Expanding;
  end;
  // Empty layout extent used between siblings.
  TuiSpacer = record
    // Variant kind represented by the value.
    public Kind: TuiSpacerKind;
    // Minimum extent retained while expanding.
    public MinimumExtent: integer;

    // Creates a fixed spacer with a non-negative extent.
    //
    // Parameters:
    // - `Extent`: Fixed extent of the spacer.
    public static function Fixed(Extent: integer): TuiSpacer;
    begin
      if Extent < 0 then
      begin
        panic('Tui fixed spacer extent must not be negative')
      end;

      return record
        Kind := TuiSpacerKind.Fixed;
        MinimumExtent := Extent;
      end
    end;

    // Creates an expanding spacer with a non-negative minimum extent.
    //
    // Parameters:
    // - `MinimumExtent`: Minimum extent retained by an expanding spacer.
    public static function Expanding(MinimumExtent: integer): TuiSpacer;
    begin
      if MinimumExtent < 0 then
      begin
        panic('Tui expanding spacer minimum extent must not be negative')
      end;

      return record
        Kind := TuiSpacerKind.Expanding;
        MinimumExtent := MinimumExtent;
      end
    end;
  end;

// Flat modern button painting.
unit Std.Tui.Rendering.Button;

uses
  Std.Console, Std.Str, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Chrome.Button,
  Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas;

procedure TuiPaintButtonText(
  Canvas: TuiCanvas;
  Position: TuiPoint;
  Button: TuiButtonSpec;
  Role: TuiStyleRole;
  ShortcutRole: TuiStyleRole
);
begin
  mutable var X: integer := Position.X;
  for Index: integer := 0 to Std.Str.Length(Button.Text) - 1 do
  begin
    var Glyph: string := Std.Str.CharAt(Button.Text, Index);
    mutable var GlyphRole: TuiStyleRole := Role;
    if (Button.Mnemonic <> '') and (Std.Str.ToLower(Glyph) = Std.Str.ToLower(Button.Mnemonic)) then
    begin
      GlyphRole := ShortcutRole
    end;

    Canvas.WriteText(TuiPoint.Create(X, Position.Y), Glyph, GlyphRole);
    X := X + Std.Console.DisplayWidth(Glyph)
  end
end;

function TuiButtonRole(Button: TuiButtonSpec; Focused: boolean): TuiStyleRole;
begin
  if not Button.Enabled then
  begin
    return TuiStyleRole.ButtonDisabled
  end;

  if Focused then
  begin
    return TuiStyleRole.ButtonSelected
  end;

  if Button.Default then
  begin
    return TuiStyleRole.ButtonDefault
  end;

  return TuiStyleRole.ButtonNormal
end;

function TuiButtonShortcutRole(Button: TuiButtonSpec; Focused: boolean): TuiStyleRole;
begin
  if not Button.Enabled then
  begin
    return TuiStyleRole.ButtonDisabled
  end;

  if Focused then
  begin
    return TuiStyleRole.ButtonSelectedShortcut
  end;

  if Button.Default then
  begin
    return TuiStyleRole.ButtonDefaultShortcut
  end;

  return TuiStyleRole.ButtonShortcut
end;

// Paints a compact one-row button.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Button`: Button specification used by the operation.
// - `Focused`: Whether the control currently owns focus.
// - `Pressed`: Whether the control is displayed as pressed.
public procedure TuiPaintButton(
  Canvas: TuiCanvas;
  Bounds: TuiRect;
  Button: TuiButtonSpec;
  Focused: boolean;
  Pressed: boolean
);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;
  mutable var Role: TuiStyleRole := TuiButtonRole(Button, Focused);
  mutable var ShortcutRole: TuiStyleRole := TuiButtonShortcutRole(Button, Focused);
  var ContentWidth: integer := Bounds.Width;
  var TextWidth: integer := Std.Console.DisplayWidth(Button.Text);
  mutable var TextX: integer := Bounds.X + ((ContentWidth - TextWidth) div 2);
  if TextX < Bounds.X + 1 then
  begin
    TextX := Bounds.X + 1
  end;

  if Pressed and Button.Enabled then
  begin
    Role := TuiStyleRole.ButtonSelected;
    ShortcutRole := TuiStyleRole.ButtonSelectedShortcut
  end;

  Canvas.FillRect(Bounds, TuiCell.Create(' ', Role));
  TuiPaintButtonText(Canvas, TuiPoint.Create(TextX, Bounds.Y), Button, Role, ShortcutRole);
  if ((Button.Enabled and Button.Default) and not Focused) and not Pressed then
  begin
    Canvas.WriteText(TuiPoint.Create(Bounds.X + 1, Bounds.Y), '•', Role)
  end
end;

unit Std.Tui.Rendering.Canvas;

uses
  Std.Console, Std.Str, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Geometry.Point,
  Std.Tui.Geometry.Rect, Std.Tui.Geometry.Size, Std.Tui.Rendering.Surface;

public type
  // Private frame-scoped drawing capability over one working surface.
  TuiCanvas = record
    // Working surface targeted by the canvas.
    public Surface: TuiWorkingSurface;
    // Clipping rectangle in surface coordinates.
    public Clip: TuiRect;
    // Canvas origin in surface coordinates.
    public Origin: TuiPoint;

    // Creates a canvas clipped to `Bounds` intersected with the surface.
    //
    // Parameters:
    // - `Surface`: Working surface affected by the operation.
    // - `Bounds`: Rectangle affected by the operation.
    public static function Create(Surface: TuiWorkingSurface; Bounds: TuiRect): TuiCanvas;
    begin
      var Size: TuiSize := Surface.Size();
      var SurfaceBounds: TuiRect := TuiRect.Create(0, 0, Size.Width, Size.Height);
      return record
        Surface := Surface;
        Clip := Bounds.Intersect(SurfaceBounds);
        Origin := TuiPoint.Create(0, 0);
      end
    end;

    // Creates a canvas with an explicit surface origin and local clip rectangle.
    //
    // Parameters:
    // - `Surface`: Working surface affected by the operation.
    // - `Origin`: Canvas origin in surface coordinates.
    // - `Clip`: Clipping rectangle for drawing.
    public static function CreateLocal(Surface: TuiWorkingSurface; Origin: TuiPoint; Clip: TuiRect): TuiCanvas;
    begin
      return record
        Surface := Surface;
        Clip := Clip;
        Origin := Origin;
      end
    end;

    // Returns a nested canvas for `LocalBounds` in this canvas's local coordinates.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `LocalBounds`: Bounds expressed in the parent canvas coordinate system.
    public function Child(Self: TuiCanvas; LocalBounds: TuiRect): TuiCanvas;
    begin
      var Visible: TuiRect := LocalBounds.Intersect(Self.Clip);
      var ChildClip: TuiRect := TuiRect.Create(Visible.X - LocalBounds.X, Visible.Y - LocalBounds.Y, Visible.Width, Visible.Height);
      return TuiCanvas.CreateLocal(Self.Surface, TuiPoint.Create(Self.Origin.X + LocalBounds.X, Self.Origin.Y +
                                                                                                LocalBounds.Y), ChildClip)
    end;

    // Paints one cell in local coordinates; clipped and wide-glyph aware.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Position`: Position in terminal-cell coordinates.
    // - `Cell`: Terminal cell written by the operation.
    public procedure PutCell(Self: TuiCanvas; Position: TuiPoint; Cell: TuiCell);
    begin
      if not Self.Clip.Contains(Position) then
      begin
        return
      end;
      var CellWidth: integer := Cell.Width();
      if (CellWidth = 2) and not Self.Clip.Contains(TuiPoint.Create(Position.X + 1, Position.Y)) then
      begin
        Self.Surface.PutCell(TuiPoint.Create(Self.Origin.X + Position.X, Self.Origin.Y + Position.Y), TuiCell.Create(' ', TuiStyleRole.Normal));
        return
      end;

      Self.Surface.PutCell(TuiPoint.Create(Self.Origin.X + Position.X, Self.Origin.Y + Position.Y), Cell)
    end;

    // Paints one glyph with the normal role.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `X`: Zero-based horizontal terminal-cell coordinate.
    // - `Y`: Zero-based vertical terminal-cell coordinate.
    // - `Glyph`: Single renderable grapheme.
    public procedure PutGlyph(Self: TuiCanvas; X: integer; Y: integer; Glyph: string);
    begin
      Self.PutCell(TuiPoint.Create(X, Y), TuiCell.Create(Glyph, TuiStyleRole.Normal))
    end;

    // Fills the visible intersection with a one-column cell.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Bounds`: Rectangle affected by the operation.
    // - `Cell`: Terminal cell written by the operation.
    public procedure FillRect(Self: TuiCanvas; Bounds: TuiRect; Cell: TuiCell);
    begin
      var CellWidth: integer := Cell.Width();
      if CellWidth <> 1 then
      begin
        panic('Tui canvas FillRect requires a one-column cell')
      end;
      var Visible: TuiRect := Bounds.Intersect(Self.Clip);
      TuiSurfaceFillRect(Self.Surface, TuiRect.Create(Self.Origin.X + Visible.X, Self.Origin.Y +
                                                                                 Visible.Y, Visible.Width, Visible.Height), Cell)
    end;

    // Draws one logical line of text; stops before a newline.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Position`: Position in terminal-cell coordinates.
    // - `Text`: Text processed or displayed by the operation.
    // - `Role`: Semantic style role used by the operation.
    public procedure WriteText(Self: TuiCanvas; Position: TuiPoint; Text: string; Role: TuiStyleRole);
    begin
      mutable var X: integer := Position.X;
      mutable var AsciiOnly: boolean := true;
      var TextLength: integer := Std.Str.Length(Text);
      for Index: integer := 0 to TextLength - 1 do
      begin
        var Code: integer := Std.Str.Ord(Std.Str.CharAt(Text, Index));
        if (Code <> 10) and ((Code < 32) or (Code > 126)) then
        begin
          AsciiOnly := false
        end
      end;

      if AsciiOnly then
      begin
        for Index: integer := 0 to TextLength - 1 do
        begin
          var Glyph: string := Std.Str.CharAt(Text, Index);
          if Glyph = Std.Str.Chr(10) then
          begin
            return
          end;

          Self.PutCell(TuiPoint.Create(X, Position.Y), TuiCell.Create(Glyph, Role));
          X := X + 1
        end;

        return
      end;

      for Glyph: string in Std.Console.SplitGraphemes(Text) do
      begin
        if Glyph = Std.Str.Chr(10) then
        begin
          return
        end;

        var GlyphWidth: integer := Std.Console.DisplayWidth(Glyph);
        if GlyphWidth > 0 then
        begin
          Self.PutCell(TuiPoint.Create(X, Position.Y), TuiCell.Create(Glyph, Role));
          X := X + GlyphWidth
        end
      end
    end;

    // Draws a horizontal box-drawing line.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `X`: Zero-based horizontal terminal-cell coordinate.
    // - `Y`: Zero-based vertical terminal-cell coordinate.
    // - `Width`: Width in terminal cells.
    // - `Role`: Semantic style role used by the operation.
    public procedure DrawHorizontalLine(
  Self: TuiCanvas;
  X: integer;
  Y: integer;
  Width: integer;
  Role: TuiStyleRole
);
    begin
      var Cell: TuiCell := TuiCell.Create('─', Role);
      for Offset: integer := 0 to Width - 1 do
      begin
        Self.PutCell(TuiPoint.Create(X + Offset, Y), Cell)
      end
    end;

    // Draws a vertical box-drawing line.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `X`: Zero-based horizontal terminal-cell coordinate.
    // - `Y`: Zero-based vertical terminal-cell coordinate.
    // - `Height`: Height in terminal cells.
    // - `Role`: Semantic style role used by the operation.
    public procedure DrawVerticalLine(
  Self: TuiCanvas;
  X: integer;
  Y: integer;
  Height: integer;
  Role: TuiStyleRole
);
    begin
      var Cell: TuiCell := TuiCell.Create('│', Role);
      for Offset: integer := 0 to Height - 1 do
      begin
        Self.PutCell(TuiPoint.Create(X, Y + Offset), Cell)
      end
    end;

    // Draws a box frame using Unicode box-drawing glyphs.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Bounds`: Rectangle affected by the operation.
    // - `Role`: Semantic style role used by the operation.
    public procedure DrawFrame(Self: TuiCanvas; Bounds: TuiRect; Role: TuiStyleRole);
    begin
      if Bounds.IsEmpty() then
      begin
        return
      end;

      if Bounds.Width = 1 then
      begin
        Self.DrawVerticalLine(Bounds.X, Bounds.Y, Bounds.Height, Role);
        Self.PutCell(TuiPoint.Create(Bounds.X, Bounds.Y), TuiCell.Create('╭', Role));
        if Bounds.Height > 1 then
        begin
          Self.PutCell(TuiPoint.Create(Bounds.X, Bounds.Bottom() - 1), TuiCell.Create('╰', Role))
        end;

        return
      end;

      if Bounds.Height = 1 then
      begin
        Self.DrawHorizontalLine(Bounds.X, Bounds.Y, Bounds.Width, Role);
        Self.PutCell(TuiPoint.Create(Bounds.X, Bounds.Y), TuiCell.Create('╭', Role));
        Self.PutCell(TuiPoint.Create(Bounds.Right() - 1, Bounds.Y), TuiCell.Create('╮', Role));
        return
      end;

      Self.DrawHorizontalLine(Bounds.X, Bounds.Y, Bounds.Width, Role);
      Self.DrawHorizontalLine(Bounds.X, Bounds.Bottom() - 1, Bounds.Width, Role);
      Self.DrawVerticalLine(Bounds.X, Bounds.Y + 1, Bounds.Height - 2, Role);
      Self.DrawVerticalLine(Bounds.Right() - 1, Bounds.Y + 1, Bounds.Height - 2, Role);
      Self.PutCell(TuiPoint.Create(Bounds.X, Bounds.Y), TuiCell.Create('╭', Role));
      Self.PutCell(TuiPoint.Create(Bounds.Right() - 1, Bounds.Y), TuiCell.Create('╮', Role));
      Self.PutCell(TuiPoint.Create(Bounds.X, Bounds.Bottom() - 1), TuiCell.Create('╰', Role));
      Self.PutCell(TuiPoint.Create(Bounds.Right() - 1, Bounds.Bottom() - 1), TuiCell.Create('╯', Role))
    end;
  end;

// Flat panel and overlay chrome painting.
unit Std.Tui.Rendering.Chrome;

uses
  Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect,
  Std.Tui.Rendering.Canvas;

// Paints an opaque panel with a thin rounded frame and left-aligned title.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Title`: Title displayed by the panel.
public procedure TuiPaintPanel(Canvas: TuiCanvas; Bounds: TuiRect; Title: string);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;

  Canvas.FillRect(Bounds, TuiCell.Create(' ', TuiStyleRole.Normal));
  Canvas.DrawFrame(Bounds, TuiStyleRole.Frame);
  if (Title <> '') and (Bounds.Width > 6) then
  begin
    Canvas.Child(TuiRect.Create(Bounds.X + 2, Bounds.Y, Bounds.Width - 4, 1))
      .WriteText(TuiPoint.Create(0, 0), (' ' + Title) + ' ', TuiStyleRole.Title)
  end
end;

// One-line input painting.
unit Std.Tui.Rendering.Input;

uses
  Std.Str, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Chrome.Input, Std.Tui.Geometry.Point,
  Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas, Std.Tui.Text.Input;

// Paints one input with hint text, horizontal scroll markers, and a block cursor.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Input`: Controlled input specification.
// - `Focused`: Whether the control currently owns focus.
public procedure TuiPaintInput(Canvas: TuiCanvas; Bounds: TuiRect; Input: TuiInputSpec; Focused: boolean);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;
  mutable var Role: TuiStyleRole := TuiStyleRole.InputNormal;
  if Focused then
  begin
    Role := TuiStyleRole.InputFocused
  end;

  Canvas.FillRect(Bounds, TuiCell.Create(' ', Role));
  if Bounds.Width <= 2 then
  begin
    if Focused then
    begin
      Canvas.WriteText(TuiPoint.Create(Bounds.X, Bounds.Y), ' ', TuiStyleRole.InputCursor)
    end;

    return
  end;
  var ContentWidth: integer := Bounds.Width - 2;
  var Viewport: TuiInputViewport := TuiInputViewportFor(Input.Text, Input.Caret, ContentWidth);
  if Input.Text = '' then
  begin
    mutable var HintX: integer := Bounds.X + 1;
    mutable var HintWidth: integer := ContentWidth;
    if Focused and (HintWidth > 1) then
    begin
      HintX := HintX + 1;
      HintWidth := HintWidth - 1
    end;

    Canvas.Child(TuiRect.Create(HintX, Bounds.Y, HintWidth, 1))
      .WriteText(TuiPoint.Create(0, 0), Input.Hint, TuiStyleRole.InputHint)
  end
  else
  begin
    Canvas.Child(TuiRect.Create(Bounds.X + 1, Bounds.Y, ContentWidth, 1))
      .WriteText(TuiPoint.Create(0, 0), Std.Str.Substring(Input.Text, Viewport.Start, Viewport.EndIndex -
                                                                                      Viewport.Start), Role)
  end;

  if Viewport.LeftClipped then
  begin
    Canvas.WriteText(TuiPoint.Create(Bounds.X, Bounds.Y), '◄', TuiStyleRole.InputScroll)
  end;

  if Viewport.RightClipped then
  begin
    Canvas.WriteText(TuiPoint.Create(Bounds.Right() - 1, Bounds.Y), '►', TuiStyleRole.InputScroll)
  end;

  if Focused then
  begin
    mutable var CursorX: integer := (Bounds.X + 1) + Viewport.CaretColumn;
    if CursorX >= Bounds.Right() - 1 then
    begin
      CursorX := Bounds.Right() - 2
    end;
    mutable var CursorGlyph: string := ' ';
    if Input.Caret < Std.Str.Length(Input.Text) then
    begin
      CursorGlyph := Std.Str.CharAt(Input.Text, Input.Caret)
    end;

    Canvas.WriteText(TuiPoint.Create(CursorX, Bounds.Y), CursorGlyph, TuiStyleRole.InputCursor)
  end
end;

unit Std.Tui.Rendering.Menu;

uses
  Std.Arrays, Std.Console, Std.Str, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole,
  Std.Tui.Chrome.MenuGeometry, Std.Tui.Chrome.MenuNode, Std.Tui.Chrome.MenuQuery,
  Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas;

function TuiMenuIdMatches(Value: option of TuiMenuNodeId; Id: TuiMenuNodeId): boolean;
begin
  case Value of
    Some(Current):
    begin
      return Current.Value = Id.Value
    end;
    None:
    begin
      return false
    end
  end
end;

procedure TuiPaintMenuLabel(
  Canvas: TuiCanvas;
  Position: TuiPoint;
  Text: string;
  Mnemonic: string;
  Role: TuiStyleRole;
  MnemonicRole: TuiStyleRole
);
begin
  mutable var X: integer := Position.X;
  mutable var MnemonicPainted: boolean := false;
  for Index: integer := 0 to Std.Str.Length(Text) - 1 do
  begin
    var Glyph: string := Std.Str.CharAt(Text, Index);
    mutable var GlyphRole: TuiStyleRole := Role;
    if (not MnemonicPainted and (Mnemonic <> '')) and
       (Std.Str.ToLower(Glyph) = Std.Str.ToLower(Mnemonic)) then
    begin
      GlyphRole := MnemonicRole;
      MnemonicPainted := true
    end;

    Canvas.WriteText(TuiPoint.Create(X, Position.Y), Glyph, GlyphRole);
    X := X + Std.Console.DisplayWidth(Glyph)
  end
end;

// Paints the one-line root menu bar.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Nodes`: Flat ordered menu-node collection.
// - `State`: Controlled state used by the operation.
// - `Focused`: Whether the control currently owns focus.
public procedure TuiPaintMenuBar(
  Canvas: TuiCanvas;
  Bounds: TuiRect;
  Nodes: array of TuiMenuNode;
  State: TuiMenuState;
  Focused: boolean
);
begin
  Canvas.FillRect(Bounds, TuiCell.Create(' ', TuiStyleRole.MenuNormal));
  mutable var ActiveRoot: option of TuiMenuNodeId := None;
  case State.Active of
    Some(Active):
    begin
      ActiveRoot := TuiMenuRootOf(Nodes, Active)
    end;
    None:
    begin
    end
  end;
  mutable var X: integer := Bounds.X;
  for Index: integer := 0 to Std.Arrays.Length(Nodes) - 1 do
  begin
    case TuiMenuNodeParent(Nodes[Index]) of
      Some(Parent):
      begin
      end;
      None:
      begin
        var Id: TuiMenuNodeId := TuiMenuNodeIdOf(Nodes[Index]);
        var Text: string := TuiMenuNodeText(Nodes[Index]);
        var Width: integer := Std.Console.DisplayWidth(Text) + 2;
        mutable var Role: TuiStyleRole := TuiStyleRole.MenuNormal;
        if (State.Open and TuiMenuIdMatches(ActiveRoot, Id)) or
           ((Focused and not State.Open) and (X = Bounds.X)) then
        begin
          Role := TuiStyleRole.MenuSelected;
          Canvas.FillRect(TuiRect.Create(X, Bounds.Y, Width, 1), TuiCell.Create(' ', Role))
        end;

        if not TuiMenuNodeSelectable(Nodes[Index]) then
        begin
          Role := TuiStyleRole.MenuDisabled
        end;
        mutable var MnemonicRole: TuiStyleRole := TuiStyleRole.MenuShortcut;
        if Role = TuiStyleRole.MenuSelected then
        begin
          MnemonicRole := TuiStyleRole.MenuSelectedShortcut
        end
        else if Role = TuiStyleRole.MenuDisabled then
        begin
          MnemonicRole := TuiStyleRole.MenuDisabled
        end;

        TuiPaintMenuLabel(Canvas, TuiPoint.Create(X + 1, Bounds.Y), Text, TuiMenuNodeMnemonic(Nodes[Index]), Role, MnemonicRole);
        X := X + Width
      end
    end
  end
end;

procedure TuiPaintMenuPopupEntry(
  Canvas: TuiCanvas;
  Bounds: TuiRect;
  Y: integer;
  Node: TuiMenuNode;
  Id: TuiMenuNodeId;
  Text: string;
  Mnemonic: string;
  Enabled: boolean;
  State: TuiMenuState
);
begin
  mutable var Role: TuiStyleRole := TuiStyleRole.MenuNormal;
  if TuiMenuIdMatches(State.Active, Id) then
  begin
    Role := TuiStyleRole.MenuSelected;
    Canvas.FillRect(TuiRect.Create(Bounds.X + 1, Y, Bounds.Width - 2, 1), TuiCell.Create(' ', Role))
  end;

  if not Enabled then
  begin
    Role := TuiStyleRole.MenuDisabled
  end;
  mutable var MnemonicRole: TuiStyleRole := TuiStyleRole.MenuShortcut;
  if Role = TuiStyleRole.MenuSelected then
  begin
    MnemonicRole := TuiStyleRole.MenuSelectedShortcut
  end
  else if Role = TuiStyleRole.MenuDisabled then
  begin
    MnemonicRole := TuiStyleRole.MenuDisabled
  end;

  TuiPaintMenuLabel(Canvas, TuiPoint.Create(Bounds.X + 2, Y), Text, Mnemonic, Role, MnemonicRole);
  case TuiMenuNodeShortcut(Node) of
    Some(Gesture):
    begin
      Canvas.WriteText(TuiPoint.Create((Bounds.Right() - 2) -
                                       Std.Console.DisplayWidth(Gesture.Display), Y), Gesture.Display, Role)
    end;
    None:
    begin
    end
  end;

  if TuiMenuNodeIsSubmenu(Node) then
  begin
    Canvas.WriteText(TuiPoint.Create(Bounds.Right() - 2, Y), '▶', Role)
  end
end;

procedure TuiPaintMenuPopup(
  Canvas: TuiCanvas;
  Popup: TuiMenuPopup;
  Nodes: array of TuiMenuNode;
  State: TuiMenuState
);
begin
  var Bounds: TuiRect := Popup.Bounds;
  Canvas.FillRect(Bounds, TuiCell.Create(' ', TuiStyleRole.MenuNormal));
  Canvas.DrawFrame(Bounds, TuiStyleRole.MenuNormal);
  mutable var Row: integer := 0;
  for Index: integer := 0 to Std.Arrays.Length(Nodes) - 1 do
  begin
    if TuiMenuHasParent(Nodes[Index], Some(Popup.Parent)) then
    begin
      var Y: integer := (Bounds.Y + 1) + Row;
      case Nodes[Index] of
        TuiMenuNode.Separator(Id, Parent):
        begin
          Canvas.DrawHorizontalLine(Bounds.X + 1, Y, Bounds.Width - 2, TuiStyleRole.MenuNormal)
        end;
        TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
        begin
          TuiPaintMenuPopupEntry(Canvas, Bounds, Y, Nodes[Index], Id, Text, Mnemonic, Enabled, State)
        end;
        TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
        begin
          TuiPaintMenuPopupEntry(Canvas, Bounds, Y, Nodes[Index], Id, Text, Mnemonic, Enabled, State)
        end
      end;

      Row := Row + 1
    end
  end
end;

// Paints all open menu popups over the completed desktop frame.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `BarBounds`: Arranged bounds of the menu bar.
// - `Nodes`: Flat ordered menu-node collection.
// - `State`: Controlled state used by the operation.
public procedure TuiPaintMenuPopups(
  Canvas: TuiCanvas;
  BarBounds: TuiRect;
  Nodes: array of TuiMenuNode;
  State: TuiMenuState
);
begin
  var TerminalBounds: TuiRect := TuiRect.Create(0, 0, Canvas.Surface.Size().Width, Canvas.Surface.Size()
                                                                                     .Height);
  var Popups: array of TuiMenuPopup := TuiMenuPopupGeometry(Nodes, State, BarBounds, TerminalBounds);
  for Index: integer := 0 to Std.Arrays.Length(Popups) - 1 do
  begin
    TuiPaintMenuPopup(Canvas, Popups[Index], Nodes, State)
  end
end;

unit Std.Tui.Rendering.Paint;

uses
  Std.Arrays, Std.Console, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Chrome.StatusItem,
  Std.Tui.Elements.Element, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Geometry.Size,
  Std.Tui.Ids.ControlId, Std.Tui.Layout.Frame, Std.Tui.Rendering.Button, Std.Tui.Rendering.Canvas,
  Std.Tui.Rendering.CellGrid, Std.Tui.Rendering.Chrome, Std.Tui.Rendering.Gauge,
  Std.Tui.Rendering.Input, Std.Tui.Rendering.Menu, Std.Tui.Rendering.Rule,
  Std.Tui.Rendering.StatusLine, Std.Tui.Rendering.Surface, Std.Tui.Rendering.TextArea;

function TuiPaintFocused(Focused: option of TuiControlId; Id: TuiControlId): boolean;
begin
  case Focused of
    Some(Value):
    begin
      return Value.Value = Id.Value
    end;
    None:
    begin
      return false
    end
  end
end;

procedure TuiPaintTextInBounds(Canvas: TuiCanvas; Bounds: TuiRect; Text: string; Role: TuiStyleRole);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;

  Canvas.Child(Bounds).WriteText(TuiPoint.Create(0, 0), Text, Role)
end;

// Paints one arranged node and returns the next unused frame index.
function TuiPaintArranged(
  Canvas: TuiCanvas;
  Frame: TuiArrangedFrame;
  Node: TuiElement;
  Index: integer;
  Focused: option of TuiControlId;
  Pressed: option of TuiControlId
): integer;
begin
  var Entry: TuiArrangedEntry := Frame.EntryAt(Index);
  mutable var Next: integer := Index + 1;
  var Clipped: TuiCanvas := TuiCanvas.CreateLocal(Canvas.Surface, TuiPoint.Create(0, 0), Entry.Clip);
  case Node of
    TuiElement.Empty:
    begin
    end;
    TuiElement.Spacer(Value):
    begin
    end;
    TuiElement.Label(Text):
    begin
      TuiPaintTextInBounds(Clipped, Entry.Bounds, Text, TuiStyleRole.Normal)
    end;
    TuiElement.Button(Button):
    begin
      TuiPaintButton(Clipped, Entry.Bounds, Button, TuiPaintFocused(Focused, Button.Id), TuiPaintFocused(Pressed, Button.Id))
    end;
    TuiElement.Input(Input):
    begin
      TuiPaintInput(Clipped, Entry.Bounds, Input, TuiPaintFocused(Focused, Input.Id))
    end;
    TuiElement.TextArea(Id, Text, Caret, Offset, ChangeAction):
    begin
      TuiPaintTextArea(Clipped, Entry.Bounds, Text, Caret, Offset, TuiPaintFocused(Focused, Id), TuiStyleRole.Normal, TuiStyleRole.Focused)
    end;
    TuiElement.CheckBox(Id, Text, Checked, ChangeAction):
    begin
      mutable var Mark: string := ' ';
      if Checked then
      begin
        Mark := 'x'
      end;

      if TuiPaintFocused(Focused, Id) then
      begin
        TuiPaintTextInBounds(Clipped, Entry.Bounds, (('>[' + Mark) + '] ') + Text, TuiStyleRole.Focused)
      end
      else
      begin
        TuiPaintTextInBounds(Clipped, Entry.Bounds, ((' [' + Mark) + '] ') + Text, TuiStyleRole.Normal)
      end
    end;
    TuiElement.List(Id, Items, Selected, ChangeAction):
    begin
      mutable var RowLimit: integer := Entry.Bounds.Height;
      if RowLimit > Std.Arrays.Length(Items) then
      begin
        RowLimit := Std.Arrays.Length(Items)
      end;

      for Row: integer := 0 to RowLimit - 1 do
      begin
        mutable var Prefix: string := '  ';
        if Row = Selected then
        begin
          Prefix := '> '
        end;

        TuiPaintTextInBounds(Clipped, TuiRect.Create(Entry.Bounds.X, Entry.Bounds.Y + Row, Entry.Bounds.Width, 1), Prefix +
                                                                                                                   Items[Row], TuiStyleRole.Normal)
      end
    end;
    TuiElement.MenuBar(Items):
    begin
      Clipped.FillRect(Entry.Bounds, TuiCell.Create(' ', TuiStyleRole.MenuNormal));
      mutable var X: integer := Entry.Bounds.X;
      for ItemIndex: integer := 0 to Std.Arrays.Length(Items) - 1 do
      begin
        mutable var Role: TuiStyleRole := TuiStyleRole.MenuNormal;
        if Items[ItemIndex].Enabled and TuiPaintFocused(Focused, Items[ItemIndex].Id) then
        begin
          Role := TuiStyleRole.MenuSelected
        end
        else if not Items[ItemIndex].Enabled then
        begin
          Role := TuiStyleRole.MenuDisabled
        end;
        var ItemText: string := (' ' + Items[ItemIndex].Text) + ' ';
        Clipped.WriteText(TuiPoint.Create(X, Entry.Bounds.Y), ItemText, Role);
        X := X + Std.Console.DisplayWidth(ItemText)
      end
    end;
    TuiElement.Menu(Id, Nodes, State, ChangeAction):
    begin
      TuiPaintMenuBar(Clipped, Entry.Bounds, Nodes, State, TuiPaintFocused(Focused, Id))
    end;
    TuiElement.StatusLine(Items):
    begin
      TuiPaintStatusLine(Clipped, Entry.Bounds, Items, Focused)
    end;
    TuiElement.CellGrid(Grid):
    begin
      TuiPaintCellGrid(Clipped, Entry.Bounds, Grid)
    end;
    TuiElement.Rule(Text):
    begin
      TuiPaintRule(Clipped, Entry.Bounds, Text)
    end;
    TuiElement.Gauge(Gauge):
    begin
      TuiPaintGauge(Clipped, Entry.Bounds, Gauge)
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintArranged(Canvas, Frame, Children[ChildIndex], Next, Focused, Pressed)
      end
    end;
    TuiElement.Row(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintArranged(Canvas, Frame, Children[ChildIndex], Next, Focused, Pressed)
      end
    end;
    TuiElement.Column(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintArranged(Canvas, Frame, Children[ChildIndex], Next, Focused, Pressed)
      end
    end;
    TuiElement.Layout(Settings, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintArranged(Canvas, Frame, Children[ChildIndex], Next, Focused, Pressed)
      end
    end;
    TuiElement.Panel(Title, Children), TuiElement.Overlay(Title, Children):
    begin
      TuiPaintPanel(Clipped, Entry.Bounds, Title);
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintArranged(Canvas, Frame, Children[ChildIndex], Next, Focused, Pressed)
      end
    end;
    TuiElement.Desktop(DesktopFocus, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintArranged(Canvas, Frame, Children[ChildIndex], Next, DesktopFocus, Pressed)
      end
    end
  end;

  return Next
end;

function TuiPaintMenuOverlays(
  Canvas: TuiCanvas;
  Frame: TuiArrangedFrame;
  Node: TuiElement;
  Index: integer;
  AllowMenu: boolean
): integer;
begin
  mutable var Next: integer := Index + 1;
  case Node of
    TuiElement.Menu(Id, Nodes, State, ChangeAction):
    begin
      if AllowMenu and State.Open then
      begin
        TuiPaintMenuPopups(Canvas, Frame.EntryAt(Index).Bounds, Nodes, State)
      end
    end;
    TuiElement.Desktop(Focused, Children):
    begin
      mutable var ModalIndex: integer := -1;
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case Children[ChildIndex] of
          TuiElement.Overlay(Title, OverlayChildren):
          begin
            ModalIndex := ChildIndex
          end
          else
          begin
          end
        end
      end;

      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu and
                                                                                ((ModalIndex < 0) or (ModalIndex = ChildIndex)))
      end
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Row(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Column(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Layout(Settings, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Panel(Title, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Overlay(Title, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPaintMenuOverlays(Canvas, Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end
    else
    begin
    end
  end;

  return Next
end;

// Paints one complete frame using arranged geometry only (no measurement).
//
// Parameters:
// - `Surface`: Working surface affected by the operation.
// - `Frame`: Arranged frame containing element geometry.
// - `Root`: Root of the element tree.
// - `Pressed`: Whether the control is displayed as pressed.
public procedure TuiPaintView(
  Surface: TuiWorkingSurface;
  Frame: TuiArrangedFrame;
  Root: TuiElement;
  Pressed: option of TuiControlId
);
begin
  Surface.Clear();
  var Canvas: TuiCanvas := TuiCanvas.Create(Surface, TuiRectForSize(Surface.Size()));
  var NextIndex: integer := TuiPaintArranged(Canvas, Frame, Root, 0, None, Pressed);
  if NextIndex <> Frame.Count() then
  begin
    panic('Tui paint did not consume the complete arranged frame')
  end;

  if TuiPaintMenuOverlays(Canvas, Frame, Root, 0, true) <> Frame.Count() then
  begin
    panic('Tui menu overlay paint did not consume the complete arranged frame')
  end
end;

// Overwrites the surface with a terminal-too-small notice when layout overflows.
//
// Parameters:
// - `Surface`: Working surface affected by the operation.
public procedure TuiPaintTooSmallOverlay(Surface: TuiWorkingSurface);
begin
  Surface.Clear();
  var Size: TuiSize := Surface.Size();
  if Size.IsEmpty() then
  begin
    return
  end;
  var Canvas: TuiCanvas := TuiCanvas.Create(Surface, TuiRectForSize(Size));
  var Message: string := 'Terminal too small';
  mutable var X: integer := 0;
  if Size.Width > Std.Console.DisplayWidth(Message) then
  begin
    X := (Size.Width - Std.Console.DisplayWidth(Message)) div 2
  end;
  mutable var Y: integer := 0;
  if Size.Height > 1 then
  begin
    Y := Size.Height div 2
  end;

  Canvas.WriteText(TuiPoint.Create(X, Y), Message, TuiStyleRole.Warning)
end;

// Status-line painting with semantic shortcut and selection roles.
unit Std.Tui.Rendering.StatusLine;

uses
  Std.Arrays, Std.Console, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Chrome.StatusItem,
  Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Ids.ControlId, Std.Tui.Rendering.Canvas;

function TuiStatusFocused(Focused: option of TuiControlId; Id: TuiControlId): boolean;
begin
  case Focused of
    Some(Value):
    begin
      return Value.Value = Id.Value
    end;
    None:
    begin
      return false
    end
  end
end;

function TuiStatusWrite(Canvas: TuiCanvas; X: integer; Y: integer; Text: string; Role: TuiStyleRole): integer;
begin
  Canvas.WriteText(TuiPoint.Create(X, Y), Text, Role);
  return X + Std.Console.DisplayWidth(Text)
end;

// Paints one complete status row, including its unused background cells.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Items`: Ordered child or menu items.
// - `Focused`: Whether the control currently owns focus.
public procedure TuiPaintStatusLine(
  Canvas: TuiCanvas;
  Bounds: TuiRect;
  Items: array of TuiStatusItem;
  Focused: option of TuiControlId
);
begin
  Canvas.FillRect(Bounds, TuiCell.Create(' ', TuiStyleRole.StatusNormal));
  mutable var X: integer := Bounds.X;
  for Index: integer := 0 to Std.Arrays.Length(Items) - 1 do
  begin
    if Index > 0 then
    begin
      X := TuiStatusWrite(Canvas, X, Bounds.Y, ' ', TuiStyleRole.StatusNormal)
    end;

    case Items[Index] of
      TuiStatusItem.Hint(Text):
      begin
        X := TuiStatusWrite(Canvas, X, Bounds.Y, Text, TuiStyleRole.StatusNormal)
      end;
      TuiStatusItem.KeyHint(KeyText, Text):
      begin
        X := TuiStatusWrite(Canvas, X, Bounds.Y, KeyText, TuiStyleRole.StatusShortcut);
        X := TuiStatusWrite(Canvas, X, Bounds.Y, ' ', TuiStyleRole.StatusNormal);
        X := TuiStatusWrite(Canvas, X, Bounds.Y, Text, TuiStyleRole.StatusNormal)
      end;
      TuiStatusItem.Command(Id, Text, Action, Enabled):
      begin
        mutable var Role: TuiStyleRole := TuiStyleRole.StatusNormal;
        if not Enabled then
        begin
          Role := TuiStyleRole.StatusDisabled
        end
        else if TuiStatusFocused(Focused, Id) then
        begin
          Role := TuiStyleRole.StatusSelected
        end;

        X := TuiStatusWrite(Canvas, X, Bounds.Y, Text, Role)
      end
    end
  end
end;

unit Std.Tui.Rendering.TextArea;

uses
  Std.Arrays, Std.Str, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Geometry.Point,
  Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas, Std.Tui.Text.TextArea;

// Paints clipped text-area lines and a focused visible caret.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
// - `Offset`: Scroll offset or position applied by the operation.
// - `Focused`: Whether the control currently owns focus.
// - `NormalRole`: Style role used in the normal state.
// - `FocusedRole`: Style role used while the control owns focus.
public procedure TuiPaintTextArea(
  Canvas: TuiCanvas;
  Bounds: TuiRect;
  Text: string;
  Caret: integer;
  Offset: TuiPoint;
  Focused: boolean;
  NormalRole: TuiStyleRole;
  FocusedRole: TuiStyleRole
);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;
  var Area: TuiCanvas := Canvas.Child(Bounds);
  var Lines: array of string := Std.Str.Split(Text, Std.Str.Chr(10));
  var LineCount: integer := Std.Arrays.Length(Lines);
  for Row: integer := 0 to Bounds.Height - 1 do
  begin
    var Line: integer := Offset.Y + Row;
    if Line < LineCount then
    begin
      Area.WriteText(TuiPoint.Create(- Offset.X, Row), Lines[Line], NormalRole)
    end
  end;

  if Focused then
  begin
    var Position: TuiTextAreaPosition := TuiTextAreaLocate(Text, Caret);
    var CaretX: integer := Position.DisplayColumn - Offset.X;
    var CaretY: integer := Position.Line - Offset.Y;
    if (((CaretX >= 0) and (CaretX < Bounds.Width)) and (CaretY >= 0)) and (CaretY < Bounds.Height) then
    begin
      Area.PutCell(TuiPoint.Create(CaretX, CaretY), TuiCell.Create('▏', FocusedRole))
    end
  end
end;

unit Std.Tui.Runtime.Application;

uses
  Std.Arrays, Std.Console, Std.Options, Std.Results, Std.Task, Std.Tui.Cells.Palette,
  Std.Tui.Elements.Element, Std.Tui.Geometry.Size, Std.Tui.Rendering.Surface,
  Std.Tui.Runtime.Application.Background, Std.Tui.Runtime.Application.Loop,
  Std.Tui.Runtime.Application.State, Std.Tui.Runtime.Cmd, Std.Tui.Runtime.Input, Std.Tui.Runtime.Msg,
  Std.Tui.Runtime.PointerEvent, Std.Tui.Runtime.TerminalSession;

function TuiIgnoreApplicationMessage<TModel>(State: TModel; Message: boolean; Cmd: TuiCmdOutput): TModel;
begin
  return State
end;

public type
  // Headless Tui application host and deterministic message loop.
  TuiApplication = record
    // Stable identifier of the value.
    public Id: integer;

    // Opens a headless application with a fixed terminal size.
    //
    // Parameters:
    // - `Size`: Size in terminal cells.
    public static function OpenForTest(Size: TuiSize): TuiApplication;
    begin
      return TuiApplication.OpenForTestWithPalette(Size, TuiPalette.Default())
    end;

    // Opens a headless application with a caller-defined palette.
    //
    // Parameters:
    // - `Size`: Size in terminal cells.
    // - `Palette`: Palette used to resolve semantic style roles.
    public static function OpenForTestWithPalette(Size: TuiSize; Palette: TuiPalette): TuiApplication;
    begin
      return record
        Id := TuiAppOpenApplication(Size, Palette, false);
      end
    end;

    // Closes the host and discards all pending input and messages.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public procedure Close(Self: TuiApplication);
    begin
      TuiAppRaiseShutdownFailure(TuiAppCloseApplication(Self.Id))
    end;

    // Closes owned work before closing the application message inbox.
    public procedure CloseWithBackground<TMessage>(Self: TuiApplication; Inbox: channel of TMessage);
    begin
      var Failures: array of TuiMsg := TuiAppCloseApplication(Self.Id);
      CloseChannel(Inbox);
      TuiAppRaiseShutdownFailure(Failures)
    end;

    // Injects an already constructed framework message in FIFO order.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Msg`: Framework message injected into the application.
    public procedure Inject(Self: TuiApplication; Msg: TuiMsg);
    begin
      var ApplicationId: integer := TuiAppRequireOpen(Self.Id);
      TuiAppPushInput(ApplicationId, TuiHostInput.Message(Msg))
    end;

    // Injects a key that will be routed through focus and controlled elements.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Key`: Console key event to route or match.
    public procedure InjectKeyForTest(Self: TuiApplication; Key: Std.Console.KeyEvent);
    begin
      var ApplicationId: integer := TuiAppRequireOpen(Self.Id);
      TuiAppPushInput(ApplicationId, TuiHostInput.Key(Key))
    end;

    // Injects a pointer event in zero-based application coordinates.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Pointer`: Normalized pointer event to route.
    public procedure InjectPointerForTest(Self: TuiApplication; Pointer: TuiPointerEvent);
    begin
      var ApplicationId: integer := TuiAppRequireOpen(Self.Id);
      TuiAppPushInput(ApplicationId, TuiHostInput.Pointer(Pointer))
    end;

    // Injects a resize that updates host size before the Resize message reaches Update.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Size`: Size in terminal cells.
    public procedure InjectResizeForTest(Self: TuiApplication; Size: TuiSize);
    begin
      var ApplicationId: integer := TuiAppRequireOpen(Self.Id);
      TuiAppPushInput(ApplicationId, TuiHostInput.Resize(Size))
    end;

    // Tries to inject one application-defined message without waiting for queue capacity.
    public function InjectBackgroundForTest<TMessage>(
  Self: TuiApplication;
  Inbox: channel of TMessage;
  Message: TMessage
): result of boolean, string;
    begin
      TuiAppRequireOpen(Self.Id);
      return TrySend(Inbox, Message)
    end;

    // Returns an explicit immutable copy of the last painted surface.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function SurfaceSnapshot(Self: TuiApplication): TuiSurfaceSnapshot;
    begin
      var ApplicationId: integer := TuiAppRequireHandle(Self.Id);
      return TuiAppSurfaces[ApplicationId - 1].Snapshot()
    end;

    // Returns the application's current palette.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Palette(Self: TuiApplication): TuiPalette;
    begin
      var ApplicationId: integer := TuiAppRequireHandle(Self.Id);
      return TuiAppPalettes[ApplicationId - 1]
    end;

    // Runs a deterministic number of message-processing iterations.
    //
    // Type parameters:
    // - `TModel`: Application model type managed by the runtime.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `InitialModel`: Initial application model.
    // - `Update`: Callback that updates the application model and command output.
    // - `View`: Callback that renders the current application model.
    // - `IterationCount`: Number of application iterations to execute.
    // - `DeltaMilliseconds`: Elapsed time in milliseconds.
    public function RunIterations<TModel>(
  Self: TuiApplication;
  InitialModel: TModel;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement;
  IterationCount: integer;
  DeltaMilliseconds: integer
): TModel;
    begin
      var Inbox: channel of boolean := CreateChannel(1);
      var Model: TModel := TuiRunHeadless(Self.Id, InitialModel, Inbox, Update, TuiIgnoreApplicationMessage, View, IterationCount, DeltaMilliseconds, false);
      CloseChannel(Inbox);
      return Model
    end;

    // Runs deterministic framework and application-defined message iterations.
    public function RunBackgroundIterations<TModel, TMessage>(
  Self: TuiApplication;
  InitialModel: TModel;
  Inbox: channel of TMessage;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  UpdateApplication: function(State: TModel; Message: TMessage; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement;
  IterationCount: integer;
  DeltaMilliseconds: integer
): TModel;
    begin
      return TuiRunHeadless(Self.Id, InitialModel, Inbox, Update, UpdateApplication, View, IterationCount, DeltaMilliseconds, true)
    end;

    // Runs one interactive Tui application until Update returns `TuiCmd.Quit`.
    //
    // Type parameters:
    // - `TModel`: Application model type managed by the runtime.
    //
    // Parameters:
    // - `InitialModel`: Initial application model.
    // - `Update`: Callback that updates the application model and command output.
    // - `View`: Callback that renders the current application model.
    public static function Run<TModel>(
  InitialModel: TModel;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement
): TModel;
    begin
      return TuiApplication.RunWithPalette(InitialModel, Update, View, TuiPalette.Default())
    end;

    // Runs one interactive Tui application with a caller-defined initial palette.
    //
    // Type parameters:
    // - `TModel`: Application model type managed by the runtime.
    //
    // Parameters:
    // - `InitialModel`: Initial application model.
    // - `Update`: Callback that updates the application model and command output.
    // - `View`: Callback that renders the current application model.
    // - `Palette`: Palette used to resolve semantic style roles.
    public static function RunWithPalette<TModel>(
  InitialModel: TModel;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement;
  Palette: TuiPalette
): TModel;
    begin
      TuiTerminalSessionAcquire();
      mutable var Width: integer := ScreenWidth();
      mutable var Height: integer := ScreenHeight();
      if Width < 1 then
      begin
        Width := 1
      end;

      if Height < 1 then
      begin
        Height := 1
      end;
      var Size: TuiSize := TuiSize.Create(Width, Height);
      var App: TuiApplication := record
        Id := TuiAppOpenApplication(Size, Palette, true);
      end;
      var Inbox: channel of boolean := CreateChannel(1);
      var Model: TModel := TuiRunInteractive(App.Id, InitialModel, Inbox, Update, TuiIgnoreApplicationMessage, View, false);
      CloseChannel(Inbox);
      return Model
    end;

    // Runs one interactive application with a bounded typed background inbox.
    public static function RunWithBackground<TModel, TMessage>(
  InitialModel: TModel;
  Inbox: channel of TMessage;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  UpdateApplication: function(State: TModel; Message: TMessage; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement
): TModel;
    begin
      return TuiApplication.RunWithBackgroundAndPalette(InitialModel, Inbox, Update, UpdateApplication, View, TuiPalette.Default())
    end;

    // Runs one interactive background-enabled application with a caller-defined palette.
    public static function RunWithBackgroundAndPalette<TModel, TMessage>(
  InitialModel: TModel;
  Inbox: channel of TMessage;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  UpdateApplication: function(State: TModel; Message: TMessage; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement;
  Palette: TuiPalette
): TModel;
    begin
      TuiTerminalSessionAcquire();
      mutable var Width: integer := ScreenWidth();
      mutable var Height: integer := ScreenHeight();
      if Width < 1 then
      begin
        Width := 1
      end;

      if Height < 1 then
      begin
        Height := 1
      end;
      var App: TuiApplication := record
        Id := TuiAppOpenApplication(TuiSize.Create(Width, Height), Palette, true);
      end;

      return TuiRunInteractive(App.Id, InitialModel, Inbox, Update, UpdateApplication, View, true)
    end;
  end;

unit Std.Tui.Runtime.Application.Background;

uses Std.Arrays, Std.Options, Std.Results, Std.Task, Std.Tui.Runtime.Msg;

public type
  // Cooperative function executed as host-owned background work.
  TuiBackgroundWork = function(Token: CancellationToken): result of boolean, string;
  // Work requested by one completed Update callback.
  TuiBackgroundCommand = enum
    // Starts one independently owned operation.
    Start(Id: integer; Work: TuiBackgroundWork);
    // Requests cancellation and defers the latest replacement until the old source ends.
    ReplaceSubscription(Id: integer; Work: TuiBackgroundWork);
    // Requests cancellation and clears any pending replacement with the matching id.
    CancelSubscription(Id: integer);
  end;

type
  TuiOwnedWork = record
    Id: integer;
    Subscription: boolean;
    Group: TaskGroup;
    Cancelling: boolean;
    Replacement: option of TuiBackgroundWork;
  end;

mutable var
  TuiBackgroundOpen: array of boolean := [];
  TuiBackgroundWorkItems: array of array of TuiOwnedWork := [];

function TuiBackgroundRequireOpen(ApplicationId: integer): integer;
begin
  if ((ApplicationId < 1) or (ApplicationId > Std.Arrays.Length(TuiBackgroundOpen))) or
     not TuiBackgroundOpen[ApplicationId - 1] then
  begin
    panic('Tui background host is closed')
  end;

  return ApplicationId
end;

procedure TuiBackgroundRemove(ApplicationId: integer; Index: integer);
begin
  mutable var Items: array of TuiOwnedWork := TuiBackgroundWorkItems[ApplicationId - 1];
  TuiBackgroundWorkItems[ApplicationId - 1] := Std.Arrays.Concat(Std.Arrays.Slice(Items, 0, Index), Std.Arrays.Slice(Items, Index +
                                                                                                                            1, (Std.Arrays.Length(Items) - Index) -
                                                                                                                               1))
end;

function TuiBackgroundFailureMessages(
  Id: integer;
  Failures: array of TaskFailure;
  IncludeCancellation: boolean
): array of TuiMsg;
begin
  mutable var Messages: array of TuiMsg := [];
  for Failure: TaskFailure in Failures do
  begin
    if IncludeCancellation or (Failure.Kind <> TaskFailureKind.Cancelled) then
    begin
      Std.Arrays.Push(Messages, TuiMsg.BackgroundFailed(Id, Failure.Kind, Failure.Message, Failure.Code, Failure.Line, Failure.Column))
    end
  end;

  return Messages
end;

function TuiBackgroundCloseAt(ApplicationId: integer; Index: integer; IncludeCancellation: boolean): array of TuiMsg;
begin
  var Item: TuiOwnedWork := TuiBackgroundWorkItems[ApplicationId - 1][Index];
  var Messages: array of TuiMsg := TuiBackgroundFailureMessages(Item.Id, CloseTaskGroup(Item.Group), IncludeCancellation);
  TuiBackgroundRemove(ApplicationId, Index);
  return Messages
end;

function TuiBackgroundFindSubscription(ApplicationId: integer; Id: integer): integer;
begin
  mutable var Items: array of TuiOwnedWork := TuiBackgroundWorkItems[ApplicationId - 1];
  for Index: integer := 0 to Std.Arrays.Length(Items) - 1 do
  begin
    if Items[Index].Subscription and (Items[Index].Id = Id) then
    begin
      return Index
    end
  end;

  return -1
end;

procedure TuiBackgroundStart(
  ApplicationId: integer;
  Id: integer;
  Subscription: boolean;
  Work: TuiBackgroundWork
);
begin
  mutable var Items: array of TuiOwnedWork := TuiBackgroundWorkItems[ApplicationId - 1];
  if Std.Arrays.Length(Items) >= 256 then
  begin
    panic('Tui application cannot own more than 256 background operations')
  end;
  var Group: TaskGroup := CreateTaskGroup();
  StartTaskInGroup(Group, Work);
  Std.Arrays.Push(Items, record
    Id := Id;
    Subscription := Subscription;
    Group := Group;
    Cancelling := false;
    Replacement := None;
  end);
  TuiBackgroundWorkItems[ApplicationId - 1] := Items
end;

procedure TuiBackgroundRequestStop(
  ApplicationId: integer;
  Index: integer;
  Replacement: option of TuiBackgroundWork
);
begin
  mutable var Items: array of TuiOwnedWork := TuiBackgroundWorkItems[ApplicationId - 1];
  CancelTaskGroup(Items[Index].Group);
  Items[Index].Cancelling := true;
  Items[Index].Replacement := Replacement;
  TuiBackgroundWorkItems[ApplicationId - 1] := Items
end;

// Allocates the background ownership slot for a new application.
public procedure TuiBackgroundOpenApplication();
begin
  TuiBackgroundOpen := Std.Arrays.Concat(TuiBackgroundOpen, [true]);
  TuiBackgroundWorkItems := Std.Arrays.Concat(TuiBackgroundWorkItems, [[]])
end;

// Requests cancellation without joining on the UI path; replacement admission is deferred to reap.
public function TuiBackgroundApply(ApplicationId: integer; Commands: array of TuiBackgroundCommand): array of TuiMsg;
begin
  TuiBackgroundRequireOpen(ApplicationId);
  for Command: TuiBackgroundCommand in Commands do
  begin
    case Command of
      TuiBackgroundCommand.Start(Id, Work):
      begin
        TuiBackgroundStart(ApplicationId, Id, false, Work)
      end;
      TuiBackgroundCommand.ReplaceSubscription(Id, Work):
      begin
        var Existing: integer := TuiBackgroundFindSubscription(ApplicationId, Id);
        if Existing >= 0 then
        begin
          TuiBackgroundRequestStop(ApplicationId, Existing, Some(Work))
        end
        else
        begin
          TuiBackgroundStart(ApplicationId, Id, true, Work)
        end
      end;
      TuiBackgroundCommand.CancelSubscription(Id):
      begin
        var Existing: integer := TuiBackgroundFindSubscription(ApplicationId, Id);
        if Existing >= 0 then
        begin
          TuiBackgroundRequestStop(ApplicationId, Existing, None)
        end
      end
    end
  end;

  return []
end;

// Reports whether an application currently owns any operation.
public function TuiBackgroundHasWork(ApplicationId: integer): boolean;
begin
  TuiBackgroundRequireOpen(ApplicationId);
  return Std.Arrays.Length(TuiBackgroundWorkItems[ApplicationId - 1]) > 0
end;

// Collects completed groups and starts only the latest pending replacement after its predecessor ends.
public function TuiBackgroundReap(ApplicationId: integer): array of TuiMsg;
begin
  TuiBackgroundRequireOpen(ApplicationId);
  mutable var Messages: array of TuiMsg := [];
  mutable var Index: integer := Std.Arrays.Length(TuiBackgroundWorkItems[ApplicationId - 1]) - 1;
  while Index >= 0 do
  begin
    var Item: TuiOwnedWork := TuiBackgroundWorkItems[ApplicationId - 1][Index];
    case TryCloseCompletedTaskGroup(Item.Group) of
      Some(Failures):
      begin
        Messages := Std.Arrays.Concat(Messages, TuiBackgroundFailureMessages(Item.Id, Failures, not Item.Cancelling));
        TuiBackgroundRemove(ApplicationId, Index);
        case Item.Replacement of
          Some(Work):
          begin
            TuiBackgroundStart(ApplicationId, Item.Id, true, Work)
          end;
          None:
          begin
          end
        end
      end;
      None:
      begin
      end
    end;

    Index := Index - 1
  end;

  return Messages
end;

// Cancels and joins all owned work at shutdown without starting pending replacements.
public function TuiBackgroundCloseApplication(ApplicationId: integer): array of TuiMsg;
begin
  if ((ApplicationId < 1) or (ApplicationId > Std.Arrays.Length(TuiBackgroundOpen))) or
     not TuiBackgroundOpen[ApplicationId - 1] then
  begin
    return []
  end;
  mutable var Messages: array of TuiMsg := [];
  while Std.Arrays.Length(TuiBackgroundWorkItems[ApplicationId - 1]) > 0 do
  begin
    Messages := Std.Arrays.Concat(Messages, TuiBackgroundCloseAt(ApplicationId, Std.Arrays.Length(TuiBackgroundWorkItems[ApplicationId -
                                                                                                                         1]) -
                                                                                1, false))
  end;

  TuiBackgroundOpen[ApplicationId - 1] := false;
  return Messages
end;

unit Std.Tui.Runtime.Application.Loop;

uses
  Std.Arrays, Std.Console, Std.Options, Std.Results, Std.Task, Std.Time, Std.Tui.Cells.Palette,
  Std.Tui.Elements.Element, Std.Tui.Runtime.Application.Background,
  Std.Tui.Runtime.Application.State, Std.Tui.Runtime.Cmd, Std.Tui.Runtime.ConsoleEvents,
  Std.Tui.Runtime.Frame, Std.Tui.Runtime.Input, Std.Tui.Runtime.Msg, Std.Tui.Runtime.Routing.Pointer,
  Std.Tui.Runtime.TerminalRenderer;

procedure TuiLoopRender(ApplicationId: integer; Tree: TuiElement; Present: boolean);
begin
  TuiRenderFrame(TuiAppSurfaces[ApplicationId - 1], TuiAppFrames[ApplicationId - 1], Tree, Std.Tui.Runtime.Routing.Pointer.TuiPointerRoutingPressed(ApplicationId));
  TuiAppTrees[ApplicationId - 1] := Tree;
  if Present then
  begin
    TuiFlushSurface(TuiAppSurfaces[ApplicationId - 1], TuiAppPalettes[ApplicationId - 1])
  end
end;

function TuiLoopApplyFramework<TModel>(
  ApplicationId: integer;
  Model: TModel;
  Msg: TuiMsg;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel
): TModel;
begin
  TuiAppApplyResizeIfNeeded(ApplicationId, Msg);
  var Cmd: TuiCmdOutput := TuiAppCommands[ApplicationId - 1];
  Cmd.Reset();
  return Update(Model, Msg, Cmd)
end;

function TuiLoopApplyApplication<TModel, TMessage>(
  ApplicationId: integer;
  Model: TModel;
  Message: TMessage;
  UpdateApplication: function(State: TModel; Message: TMessage; Cmd: TuiCmdOutput): TModel
): TModel;
begin
  var Cmd: TuiCmdOutput := TuiAppCommands[ApplicationId - 1];
  Cmd.Reset();
  return UpdateApplication(Model, Message, Cmd)
end;

function TuiLoopFinishUpdate<TModel>(
  ApplicationId: integer;
  Model: TModel;
  View: function(State: TModel): TuiElement;
  Present: boolean
): boolean;
begin
  var Cmd: TuiCmdOutput := TuiAppCommands[ApplicationId - 1];
  if TuiAppApplyCommand(ApplicationId, Cmd) then
  begin
    return true
  end;

  TuiLoopRender(ApplicationId, View(Model), Present);
  return false
end;

procedure TuiLoopClose(ApplicationId: integer);
begin
  TuiAppRaiseShutdownFailure(TuiAppCloseApplication(ApplicationId))
end;

procedure TuiLoopCloseWithInbox<TMessage>(ApplicationId: integer; Inbox: channel of TMessage);
begin
  var Failures: array of TuiMsg := TuiAppCloseApplication(ApplicationId);
  CloseChannel(Inbox);
  TuiAppRaiseShutdownFailure(Failures)
end;

// Runs a deterministic bounded headless loop with an optional typed inbox.
public function TuiRunHeadless<TModel, TMessage>(
  ApplicationId: integer;
  InitialModel: TModel;
  Inbox: channel of TMessage;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  UpdateApplication: function(State: TModel; Message: TMessage; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement;
  IterationCount: integer;
  DeltaMilliseconds: integer;
  BackgroundEnabled: boolean
): TModel;
begin
  TuiAppRequireOpen(ApplicationId);
  if IterationCount < 0 then
  begin
    panic('Tui iteration count must not be negative')
  end;

  if DeltaMilliseconds < 0 then
  begin
    panic('Tui tick delta must not be negative')
  end;
  mutable var Model: TModel := InitialModel;
  TuiLoopRender(ApplicationId, View(Model), false);
  if BackgroundEnabled then
  begin
    TuiAppStart(ApplicationId)
  end;
  mutable var Remaining: integer := IterationCount;
  while Remaining > 0 do
  begin
    if not TuiAppOpen[ApplicationId - 1] then
    begin
      return Model
    end;

    TuiAppPushMessages(ApplicationId, TuiBackgroundReap(ApplicationId));
    if (Std.Arrays.Length(TuiAppMessages[ApplicationId - 1]) = 0) and
       (Std.Arrays.Length(TuiAppInputs[ApplicationId - 1]) > 0) then
    begin
      TuiAppRouteInput(ApplicationId, TuiAppPopInput(ApplicationId));
      if Std.Arrays.Length(TuiAppMessages[ApplicationId - 1]) = 0 then
      begin
        continue
      end
    end;

    if Std.Arrays.Length(TuiAppMessages[ApplicationId - 1]) > 0 then
    begin
      Remaining := Remaining - 1;
      Model := TuiLoopApplyFramework(ApplicationId, Model, TuiAppPopMessage(ApplicationId), Update);
      if TuiLoopFinishUpdate(ApplicationId, Model, View, false) then
      begin
        if BackgroundEnabled then
        begin
          TuiLoopCloseWithInbox(ApplicationId, Inbox)
        end
        else
        begin
          TuiLoopClose(ApplicationId)
        end;

        return Model
      end
    end
    else if BackgroundEnabled then
    begin
      case Std.Results.Unwrap(TryReceive(Inbox)) of
        Some(Message):
        begin
          Remaining := Remaining - 1;
          Model := TuiLoopApplyApplication(ApplicationId, Model, Message, UpdateApplication);
          if TuiLoopFinishUpdate(ApplicationId, Model, View, false) then
          begin
            TuiLoopCloseWithInbox(ApplicationId, Inbox);
            return Model
          end
        end;
        None:
        begin
          Remaining := Remaining - 1;
          Model := TuiLoopApplyFramework(ApplicationId, Model, TuiMsg.Tick(DeltaMilliseconds), Update);
          if TuiLoopFinishUpdate(ApplicationId, Model, View, false) then
          begin
            TuiLoopCloseWithInbox(ApplicationId, Inbox);
            return Model
          end
        end
      end
    end
    else
    begin
      Remaining := Remaining - 1;
      Model := TuiLoopApplyFramework(ApplicationId, Model, TuiMsg.Tick(DeltaMilliseconds), Update);
      if TuiLoopFinishUpdate(ApplicationId, Model, View, false) then
      begin
        TuiLoopClose(ApplicationId);
        return Model
      end
    end
  end;

  return Model
end;

function TuiConsoleInputPump(Token: CancellationToken; Output: channel of TuiHostInput): result of boolean, string;
begin
  while not IsCancellationRequested(Token) do
  begin
    case TuiReadConsoleHostInputWithTimeout(50) of
      Some(Input):
      begin
        if IsError(SendWithCancellation(Output, Input, Token)) then
        begin
          return Ok(true)
        end
      end;
      None:
      begin
      end
    end;

    // Release the pool worker even when Console polling returns no event.
    Sleep(0)
  end;

  return Ok(true)
end;

// Runs the interactive loop, selecting fairly between Console and application messages.
public function TuiRunInteractive<TModel, TMessage>(
  ApplicationId: integer;
  InitialModel: TModel;
  Inbox: channel of TMessage;
  Update: function(State: TModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TModel;
  UpdateApplication: function(State: TModel; Message: TMessage; Cmd: TuiCmdOutput): TModel;
  View: function(State: TModel): TuiElement;
  BackgroundEnabled: boolean
): TModel;
begin
  TuiAppRequireOpen(ApplicationId);
  var ConsoleInputs: channel of TuiHostInput := CreateChannel(32);
  var InputGroup: TaskGroup := CreateTaskGroup();
  StartTaskInGroup(InputGroup, function(Token: CancellationToken): result of boolean, string begin
    return TuiConsoleInputPump(Token, ConsoleInputs)
  end);
  mutable var Model: TModel := InitialModel;
  TuiLoopRender(ApplicationId, View(Model), true);
  if BackgroundEnabled then
  begin
    TuiAppStart(ApplicationId)
  end;
  mutable var PreferApplication: boolean := false;
  while TuiAppOpen[ApplicationId - 1] do
  begin
    TuiAppPushMessages(ApplicationId, TuiBackgroundReap(ApplicationId));
    if Std.Arrays.Length(TuiAppMessages[ApplicationId - 1]) > 0 then
    begin
      Model := TuiLoopApplyFramework(ApplicationId, Model, TuiAppPopMessage(ApplicationId), Update);
      if TuiLoopFinishUpdate(ApplicationId, Model, View, true) then
      begin
        CloseTaskGroup(InputGroup);
        CloseChannel(ConsoleInputs);
        if BackgroundEnabled then
        begin
          TuiLoopCloseWithInbox(ApplicationId, Inbox)
        end
        else
        begin
          TuiLoopClose(ApplicationId)
        end;

        return Model
      end;

      continue
    end;

    if Std.Arrays.Length(TuiAppInputs[ApplicationId - 1]) > 0 then
    begin
      TuiAppRouteInput(ApplicationId, TuiAppPopInput(ApplicationId));
      continue
    end;
    mutable var ConsoleInput: option of TuiHostInput := None;
    mutable var ApplicationInput: option of TMessage := None;
    mutable var Cases: array of WaitCase := [];
    var ConsoleCase: WaitCase := ReceiveCase(ConsoleInputs, procedure(Outcome: result of TuiHostInput, string) begin
      case Outcome of
        Ok(Input):
        begin
          ConsoleInput := Some(Input)
        end;
        Error(Message):
        begin
        end
      end
    end);
    if BackgroundEnabled then
    begin
      var ApplicationCase: WaitCase := ReceiveCase(Inbox, procedure(Outcome: result of TMessage, string) begin
        case Outcome of
          Ok(Message):
          begin
            ApplicationInput := Some(Message)
          end;
          Error(Failure):
          begin
          end
        end
      end);
      if PreferApplication then
      begin
        Std.Arrays.Push(Cases, ApplicationCase);
        Std.Arrays.Push(Cases, ConsoleCase)
      end
      else
      begin
        Std.Arrays.Push(Cases, ConsoleCase);
        Std.Arrays.Push(Cases, ApplicationCase)
      end
    end
    else
    begin
      Std.Arrays.Push(Cases, ConsoleCase)
    end;

    if TuiBackgroundHasWork(ApplicationId) then
    begin
      Std.Arrays.Push(Cases, TimerCase(50, procedure() begin end))
    end;

    Select(Cases);
    PreferApplication := not PreferApplication;
    case ConsoleInput of
      Some(Input):
      begin
        TuiAppRouteInput(ApplicationId, Input)
      end;
      None:
      begin
      end
    end;

    case ApplicationInput of
      Some(Message):
      begin
        Model := TuiLoopApplyApplication(ApplicationId, Model, Message, UpdateApplication);
        if TuiLoopFinishUpdate(ApplicationId, Model, View, true) then
        begin
          CloseTaskGroup(InputGroup);
          CloseChannel(ConsoleInputs);
          TuiLoopCloseWithInbox(ApplicationId, Inbox);
          return Model
        end
      end;
      None:
      begin
      end
    end
  end;

  CloseTaskGroup(InputGroup);
  CloseChannel(ConsoleInputs);
  if BackgroundEnabled then
  begin
    TuiLoopCloseWithInbox(ApplicationId, Inbox)
  end
  else
  begin
    TuiLoopClose(ApplicationId)
  end;

  return Model
end;

unit Std.Tui.Runtime.Application.State;

uses
  Std.Arrays, Std.Options, Std.Tui.Cells.Palette, Std.Tui.Elements.Element, Std.Tui.Geometry.Size,
  Std.Tui.Layout.Frame, Std.Tui.Rendering.Surface, Std.Tui.Runtime.Application.Background,
  Std.Tui.Runtime.Cmd, Std.Tui.Runtime.Input, Std.Tui.Runtime.Msg, Std.Tui.Runtime.Routing,
  Std.Tui.Runtime.Routing.Pointer, Std.Tui.Runtime.TerminalSession;

public mutable var
  TuiAppOpen: array of boolean := [];
  TuiAppInputs: array of array of TuiHostInput := [];
  TuiAppMessages: array of array of TuiMsg := [];
  TuiAppSurfaces: array of TuiWorkingSurface := [];
  TuiAppFrames: array of TuiArrangedFrame := [];
  TuiAppTrees: array of TuiElement := [];
  TuiAppCommands: array of TuiCmdOutput := [];
  TuiAppInteractive: array of boolean := [];
  TuiAppPalettes: array of TuiPalette := [];
  TuiAppStarted: array of boolean := [];

// Opens application-owned state and returns its stable identifier.
public function TuiAppOpenApplication(Size: TuiSize; Palette: TuiPalette; Interactive: boolean): integer;
begin
  TuiAppOpen := Std.Arrays.Concat(TuiAppOpen, [true]);
  TuiAppInputs := Std.Arrays.Concat(TuiAppInputs, [[]]);
  TuiAppMessages := Std.Arrays.Concat(TuiAppMessages, [[]]);
  TuiAppSurfaces := Std.Arrays.Concat(TuiAppSurfaces, [TuiWorkingSurface.Create(Size)]);
  TuiAppFrames := Std.Arrays.Concat(TuiAppFrames, [TuiArrangedFrame.Create()]);
  TuiAppTrees := Std.Arrays.Concat(TuiAppTrees, [TuiElement.Empty]);
  TuiAppCommands := Std.Arrays.Concat(TuiAppCommands, [TuiCmdOutput.Create()]);
  TuiAppInteractive := Std.Arrays.Concat(TuiAppInteractive, [Interactive]);
  TuiAppPalettes := Std.Arrays.Concat(TuiAppPalettes, [Palette]);
  TuiAppStarted := Std.Arrays.Concat(TuiAppStarted, [false]);
  TuiBackgroundOpenApplication();
  Std.Tui.Runtime.Routing.Pointer.TuiPointerRoutingOpen();
  return Std.Arrays.Length(TuiAppOpen)
end;

// Cancels owned work, closes application state, and returns shutdown failures.
public function TuiAppCloseApplication(ApplicationId: integer): array of TuiMsg;
begin
  if (ApplicationId < 1) or (ApplicationId > Std.Arrays.Length(TuiAppOpen)) then
  begin
    return []
  end;

  if not TuiAppOpen[ApplicationId - 1] then
  begin
    return []
  end;
  var BackgroundFailures: array of TuiMsg := TuiBackgroundCloseApplication(ApplicationId);
  TuiAppOpen[ApplicationId - 1] := false;
  TuiAppInputs[ApplicationId - 1] := [];
  TuiAppMessages[ApplicationId - 1] := [];
  Std.Tui.Runtime.Routing.Pointer.TuiPointerRoutingClose(ApplicationId);
  if TuiAppInteractive[ApplicationId - 1] then
  begin
    TuiAppInteractive[ApplicationId - 1] := false;
    TuiTerminalSessionRelease()
  end;

  return BackgroundFailures
end;

// Raises the first shutdown failure after application resources have been released.
public procedure TuiAppRaiseShutdownFailure(Failures: array of TuiMsg);
begin
  if Std.Arrays.Length(Failures) = 0 then
  begin
    return
  end;

  case Failures[0] of
    TuiMsg.BackgroundFailed(IgnoredId, Kind, Message, Code, Line, Column):
    begin
      panic(Message)
    end
    else
    begin
      panic('Tui background operation failed during shutdown')
    end
  end
end;

public function TuiAppRequireHandle(ApplicationId: integer): integer;
begin
  if (ApplicationId < 1) or (ApplicationId > Std.Arrays.Length(TuiAppOpen)) then
  begin
    panic('Tui application handle is stale')
  end;

  return ApplicationId
end;

public function TuiAppRequireOpen(ApplicationId: integer): integer;
begin
  TuiAppRequireHandle(ApplicationId);
  if not TuiAppOpen[ApplicationId - 1] then
  begin
    panic('Tui application is closed')
  end;

  return ApplicationId
end;

public function TuiAppPopInput(ApplicationId: integer): TuiHostInput;
begin
  var Input: TuiHostInput := TuiAppInputs[ApplicationId - 1][0];
  TuiAppInputs[ApplicationId - 1] := Std.Arrays.Slice(TuiAppInputs[ApplicationId - 1], 1, Std.Arrays.Length(TuiAppInputs[ApplicationId -
                                                                                                                         1]) -
                                                                                          1);
  return Input
end;

public function TuiAppPopMessage(ApplicationId: integer): TuiMsg;
begin
  var Msg: TuiMsg := TuiAppMessages[ApplicationId - 1][0];
  TuiAppMessages[ApplicationId - 1] := Std.Arrays.Slice(TuiAppMessages[ApplicationId - 1], 1, Std.Arrays.Length(TuiAppMessages[ApplicationId -
                                                                                                                               1]) -
                                                                                              1);
  return Msg
end;

public procedure TuiAppPushMessages(ApplicationId: integer; Messages: array of TuiMsg);
begin
  TuiAppMessages[ApplicationId - 1] := Std.Arrays.Concat(TuiAppMessages[ApplicationId - 1], Messages)
end;

public procedure TuiAppPushInput(ApplicationId: integer; Input: TuiHostInput);
begin
  TuiAppInputs[ApplicationId - 1] := Std.Arrays.Concat(TuiAppInputs[ApplicationId - 1], [Input])
end;

// Queues Started exactly once for a background-enabled host.
public procedure TuiAppStart(ApplicationId: integer);
begin
  TuiAppRequireOpen(ApplicationId);
  if not TuiAppStarted[ApplicationId - 1] then
  begin
    TuiAppStarted[ApplicationId - 1] := true;
    TuiAppPushMessages(ApplicationId, [TuiMsg.Started])
  end
end;

public procedure TuiAppApplyResize(ApplicationId: integer; Size: TuiSize);
begin
  TuiAppSurfaces[ApplicationId - 1].Resize(Size)
end;

public procedure TuiAppRouteInput(ApplicationId: integer; Input: TuiHostInput);
begin
  case Input of
    TuiHostInput.Message(InputMsg):
    begin
      TuiAppPushMessages(ApplicationId, [InputMsg])
    end;
    TuiHostInput.Key(Key):
    begin
      TuiAppPushMessages(ApplicationId, TuiRouteKey(TuiAppTrees[ApplicationId - 1], TuiAppFrames[ApplicationId -
                                                                                                 1], Key))
    end;
    TuiHostInput.Pointer(Pointer):
    begin
      TuiAppPushMessages(ApplicationId, Std.Tui.Runtime.Routing.Pointer.TuiRouteApplicationPointer(Pointer, ApplicationId, TuiAppTrees[ApplicationId -
                                                                                                                                       1], TuiAppFrames[ApplicationId -
                                                                                                                                                        1]))
    end;
    TuiHostInput.Resize(Size):
    begin
      TuiAppPushMessages(ApplicationId, [TuiMsg.Resize(Size)])
    end
  end
end;

public procedure TuiAppApplyResizeIfNeeded(ApplicationId: integer; Msg: TuiMsg);
begin
  case Msg of
    TuiMsg.Resize(Size):
    begin
      TuiAppApplyResize(ApplicationId, Size)
    end
    else
    begin
    end
  end
end;

public function TuiAppApplyCommand(ApplicationId: integer; Output: TuiCmdOutput): boolean;
begin
  case Output.Command() of
    TuiCmd.NoCommand:
    begin
    end;
    TuiCmd.Quit:
    begin
      return true
    end;
    TuiCmd.SetPalette:
    begin
      case Output.ReadPalette() of
        Some(Palette):
        begin
          TuiAppPalettes[ApplicationId - 1] := Palette
        end;
        None:
        begin
          panic('Tui SetPalette command requires a palette')
        end
      end;

      TuiSurfaceInvalidateTerminal(TuiAppSurfaces[ApplicationId - 1])
    end
  end;

  TuiAppPushMessages(ApplicationId, TuiBackgroundApply(ApplicationId, Output.ReadBackground()));
  return false
end;

unit Std.Tui.Runtime.Cmd;

uses Std.Arrays, Std.Options, Std.Tui.Cells.Palette, Std.Tui.Runtime.Application.Background;

public type
  // Runtime command returned by an application's Update function.
  TuiCmd = enum
    // Represents the `NoCommand` variant of `TuiCmd`.
    NoCommand;
    // Represents the `Quit` variant of `TuiCmd`.
    Quit;
    // Represents the `SetPalette` variant of `TuiCmd`.
    SetPalette;
  end;

mutable var
  TuiCommandValues: array of TuiCmd := [];
  TuiCommandPalettes: array of option of TuiPalette := [];
  TuiCommandBackground: array of array of TuiBackgroundCommand := [];

function TuiCmdOutputRequire(Slot: integer): integer;
begin
  if (Slot < 1) or (Slot > Std.Arrays.Length(TuiCommandValues)) then
  begin
    panic('Tui command output handle is invalid')
  end;

  return Slot
end;

public type
  // Host-owned command output capability passed to Update.
  TuiCmdOutput = record
    // Opaque backing-storage slot.
    public Slot: integer;

    // Allocates one reusable command output.
    public static function Create(): TuiCmdOutput;
    begin
      TuiCommandValues := Std.Arrays.Concat(TuiCommandValues, [TuiCmd.NoCommand]);
      TuiCommandPalettes := Std.Arrays.Concat(TuiCommandPalettes, [None]);
      TuiCommandBackground := Std.Arrays.Concat(TuiCommandBackground, [[]]);
      return record
        Slot := Std.Arrays.Length(TuiCommandValues);
      end
    end;

    // Resets the output before one Update call.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public procedure Reset(Self: TuiCmdOutput);
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      TuiCommandValues[Slot - 1] := TuiCmd.NoCommand;
      TuiCommandPalettes[Slot - 1] := None;
      TuiCommandBackground[Slot - 1] := []
    end;

    // Starts one operation after Update returns. The host owns it until completion or shutdown.
    public procedure StartBackground(Self: TuiCmdOutput; Id: integer; Work: TuiBackgroundWork);
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      if Id < 1 then
      begin
        panic('Tui background id must be positive')
      end;
      mutable var Commands: array of TuiBackgroundCommand := TuiCommandBackground[Slot - 1];
      Std.Arrays.Push(Commands, TuiBackgroundCommand.Start(Id, Work));
      TuiCommandBackground[Slot - 1] := Commands
    end;

    // Requests cancellation and starts the latest replacement after the previous operation ends.
    public procedure ReplaceSubscription(Self: TuiCmdOutput; Id: integer; Work: TuiBackgroundWork);
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      if Id < 1 then
      begin
        panic('Tui subscription id must be positive')
      end;
      mutable var Commands: array of TuiBackgroundCommand := TuiCommandBackground[Slot - 1];
      Std.Arrays.Push(Commands, TuiBackgroundCommand.ReplaceSubscription(Id, Work));
      TuiCommandBackground[Slot - 1] := Commands
    end;

    // Requests cancellation after Update returns; the host joins it when complete or at shutdown.
    public procedure CancelSubscription(Self: TuiCmdOutput; Id: integer);
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      if Id < 1 then
      begin
        panic('Tui subscription id must be positive')
      end;
      mutable var Commands: array of TuiBackgroundCommand := TuiCommandBackground[Slot - 1];
      Std.Arrays.Push(Commands, TuiBackgroundCommand.CancelSubscription(Id));
      TuiCommandBackground[Slot - 1] := Commands
    end;

    // Sets the command returned by the current Update call.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Value`: Value used to create or update the result.
    public procedure Set(Self: TuiCmdOutput; Value: TuiCmd);
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      TuiCommandValues[Slot - 1] := Value;
      TuiCommandPalettes[Slot - 1] := None
    end;

    // Requests an immediate palette change after Update returns.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Palette`: Palette used to resolve semantic style roles.
    public procedure SetPalette(Self: TuiCmdOutput; Palette: TuiPalette);
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      TuiCommandValues[Slot - 1] := TuiCmd.SetPalette;
      TuiCommandPalettes[Slot - 1] := Some(Palette)
    end;

    // Reads the command after Update returns.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Command(Self: TuiCmdOutput): TuiCmd;
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      return TuiCommandValues[Slot - 1]
    end;

    // Returns the palette attached to a SetPalette command.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function ReadPalette(Self: TuiCmdOutput): option of TuiPalette;
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      return TuiCommandPalettes[Slot - 1]
    end;

    // Returns background commands emitted by the current Update call.
    public function ReadBackground(Self: TuiCmdOutput): array of TuiBackgroundCommand;
    begin
      var Slot: integer := TuiCmdOutputRequire(Self.Slot);
      return TuiCommandBackground[Slot - 1]
    end;
  end;

unit Std.Tui.Runtime.ConsoleEvents;

uses
  Std.Console, Std.Options, Std.Tui.Geometry.Point, Std.Tui.Geometry.Size, Std.Tui.Runtime.Input,
  Std.Tui.Runtime.PointerEvent;

function TuiPointerButtonFromConsole(Button: Std.Console.MouseButton): TuiPointerButton;
begin
  if Button = Std.Console.MouseButton.Left then
  begin
    return TuiPointerButton.Left
  end;

  if Button = Std.Console.MouseButton.Right then
  begin
    return TuiPointerButton.Right
  end;

  if Button = Std.Console.MouseButton.Middle then
  begin
    return TuiPointerButton.Middle
  end;

  return TuiPointerButton.NoButton
end;

// Converts one Console event to Tui host input, discarding unsupported event kinds.
//
// Parameters:
// - `InputEvent`: Console event to translate.
public function TuiConsoleEventToHostInput(InputEvent: Std.Console.ConsoleEvent): option of TuiHostInput;
begin
  case InputEvent.kind of
    Std.Console.EventKind.Key:
    begin
      return Some(TuiHostInput.Key(InputEvent.key))
    end;
    Std.Console.EventKind.Mouse:
    begin
      return Some(TuiHostInput.Pointer(TuiPointerEvent.WithModifiers(InputEvent.mouse_action, TuiPointerButtonFromConsole(InputEvent.mouse_button), TuiPoint.Create(InputEvent.mouse_x -
                                                                                                                                                                    1, InputEvent.mouse_y -
                                                                                                                                                                       1), InputEvent.shift, InputEvent.ctrl, InputEvent.alt, InputEvent.meta)))
    end;
    Std.Console.EventKind.Resize:
    begin
      if (InputEvent.width <= 0) or (InputEvent.height <= 0) then
      begin
        return None
      end;

      return Some(TuiHostInput.Resize(TuiSize.Create(InputEvent.width, InputEvent.height)))
    end;
    Std.Console.EventKind.Paste, Std.Console.EventKind.FocusGained, Std.Console.EventKind.FocusLost:
    begin
      return None
    end
  end
end;

// Blocks for one Console event and maps it to supported Tui host input.
public function TuiReadConsoleHostInput(): option of TuiHostInput;
begin
  return TuiConsoleEventToHostInput(ReadEvent())
end;

// Waits for one Console event up to the given duration.
//
// Parameters:
// - `TimeoutMillis`: Non-negative relative wait duration.
public function TuiReadConsoleHostInputWithTimeout(TimeoutMillis: integer): option of TuiHostInput;
begin
  case ReadEventTimeout(TimeoutMillis) of
    Some(InputEvent):
    begin
      return TuiConsoleEventToHostInput(InputEvent)
    end;
    None:
    begin
      return None
    end
  end
end;

unit Std.Tui.Runtime.Frame;

uses
  Std.Options, Std.Tui.Elements.Element, Std.Tui.Elements.Validate, Std.Tui.Geometry.Rect,
  Std.Tui.Geometry.Size, Std.Tui.Ids.ControlId, Std.Tui.Layout.Arrange, Std.Tui.Layout.Frame,
  Std.Tui.Rendering.Paint, Std.Tui.Rendering.Surface;

// Validates, arranges, and paints one complete frame into the host-owned arranged frame.
//
// Parameters:
// - `Surface`: Working surface affected by the operation.
// - `Frame`: Arranged frame containing element geometry.
// - `Root`: Root of the element tree.
// - `Pressed`: Whether the control is displayed as pressed.
public procedure TuiRenderFrame(
  Surface: TuiWorkingSurface;
  Frame: TuiArrangedFrame;
  Root: TuiElement;
  Pressed: option of TuiControlId
);
begin
  TuiElementValidate(Root);
  TuiArrange(Frame, Root, TuiRectForSize(Surface.Size()));
  TuiPaintView(Surface, Frame, Root, Pressed)
end;

unit Std.Tui.Runtime.Helpers;

uses
  Std.Arrays, Std.Tui.Elements.Element, Std.Tui.Geometry.Size, Std.Tui.Ids.ControlId,
  Std.Tui.Layout.LayoutFit, Std.Tui.Layout.Measure, Std.Tui.Layout.MeasureResult,
  Std.Tui.Layout.MeasureSpec, Std.Tui.Runtime.Routing.Focus;

// Returns the first focusable control in the active modal or full tree, or `None`.
//
// Parameters:
// - `Root`: Root of the element tree.
public function TuiFocusFirst(Root: TuiElement): option of TuiControlId;
begin
  var Controls: array of TuiControlId := TuiFocusableControls(Root);
  if Std.Arrays.Length(Controls) = 0 then
  begin
    return None
  end;

  return Some(Controls[0])
end;

// Returns `Preferred` when it is focusable in the active tree; otherwise the first focusable id.
//
// Parameters:
// - `Root`: Root of the element tree.
// - `Preferred`: Preferred size or focus identifier.
public function TuiFocusResolve(Root: TuiElement; Preferred: option of TuiControlId): option of TuiControlId;
begin
  var Controls: array of TuiControlId := TuiFocusableControls(Root);
  if Std.Arrays.Length(Controls) = 0 then
  begin
    return None
  end;

  case Preferred of
    Some(Id):
    begin
      if TuiControlIndex(Controls, Id) >= 0 then
      begin
        return Preferred
      end
    end;
    None:
    begin
    end
  end;

  return Some(Controls[0])
end;

// Reports whether the root's unconstrained minimum fits the available terminal size.
//
// Parameters:
// - `Root`: Root of the element tree.
// - `Available`: Available terminal size.
public function TuiLayoutFitFor(Root: TuiElement; Available: TuiSize): TuiLayoutFit;
begin
  var Measured: TuiMeasureResult := TuiMeasure(Root, TuiMeasureSpec.Unbounded());
  return TuiLayoutFit.Create(Measured.Minimum, Available)
end;

unit Std.Tui.Runtime.Input;

uses Std.Console, Std.Tui.Geometry.Size, Std.Tui.Runtime.Msg, Std.Tui.Runtime.PointerEvent;

public type
  // One externally injected headless event, kept in arrival order.
  TuiHostInput = enum
    // Represents the `Message` variant of `TuiHostInput`.
    //
    // Parameters:
    // - `Msg`: Framework message carried by the host input.
    Message(Msg: TuiMsg);
    // Represents the `Key` variant of `TuiHostInput`.
    //
    // Parameters:
    // - `Key`: Console key event carried by the variant.
    Key(Key: Std.Console.KeyEvent);
    // Represents the `Pointer` variant of `TuiHostInput`.
    //
    // Parameters:
    // - `Pointer`: Normalized pointer event carried by the variant.
    Pointer(Pointer: TuiPointerEvent);
    // Represents the `Resize` variant of `TuiHostInput`.
    //
    // Parameters:
    // - `Size`: Size in terminal cells.
    Resize(Size: TuiSize);
  end;

unit Std.Tui.Runtime.Msg;

uses
  Std.Console, Std.Task, Std.Tui.Chrome.MenuNode, Std.Tui.Geometry.Point, Std.Tui.Geometry.Size,
  Std.Tui.Ids.Action, Std.Tui.Ids.ControlId, Std.Tui.Runtime.PointerEvent;

public type
  // Framework messages delivered to an application's Update function.
  TuiMsg = enum
    // Signals startup after the first frame of a background-enabled host.
    Started;
    // Represents the `Key` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Key`: Console key event carried by the variant.
    Key(Key: Std.Console.KeyEvent);
    // Represents the `Pointer` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Pointer`: Normalized pointer event carried by the variant.
    Pointer(Pointer: TuiPointerEvent);
    // Represents the `Tick` variant of `TuiMsg`.
    //
    // Parameters:
    // - `DeltaMilliseconds`: Elapsed time in milliseconds.
    Tick(DeltaMilliseconds: integer);
    // Represents the `Resize` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Size`: Size in terminal cells.
    Resize(Size: TuiSize);
    // Represents the `FocusChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Previous`: Previously focused control identifier.
    // - `Current`: Currently focused control identifier.
    FocusChanged(Previous: option of TuiControlId; Current: option of TuiControlId);
    // Represents the `Action` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    Action(Source: TuiControlId; Action: TuiAction);
    // Represents the `TextChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    // - `Text`: Text carried or displayed by the variant.
    // - `Caret`: Zero-based character index of the caret.
    TextChanged(Source: TuiControlId; Action: TuiAction; Text: string; Caret: integer);
    // Represents the `TextAreaChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    // - `Text`: Text carried or displayed by the variant.
    // - `Caret`: Zero-based character index of the caret.
    // - `Offset`: Scroll offset carried by the variant.
    TextAreaChanged(Source: TuiControlId; Action: TuiAction; Text: string; Caret: integer; Offset: TuiPoint);
    // Represents the `CheckChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    // - `Checked`: Checked state carried by the variant.
    CheckChanged(Source: TuiControlId; Action: TuiAction; Checked: boolean);
    // Represents the `SelectionChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    // - `Selected`: Selected item index.
    SelectionChanged(Source: TuiControlId; Action: TuiAction; Selected: integer);
    // Represents the `ScrollChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    // - `Offset`: Scroll offset carried by the variant.
    ScrollChanged(Source: TuiControlId; Action: TuiAction; Offset: TuiPoint);
    // Represents the `MenuChanged` variant of `TuiMsg`.
    //
    // Parameters:
    // - `Source`: Identifier of the control that produced the value.
    // - `Action`: Application action carried by the variant.
    // - `State`: Controlled menu state carried by the variant.
    MenuChanged(Source: TuiControlId; Action: TuiAction; State: TuiMenuState);
    // Reports a completed host-owned operation that returned or raised a failure.
    BackgroundFailed(Id: integer; Kind: TaskFailureKind; Message: string; Code: integer; Line: integer; Column: integer);
    // Represents the `QuitRequested` variant of `TuiMsg`.
    QuitRequested;
  end;

// Creates a source-aware action message.
//
// Parameters:
// - `Source`: Identifier of the control that produced the message.
// - `Action`: Application action associated with the control or emitted message.
public function TuiMsgAction(Source: TuiControlId; Action: TuiAction): TuiMsg;
begin
  return TuiMsg.Action(Source, Action)
end;

// Creates a source-aware controlled-input change message.
//
// Parameters:
// - `Source`: Identifier of the control that produced the message.
// - `Action`: Application action associated with the control or emitted message.
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
public function TuiMsgTextChanged(Source: TuiControlId; Action: TuiAction; Text: string; Caret: integer): TuiMsg;
begin
  return TuiMsg.TextChanged(Source, Action, Text, Caret)
end;

// Creates a source-aware controlled multiline text-area change message.
//
// Parameters:
// - `Source`: Identifier of the control that produced the message.
// - `Action`: Application action associated with the control or emitted message.
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
// - `Offset`: Scroll offset or position applied by the operation.
public function TuiMsgTextAreaChanged(
  Source: TuiControlId;
  Action: TuiAction;
  Text: string;
  Caret: integer;
  Offset: TuiPoint
): TuiMsg;
begin
  return TuiMsg.TextAreaChanged(Source, Action, Text, Caret, Offset)
end;

// Creates a source-aware controlled check-box change message.
//
// Parameters:
// - `Source`: Identifier of the control that produced the message.
// - `Action`: Application action associated with the control or emitted message.
// - `Checked`: Proposed checked state.
public function TuiMsgCheckChanged(Source: TuiControlId; Action: TuiAction; Checked: boolean): TuiMsg;
begin
  return TuiMsg.CheckChanged(Source, Action, Checked)
end;

// Creates a source-aware controlled list selection-change message.
//
// Parameters:
// - `Source`: Identifier of the control that produced the message.
// - `Action`: Application action associated with the control or emitted message.
// - `Selected`: Selected item index.
public function TuiMsgSelectionChanged(Source: TuiControlId; Action: TuiAction; Selected: integer): TuiMsg;
begin
  return TuiMsg.SelectionChanged(Source, Action, Selected)
end;

