unit Std.Tui.Runtime.Routing.Button;

uses
  Std.Arrays, Std.Console, Std.Str, Std.Tui.Chrome.Button, Std.Tui.Elements.Element,
  Std.Tui.Ids.ControlId, Std.Tui.Runtime.Msg;

function TuiButtonFind(Node: TuiElement; RequireDefault: boolean; Mnemonic: string): option of TuiButtonSpec;
begin
  case Node of
    TuiElement.Button(Button):
    begin
      if Button.Enabled and
         ((RequireDefault and Button.Default) or ((Mnemonic <> '') and (Std.Str.ToLower(Button.Mnemonic) = Std.Str.ToLower(Mnemonic)))) then
      begin
        return Some(Button)
      end;

      return None
    end;
    TuiElement.Desktop(Focused, Children):
    begin
      mutable var ModalIndex: integer := -1;
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case Children[Index] of
          TuiElement.Overlay(Title, OverlayChildren):
          begin
            ModalIndex := Index
          end
          else
          begin
          end
        end
      end;

      if ModalIndex >= 0 then
      begin
        return TuiButtonFind(Children[ModalIndex], RequireDefault, Mnemonic)
      end;

      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end;
    TuiElement.Row(Children, Spacing):
    begin
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end;
    TuiElement.Column(Children, Spacing):
    begin
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end;
    TuiElement.Layout(Settings, Children):
    begin
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end;
    TuiElement.Panel(Title, Children):
    begin
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end;
    TuiElement.Overlay(Title, Children):
    begin
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case TuiButtonFind(Children[Index], RequireDefault, Mnemonic) of
          Some(Button):
          begin
            return Some(Button)
          end;
          None:
          begin
          end
        end
      end;

      return None
    end
    else
    begin
      return None
    end
  end
end;

// Returns the first enabled default button in the active modal or full tree.
//
// Parameters:
// - `Root`: Root of the element tree.
public function TuiFindDefaultButton(Root: TuiElement): option of TuiButtonSpec;
begin
  return TuiButtonFind(Root, true, '')
end;

// Returns the first enabled button matching an Alt mnemonic in the active modal or full tree.
//
// Parameters:
// - `Root`: Root of the element tree.
// - `Mnemonic`: Keyboard mnemonic used to activate the item.
public function TuiFindMnemonicButton(Root: TuiElement; Mnemonic: string): option of TuiButtonSpec;
begin
  if Mnemonic = '' then
  begin
    return None
  end;

  return TuiButtonFind(Root, false, Mnemonic)
end;

// Routes one Alt mnemonic to an enabled button action.
//
// Parameters:
// - `Root`: Root of the element tree.
// - `Key`: Console key event to route or match.
public function TuiRouteButtonMnemonicKey(Root: TuiElement; Key: Std.Console.KeyEvent): option of array of TuiMsg;
begin
  if (Key.kind <> Std.Console.KeyKind.Character) or not Key.alt then
  begin
    return None
  end;

  case TuiFindMnemonicButton(Root, Key.ch) of
    Some(Button):
    begin
      return Some([TuiMsg.Action(Button.Id, Button.Action)])
    end;
    None:
    begin
      return None
    end
  end
end;

// Routes Enter or Space when an enabled button owns keyboard focus.
//
// Parameters:
// - `Button`: Button specification used by the operation.
// - `Target`: Target control identifier.
// - `Key`: Console key event to route or match.
public function TuiRouteFocusedButtonKey(
  Button: TuiButtonSpec;
  Target: TuiControlId;
  Key: Std.Console.KeyEvent
): option of TuiMsg;
begin
  if Button.Id.Value <> Target.Value then
  begin
    return None
  end;

  if Button.Enabled and
     ((Key.kind = Std.Console.KeyKind.Enter) or (Key.kind = Std.Console.KeyKind.Space)) then
  begin
    return Some(TuiMsg.Action(Button.Id, Button.Action))
  end;

  return None
end;

// Returns the enabled default button action for Enter.
//
// Parameters:
// - `Root`: Root of the element tree.
public function TuiRouteDefaultButtonEnter(Root: TuiElement): option of TuiMsg;
begin
  case TuiFindDefaultButton(Root) of
    Some(Button):
    begin
      return Some(TuiMsg.Action(Button.Id, Button.Action))
    end;
    None:
    begin
      return None
    end
  end
end;

unit Std.Tui.Runtime.Routing.ButtonCapture;

uses Std.Arrays, Std.Tui.Chrome.Button, Std.Tui.Ids.ControlId;

public type
  // Host-owned pointer capture for one button press.
  TuiButtonPressState = enum
    // Represents the `Idle` variant of `TuiButtonPressState`.
    Idle;
    // Represents the `Captured` variant of `TuiButtonPressState`.
    //
    // Parameters:
    // - `Button`: Button specification carried by the variant.
    // - `Inside`: Whether the pointer remains inside the captured control.
    Captured(Button: TuiButtonSpec; Inside: boolean);
  end;

mutable var
  TuiButtonPressStates: array of TuiButtonPressState := [];

// Allocates idle button-capture state for one application.
public procedure TuiButtonCaptureOpen();
begin
  TuiButtonPressStates := Std.Arrays.Concat(TuiButtonPressStates, [TuiButtonPressState.Idle])
end;

// Clears button-capture state for one application.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
public procedure TuiButtonCaptureClose(ApplicationId: integer);
begin
  TuiButtonPressStates[ApplicationId - 1] := TuiButtonPressState.Idle
end;

// Returns the current button-capture state for one application.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
public function TuiButtonCaptureGet(ApplicationId: integer): TuiButtonPressState;
begin
  return TuiButtonPressStates[ApplicationId - 1]
end;

// Releases button capture for one application.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
public procedure TuiButtonCaptureRelease(ApplicationId: integer);
begin
  TuiButtonPressStates[ApplicationId - 1] := TuiButtonPressState.Idle
end;

// Captures one button and records whether the pointer remains inside it.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
// - `Button`: Button specification used by the operation.
// - `Inside`: Whether the pointer remains inside the captured control.
public procedure TuiButtonCaptureSet(ApplicationId: integer; Button: TuiButtonSpec; Inside: boolean);
begin
  TuiButtonPressStates[ApplicationId - 1] := TuiButtonPressState.Captured(Button, Inside)
end;

// Returns the button painted pressed while capture remains inside it.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
public function TuiButtonCapturePressed(ApplicationId: integer): option of TuiControlId;
begin
  case TuiButtonPressStates[ApplicationId - 1] of
    TuiButtonPressState.Captured(Button, Inside) if Inside:
    begin
      return Some(Button.Id)
    end;
    TuiButtonPressState.Idle:
    begin
      return None
    end;
    TuiButtonPressState.Captured(Button, Inside):
    begin
      return None
    end
  end
end;

unit Std.Tui.Runtime.Routing.Focus;

uses
  Std.Arrays, Std.Tui.Chrome.StatusItem, Std.Tui.Elements.Element, Std.Tui.Ids.ControlId,
  Std.Tui.Layout.Frame;

function TuiRouteFrameMatchesNode(
  Frame: TuiArrangedFrame;
  Node: TuiElement;
  Index: integer;
  ParentIndex: integer
): integer;
begin
  if Frame.EntryAt(Index).ParentIndex <> ParentIndex then
  begin
    panic('Tui routing received a frame for a different element tree')
  end;
  mutable var Next: integer := Index + 1;
  mutable var Descendants: array of TuiElement := [];
  case Node of
    TuiElement.Scroll(Id, Offset, ChangeAction, ScrollChildren):
    begin
      Descendants := ScrollChildren
    end;
    TuiElement.Row(RowChildren, Spacing):
    begin
      Descendants := RowChildren
    end;
    TuiElement.Column(ColumnChildren, Spacing):
    begin
      Descendants := ColumnChildren
    end;
    TuiElement.Layout(Settings, LayoutChildren):
    begin
      Descendants := LayoutChildren
    end;
    TuiElement.Panel(Title, PanelChildren):
    begin
      Descendants := PanelChildren
    end;
    TuiElement.Overlay(Title, OverlayChildren):
    begin
      Descendants := OverlayChildren
    end;
    TuiElement.Desktop(Focused, DesktopChildren):
    begin
      Descendants := DesktopChildren
    end
    else
    begin
    end
  end;

  for ChildIndex: integer := 0 to Std.Arrays.Length(Descendants) - 1 do
  begin
    Next := TuiRouteFrameMatchesNode(Frame, Descendants[ChildIndex], Next, Index)
  end;

  return Next
end;

// Panics when the arranged frame does not match the previous painted tree.
//
// Parameters:
// - `Frame`: Arranged frame containing element geometry.
// - `Root`: Root of the element tree.
public procedure TuiRouteRequireMatchingFrame(Frame: TuiArrangedFrame; Root: TuiElement);
begin
  if Frame.Count() = 0 then
  begin
    panic('Tui routing requires a successfully painted frame')
  end;

  if TuiRouteFrameMatchesNode(Frame, Root, 0, -1) <> Frame.Count() then
  begin
    panic('Tui routing received a frame for a different element tree')
  end
end;

// Returns focusable control ids in the active modal or full tree order.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiFocusableControls(Node: TuiElement): array of TuiControlId;
begin
  mutable var Descendants: array of TuiElement := [];
  case Node of
    TuiElement.Button(Button):
    begin
      if Button.Enabled then
      begin
        return [Button.Id]
      end
      else
      begin
        return []
      end
    end;
    TuiElement.Input(Input):
    begin
      return [Input.Id]
    end;
    TuiElement.TextArea(Id, Text, Caret, Offset, ChangeAction):
    begin
      return [Id]
    end;
    TuiElement.CheckBox(Id, Text, Checked, ChangeAction):
    begin
      return [Id]
    end;
    TuiElement.List(Id, Items, Selected, ChangeAction):
    begin
      return [Id]
    end;
    TuiElement.Menu(Id, Nodes, State, ChangeAction):
    begin
      return [Id]
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      mutable var Controls: array of TuiControlId := [Id];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiFocusableControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.MenuBar(Items):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Items) - 1 do
      begin
        if Items[Index].Enabled then
        begin
          Controls := Std.Arrays.Concat(Controls, [Items[Index].Id])
        end
      end;

      return Controls
    end;
    TuiElement.StatusLine(Items):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Items) - 1 do
      begin
        case Items[Index] of
          TuiStatusItem.Command(Id, Text, Action, Enabled):
          begin
            if Enabled then
            begin
              Controls := Std.Arrays.Concat(Controls, [Id])
            end
          end
          else
          begin
          end
        end
      end;

      return Controls
    end;
    TuiElement.Row(RowChildren, Spacing):
    begin
      Descendants := RowChildren
    end;
    TuiElement.Column(ColumnChildren, Spacing):
    begin
      Descendants := ColumnChildren
    end;
    TuiElement.Layout(Settings, LayoutChildren):
    begin
      Descendants := LayoutChildren
    end;
    TuiElement.Panel(Title, PanelChildren):
    begin
      Descendants := PanelChildren
    end;
    TuiElement.Overlay(Title, OverlayChildren):
    begin
      Descendants := OverlayChildren
    end;
    TuiElement.Desktop(Focused, Children):
    begin
      mutable var LastOverlay: integer := -1;
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case Children[Index] of
          TuiElement.Overlay(Title, OverlayChildren):
          begin
            LastOverlay := Index
          end
          else
          begin
          end
        end
      end;

      if LastOverlay >= 0 then
      begin
        return TuiFocusableControls(Children[LastOverlay])
      end
      else
      begin
        mutable var Controls: array of TuiControlId := [];
        for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
        begin
          Controls := Std.Arrays.Concat(Controls, TuiFocusableControls(Children[Index]))
        end;

        return Controls
      end
    end
    else
    begin
      return []
    end
  end;
  mutable var Controls: array of TuiControlId := [];
  for Index: integer := 0 to Std.Arrays.Length(Descendants) - 1 do
  begin
    Controls := Std.Arrays.Concat(Controls, TuiFocusableControls(Descendants[Index]))
  end;

  return Controls
end;

// Reads the desktop focus id, or `None` when the root is not a desktop.
//
// Parameters:
// - `Root`: Root of the element tree.
public function TuiRootFocus(Root: TuiElement): option of TuiControlId;
begin
  case Root of
    TuiElement.Desktop(Focused, Children):
    begin
      return Focused
    end
    else
    begin
      return None
    end
  end
end;

// Returns the focusable-list index of a control id, or `-1` when absent.
//
// Parameters:
// - `Controls`: Ordered control identifiers to search.
// - `Id`: Identifier assigned to the created or selected value.
public function TuiControlIndex(Controls: array of TuiControlId; Id: TuiControlId): integer;
begin
  for Index: integer := 0 to Std.Arrays.Length(Controls) - 1 do
  begin
    if Controls[Index].Value = Id.Value then
    begin
      return Index
    end
  end;

  return -1
end;

// Returns whether two control ids refer to the same identity.
//
// Parameters:
// - `Left`: Left input value or edge.
// - `Right`: Right input value or edge.
public function TuiSameControlId(Left: TuiControlId; Right: TuiControlId): boolean;
begin
  return Left.Value = Right.Value
end;

// Returns whether the option id matches the target control.
//
// Parameters:
// - `Focused`: Whether the control currently owns focus.
// - `Target`: Target control identifier.
public function TuiFocusMatches(Focused: option of TuiControlId; Target: TuiControlId): boolean;
begin
  case Focused of
    Some(Id):
    begin
      return TuiSameControlId(Id, Target)
    end;
    None:
    begin
      return false
    end
  end
end;

unit Std.Tui.Runtime.Routing.FocusNavigation;

uses
  Std.Arrays, Std.Console, Std.Tui.Chrome.StatusItem, Std.Tui.Elements.Element,
  Std.Tui.Ids.ControlId, Std.Tui.Runtime.Msg, Std.Tui.Runtime.Routing.Focus;

function TuiButtonFocusControls(Node: TuiElement): array of TuiControlId;
begin
  case Node of
    TuiElement.Button(Button):
    begin
      if Button.Enabled then
      begin
        return [Button.Id]
      end;

      return []
    end;
    TuiElement.Desktop(Focused, Children):
    begin
      mutable var LastOverlay: integer := -1;
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        case Children[Index] of
          TuiElement.Overlay(Title, OverlayChildren):
          begin
            LastOverlay := Index
          end
          else
          begin
          end
        end
      end;

      if LastOverlay >= 0 then
      begin
        return TuiButtonFocusControls(Children[LastOverlay])
      end;
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.Row(Children, Spacing):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.Column(Children, Spacing):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.Layout(Settings, Children):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.Panel(Title, Children):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end;
    TuiElement.Overlay(Title, Children):
    begin
      mutable var Controls: array of TuiControlId := [];
      for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Controls := Std.Arrays.Concat(Controls, TuiButtonFocusControls(Children[Index]))
      end;

      return Controls
    end
    else
    begin
      return []
    end
  end
end;

// Routes an unmodified arrow key between enabled buttons in the active modal or full tree.
//
// Parameters:
// - `Root`: Root of the element tree.
// - `Previous`: Previously focused control identifier.
// - `Key`: Console key event to route or match.
public function TuiRouteButtonFocusNavigation(
  Root: TuiElement;
  Previous: option of TuiControlId;
  Key: Std.Console.KeyEvent
): option of array of TuiMsg;
begin
  if ((Key.shift or Key.ctrl) or Key.alt) or Key.meta then
  begin
    return None
  end;
  mutable var Direction: integer := 0;
  if (Key.kind = Std.Console.KeyKind.Up) or (Key.kind = Std.Console.KeyKind.Left) then
  begin
    Direction := -1
  end
  else if (Key.kind = Std.Console.KeyKind.Down) or (Key.kind = Std.Console.KeyKind.Right) then
  begin
    Direction := 1
  end
  else
  begin
    return None
  end;
  var Controls: array of TuiControlId := TuiButtonFocusControls(Root);
  if Std.Arrays.Length(Controls) = 0 then
  begin
    return None
  end;
  mutable var CurrentIndex: integer := -1;
  case Previous of
    Some(Id):
    begin
      CurrentIndex := TuiControlIndex(Controls, Id)
    end;
    None:
    begin
      return None
    end
  end;

  if CurrentIndex < 0 then
  begin
    return None
  end;
  mutable var NextIndex: integer := CurrentIndex + Direction;
  if NextIndex < 0 then
  begin
    NextIndex := Std.Arrays.Length(Controls) - 1
  end
  else if NextIndex >= Std.Arrays.Length(Controls) then
  begin
    NextIndex := 0
  end;

  if NextIndex = CurrentIndex then
  begin
    return Some([])
  end;

  return Some([TuiMsg.FocusChanged(Previous, Some(Controls[NextIndex]))])
end;

unit Std.Tui.Runtime.Routing.Pointer;

uses
  Std.Arrays, Std.Console, Std.Tui.Chrome.Button, Std.Tui.Elements.Element, Std.Tui.Geometry.Point,
  Std.Tui.Ids.ControlId, Std.Tui.Layout.Frame, Std.Tui.Runtime.Msg, Std.Tui.Runtime.PointerEvent,
  Std.Tui.Runtime.Routing.ButtonCapture, Std.Tui.Runtime.Routing.Focus,
  Std.Tui.Runtime.Routing.MenuPointer, Std.Tui.Runtime.Routing.PointerHit,
  Std.Tui.Runtime.Routing.TextArea, Std.Tui.Text.Input;

function TuiRoutePointerFocusMessages(Previous: option of TuiControlId; Target: TuiControlId): array of TuiMsg;
begin
  if TuiFocusMatches(Previous, Target) then
  begin
    return []
  end;

  return [TuiMsg.FocusChanged(Previous, Some(Target))]
end;

function TuiIdlePointerResult(ApplicationId: integer; Messages: array of TuiMsg): array of TuiMsg;
begin
  TuiButtonCaptureRelease(ApplicationId);
  return Messages
end;

function TuiCapturedPointerResult(
  ApplicationId: integer;
  Messages: array of TuiMsg;
  Button: TuiButtonSpec;
  Inside: boolean
): array of TuiMsg;
begin
  TuiButtonCaptureSet(ApplicationId, Button, Inside);
  return Messages
end;

function TuiPointerInsideCapturedButton(
  Root: TuiElement;
  Frame: TuiArrangedFrame;
  Position: TuiPoint;
  Button: TuiButtonSpec
): boolean;
begin
  case TuiPointerHitAt(Frame, Root, Position) of
    TuiPointerHit.ElementButton(Hit):
    begin
      return Hit.Id.Value = Button.Id.Value
    end
    else
    begin
      return false
    end
  end
end;

// Allocates idle pointer-button state for one application.
public procedure TuiPointerRoutingOpen();
begin
  TuiButtonCaptureOpen()
end;

// Clears pointer-button state for one application.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
public procedure TuiPointerRoutingClose(ApplicationId: integer);
begin
  TuiButtonCaptureClose(ApplicationId)
end;

// Returns the button painted pressed for one application.
//
// Parameters:
// - `ApplicationId`: Identifier of the application-owned routing state.
public function TuiPointerRoutingPressed(ApplicationId: integer): option of TuiControlId;
begin
  return TuiButtonCapturePressed(ApplicationId)
end;

// Routes one pointer event and advances application-owned button capture.
//
// Parameters:
// - `Pointer`: Normalized pointer event to route.
// - `ApplicationId`: Identifier of the application-owned routing state.
// - `Root`: Root of the element tree.
// - `Frame`: Arranged frame containing element geometry.
public function TuiRouteApplicationPointer(
  Pointer: TuiPointerEvent;
  ApplicationId: integer;
  Root: TuiElement;
  Frame: TuiArrangedFrame
): array of TuiMsg;
begin
  var PointerAction: Std.Console.MouseAction := Pointer.Action;
  var PointerButton: TuiPointerButton := Pointer.Button;
  var PointerPosition: TuiPoint := Pointer.Position;
  var PointerShift: boolean := Pointer.Shift;
  var PointerCtrl: boolean := Pointer.Ctrl;
  var PointerAlt: boolean := Pointer.Alt;
  var PointerMeta: boolean := Pointer.Meta;
  TuiRouteRequireMatchingFrame(Frame, Root);
  case TuiButtonCaptureGet(ApplicationId) of
    TuiButtonPressState.Captured(Button, PreviousInside):
    begin
      var Inside: boolean := TuiPointerInsideCapturedButton(Root, Frame, PointerPosition, Button);
      if PointerAction = Std.Console.MouseAction.Up then
      begin
        if Inside then
        begin
          return TuiIdlePointerResult(ApplicationId, [TuiMsg.Action(Button.Id, Button.Action)])
        end;

        return TuiIdlePointerResult(ApplicationId, [
                                                     TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                                   ])
      end;

      return TuiCapturedPointerResult(ApplicationId, [
                                                       TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                                     ], Button, Inside)
    end;
    TuiButtonPressState.Idle:
    begin
    end
  end;
  var MenuPointer: boolean := (PointerAction = Std.Console.MouseAction.Move) or
                              ((PointerAction = Std.Console.MouseAction.Down) and (PointerButton = TuiPointerButton.Left));
  if MenuPointer then
  begin
    case TuiRouteMenuPointer(Root, Frame, PointerPosition, PointerAction =
                                                           Std.Console.MouseAction.Down) of
      Some(Messages):
      begin
        return TuiIdlePointerResult(ApplicationId, Messages)
      end;
      None:
      begin
      end
    end
  end;

  if (PointerAction <> Std.Console.MouseAction.Down) or (PointerButton <> TuiPointerButton.Left) then
  begin
    return TuiIdlePointerResult(ApplicationId, [
                                                 TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                               ])
  end;
  var Previous: option of TuiControlId := TuiRootFocus(Root);
  case TuiPointerHitAt(Frame, Root, PointerPosition) of
    TuiPointerHit.Miss:
    begin
      return TuiIdlePointerResult(ApplicationId, [
                                                   TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                                 ])
    end;
    TuiPointerHit.ElementButton(Button):
    begin
      var Messages: array of TuiMsg := Std.Arrays.Concat(TuiRoutePointerFocusMessages(Previous, Button.Id), [
                                                                                                              TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                                                                                            ]);
      return TuiCapturedPointerResult(ApplicationId, Messages, Button, true)
    end;
    TuiPointerHit.ImmediateButton(Id, Action):
    begin
      return TuiIdlePointerResult(ApplicationId, Std.Arrays.Concat(TuiRoutePointerFocusMessages(Previous, Id), [
                                                                                                                 TuiMsg.Action(Id, Action)
                                                                                                               ]))
    end;
    TuiPointerHit.Input(Input, Bounds):
    begin
      var Viewport: TuiInputViewport := TuiInputViewportFor(Input.Text, Input.Caret, Bounds.Width -
                                                                                     2);
      var Caret: integer := TuiInputCaretAtColumn(Input.Text, Viewport, (PointerPosition.X - Bounds.X) -
                                                                        1);
      return TuiIdlePointerResult(ApplicationId, Std.Arrays.Concat(TuiRoutePointerFocusMessages(Previous, Input.Id), [
                                                                                                                       TuiMsg.TextChanged(Input.Id, Input.ChangeAction, Input.Text, Caret)
                                                                                                                     ]))
    end;
    TuiPointerHit.TextArea(Id, Action, Text, Offset, Bounds):
    begin
      return TuiIdlePointerResult(ApplicationId, Std.Arrays.Concat(TuiRoutePointerFocusMessages(Previous, Id), [
                                                                                                                 TuiRouteTextAreaPointer(Id, Text, Offset, Action, Bounds, PointerPosition)
                                                                                                               ]))
    end;
    TuiPointerHit.CheckBox(Id, Action, Checked):
    begin
      return TuiIdlePointerResult(ApplicationId, Std.Arrays.Concat(TuiRoutePointerFocusMessages(Previous, Id), [
                                                                                                                 TuiMsg.CheckChanged(Id, Action, not Checked)
                                                                                                               ]))
    end;
    TuiPointerHit.List(Id, Action, CurrentSelected, Proposed):
    begin
      var FocusMessages: array of TuiMsg := TuiRoutePointerFocusMessages(Previous, Id);
      if Proposed = CurrentSelected then
      begin
        if Std.Arrays.Length(FocusMessages) = 0 then
        begin
          return TuiIdlePointerResult(ApplicationId, [
                                                       TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                                     ])
        end;

        return TuiIdlePointerResult(ApplicationId, FocusMessages)
      end;

      return TuiIdlePointerResult(ApplicationId, Std.Arrays.Concat(FocusMessages, [
                                                                                    TuiMsg.SelectionChanged(Id, Action, Proposed)
                                                                                  ]))
    end;
    TuiPointerHit.Scroll(Id):
    begin
      var FocusMessages: array of TuiMsg := TuiRoutePointerFocusMessages(Previous, Id);
      if Std.Arrays.Length(FocusMessages) = 0 then
      begin
        return TuiIdlePointerResult(ApplicationId, [
                                                     TuiMsg.Pointer(TuiPointerEvent.WithModifiers(PointerAction, PointerButton, PointerPosition, PointerShift, PointerCtrl, PointerAlt, PointerMeta))
                                                   ])
      end;

      return TuiIdlePointerResult(ApplicationId, FocusMessages)
    end
  end
end;

unit Std.Tui.Runtime.Routing.PointerHit;

uses
  Std.Arrays, Std.Console, Std.Tui.Chrome.Button, Std.Tui.Chrome.Input, Std.Tui.Chrome.StatusItem,
  Std.Tui.Elements.Element, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Ids.Action,
  Std.Tui.Ids.ControlId, Std.Tui.Layout.Frame;

public type
  // Hit result for pointer routing against arranged geometry.
  TuiPointerHit = enum
    // Represents the `Miss` variant of `TuiPointerHit`.
    Miss;
    // Represents the `ElementButton` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Button`: Button specification carried by the variant.
    ElementButton(Button: TuiButtonSpec);
    // Represents the `ImmediateButton` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Id`: Identifier carried by the variant.
    // - `Action`: Application action carried by the variant.
    ImmediateButton(Id: TuiControlId; Action: TuiAction);
    // Represents the `Input` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Value`: Typed value wrapped by the variant.
    // - `Bounds`: Arranged bounds associated with the hit or control.
    Input(Value: TuiInputSpec; Bounds: TuiRect);
    // Represents the `TextArea` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Id`: Identifier carried by the variant.
    // - `Action`: Application action carried by the variant.
    // - `Text`: Text carried or displayed by the variant.
    // - `Offset`: Scroll offset carried by the variant.
    // - `Bounds`: Arranged bounds associated with the hit or control.
    TextArea(Id: TuiControlId; Action: TuiAction; Text: string; Offset: TuiPoint; Bounds: TuiRect);
    // Represents the `CheckBox` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Id`: Identifier carried by the variant.
    // - `Action`: Application action carried by the variant.
    // - `Checked`: Checked state carried by the variant.
    CheckBox(Id: TuiControlId; Action: TuiAction; Checked: boolean);
    // Represents the `List` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Id`: Identifier carried by the variant.
    // - `Action`: Application action carried by the variant.
    // - `CurrentSelected`: Current selected item index.
    // - `Proposed`: Proposed selected item index.
    List(Id: TuiControlId; Action: TuiAction; CurrentSelected: integer; Proposed: integer);
    // Represents the `Scroll` variant of `TuiPointerHit`.
    //
    // Parameters:
    // - `Id`: Identifier carried by the variant.
    Scroll(Id: TuiControlId);
  end;

mutable var
  TuiPointerBestHit: TuiPointerHit := TuiPointerHit.Miss;

function TuiPointerModalChildIndex(Children: array of TuiElement): integer;
begin
  mutable var LastOverlay: integer := -1;
  for Index: integer := 0 to Std.Arrays.Length(Children) - 1 do
  begin
    case Children[Index] of
      TuiElement.Overlay(Title, OverlayChildren):
      begin
        LastOverlay := Index
      end
      else
      begin
      end
    end
  end;

  return LastOverlay
end;

function TuiPointerHitWalk(
  Frame: TuiArrangedFrame;
  Node: TuiElement;
  Index: integer;
  Point: TuiPoint;
  AllowHits: boolean
): integer;
begin
  var Entry: TuiArrangedEntry := Frame.EntryAt(Index);
  mutable var Next: integer := Index + 1;
  case Node of
    TuiElement.Button(Button):
    begin
      mutable var ActiveWidth: integer := Entry.Bounds.Width - 1;
      if ActiveWidth < 0 then
      begin
        ActiveWidth := 0
      end;
      var ActiveBounds: TuiRect := TuiRect.Create(Entry.Bounds.X, Entry.Bounds.Y, ActiveWidth, 1);
      if (Button.Enabled and AllowHits) and Entry.Clip.Intersect(ActiveBounds).Contains(Point) then
      begin
        TuiPointerBestHit := TuiPointerHit.ElementButton(Button)
      end
    end;
    TuiElement.Input(Input):
    begin
      if AllowHits and Entry.Clip.Contains(Point) then
      begin
        TuiPointerBestHit := TuiPointerHit.Input(Input, Entry.Bounds)
      end
    end;
    TuiElement.TextArea(Id, Text, Caret, Offset, ChangeAction):
    begin
      if AllowHits and Entry.Clip.Contains(Point) then
      begin
        TuiPointerBestHit := TuiPointerHit.TextArea(Id, ChangeAction, Text, Offset, Entry.Bounds)
      end
    end;
    TuiElement.CheckBox(Id, Text, Checked, ChangeAction):
    begin
      if AllowHits and Entry.Clip.Contains(Point) then
      begin
        TuiPointerBestHit := TuiPointerHit.CheckBox(Id, ChangeAction, Checked)
      end
    end;
    TuiElement.List(Id, Items, Selected, ChangeAction):
    begin
      if AllowHits and Entry.Clip.Contains(Point) then
      begin
        var Row: integer := Point.Y - Entry.Bounds.Y;
        if (Row >= 0) and (Row < Std.Arrays.Length(Items)) then
        begin
          TuiPointerBestHit := TuiPointerHit.List(Id, ChangeAction, Selected, Row)
        end
      end
    end;
    TuiElement.MenuBar(Items):
    begin
      mutable var Cursor: integer := Entry.Bounds.X;
      for ItemIndex: integer := 0 to Std.Arrays.Length(Items) - 1 do
      begin
        var Width: integer := Std.Console.DisplayWidth(Items[ItemIndex].Text) + 2;
        var ItemBounds: TuiRect := TuiRect.Create(Cursor, Entry.Bounds.Y, Width, 1);
        if (AllowHits and Items[ItemIndex].Enabled) and
           Entry.Clip.Intersect(ItemBounds).Contains(Point) then
        begin
          TuiPointerBestHit := TuiPointerHit.ImmediateButton(Items[ItemIndex].Id, Items[ItemIndex].Action)
        end;

        Cursor := Cursor + Width
      end
    end;
    TuiElement.Menu(Id, Nodes, State, ChangeAction):
    begin
    end;
    TuiElement.StatusLine(Items):
    begin
      mutable var Cursor: integer := Entry.Bounds.X;
      for ItemIndex: integer := 0 to Std.Arrays.Length(Items) - 1 do
      begin
        if ItemIndex > 0 then
        begin
          Cursor := Cursor + 1
        end;

        case Items[ItemIndex] of
          TuiStatusItem.Hint(Text):
          begin
            Cursor := Cursor + Std.Console.DisplayWidth(Text)
          end;
          TuiStatusItem.KeyHint(KeyText, Text):
          begin
            Cursor := ((Cursor + Std.Console.DisplayWidth(KeyText)) + Std.Console.DisplayWidth(Text)) +
                      1
          end;
          TuiStatusItem.Command(Id, Text, Action, Enabled):
          begin
            var Width: integer := Std.Console.DisplayWidth(Text);
            var ItemBounds: TuiRect := TuiRect.Create(Cursor, Entry.Bounds.Y, Width, 1);
            if (AllowHits and Enabled) and Entry.Clip.Intersect(ItemBounds).Contains(Point) then
            begin
              TuiPointerBestHit := TuiPointerHit.ImmediateButton(Id, Action)
            end;

            Cursor := Cursor + Width
          end
        end
      end
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      var ScrollAllowsHits: boolean := AllowHits and Entry.Clip.Contains(Point);
      if ScrollAllowsHits then
      begin
        TuiPointerBestHit := TuiPointerHit.Scroll(Id)
      end;

      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, ScrollAllowsHits)
      end
    end;
    TuiElement.Row(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, AllowHits)
      end
    end;
    TuiElement.Column(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, AllowHits)
      end
    end;
    TuiElement.Layout(Settings, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, AllowHits)
      end
    end;
    TuiElement.Panel(Title, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, AllowHits)
      end
    end;
    TuiElement.Overlay(Title, Children):
    begin
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, AllowHits)
      end
    end;
    TuiElement.Desktop(Focused, Children):
    begin
      var ModalIndex: integer := TuiPointerModalChildIndex(Children);
      for ChildIndex: integer := 0 to Std.Arrays.Length(Children) - 1 do
      begin
        mutable var ChildAllow: boolean := AllowHits;
        if ModalIndex >= 0 then
        begin
          ChildAllow := AllowHits and (ChildIndex = ModalIndex)
        end;

        Next := TuiPointerHitWalk(Frame, Children[ChildIndex], Next, Point, ChildAllow)
      end
    end
    else
    begin
    end
  end;

  return Next
end;

// Returns the deepest eligible hit at a point.
//
// Parameters:
// - `Frame`: Arranged frame containing element geometry.
// - `Root`: Root of the element tree.
// - `Point`: Point tested by the operation.
public function TuiPointerHitAt(Frame: TuiArrangedFrame; Root: TuiElement; Point: TuiPoint): TuiPointerHit;
begin
  TuiPointerBestHit := TuiPointerHit.Miss;
  if TuiPointerHitWalk(Frame, Root, 0, Point, true) <> Frame.Count() then
  begin
    panic('Tui pointer routing did not consume the complete arranged frame')
  end;

  return TuiPointerBestHit
end;

unit Std.Tui.Runtime.Routing.TextArea;

uses
  Std.Console, Std.Str, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Geometry.Size,
  Std.Tui.Ids.Action, Std.Tui.Ids.ControlId, Std.Tui.Runtime.Msg, Std.Tui.Text.TextArea;

function TuiTextAreaClampLine(Text: string; Line: integer): integer;
begin
  if Line < 0 then
  begin
    return 0
  end;
  var Last: integer := TuiTextAreaLineCount(Text) - 1;
  if Line > Last then
  begin
    return Last
  end;

  return Line
end;

// Routes one key into a complete controlled text-area state proposal.
//
// Parameters:
// - `Id`: Identifier assigned to the created or selected value.
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
// - `Offset`: Scroll offset or position applied by the operation.
// - `ChangeAction`: Application action emitted when the value changes.
// - `Viewport`: Visible input or text-area viewport.
// - `Key`: Console key event to route or match.
public function TuiRouteTextAreaKey(
  Id: TuiControlId;
  Text: string;
  Caret: integer;
  Offset: TuiPoint;
  ChangeAction: TuiAction;
  Viewport: TuiRect;
  Key: Std.Console.KeyEvent
): option of TuiMsg;
begin
  mutable var NextText: string := Text;
  mutable var NextCaret: integer := Caret;
  mutable var Handled: boolean := true;
  var Position: TuiTextAreaPosition := TuiTextAreaLocate(Text, Caret);
  if (((Key.kind = Std.Console.KeyKind.Character) and not Key.ctrl) and not Key.alt) and
     not Key.meta then
  begin
    NextText := Std.Str.Insert(Text, Caret, Key.ch);
    NextCaret := Caret + Std.Str.Length(Key.ch)
  end
  else if Key.kind = Std.Console.KeyKind.Space then
  begin
    NextText := Std.Str.Insert(Text, Caret, ' ');
    NextCaret := Caret + 1
  end
  else if Key.kind = Std.Console.KeyKind.Enter then
  begin
    NextText := Std.Str.Insert(Text, Caret, Std.Str.Chr(10));
    NextCaret := Caret + 1
  end
  else if Key.kind = Std.Console.KeyKind.Tab then
  begin
    NextText := Std.Str.Insert(Text, Caret, '  ');
    NextCaret := Caret + 2
  end
  else if (Key.kind = Std.Console.KeyKind.Backspace) and (Caret > 0) then
  begin
    NextText := Std.Str.Delete(Text, Caret - 1, 1);
    NextCaret := Caret - 1
  end
  else if (Key.kind = Std.Console.KeyKind.Delete) and (Caret < Std.Str.Length(Text)) then
  begin
    NextText := Std.Str.Delete(Text, Caret, 1)
  end
  else if (Key.kind = Std.Console.KeyKind.Left) and (Caret > 0) then
  begin
    NextCaret := Caret - 1
  end
  else if (Key.kind = Std.Console.KeyKind.Right) and (Caret < Std.Str.Length(Text)) then
  begin
    NextCaret := Caret + 1
  end
  else if Key.kind = Std.Console.KeyKind.Up then
  begin
    var TargetLine: integer := TuiTextAreaClampLine(Text, Position.Line - 1);
    NextCaret := TuiTextAreaCaretAtDisplayColumn(Text, TargetLine, Position.DisplayColumn)
  end
  else if Key.kind = Std.Console.KeyKind.Down then
  begin
    var TargetLine: integer := TuiTextAreaClampLine(Text, Position.Line + 1);
    NextCaret := TuiTextAreaCaretAtDisplayColumn(Text, TargetLine, Position.DisplayColumn)
  end
  else if Key.kind = Std.Console.KeyKind.Home then
  begin
    NextCaret := Position.LineStart
  end
  else if Key.kind = Std.Console.KeyKind.EndKey then
  begin
    NextCaret := Position.LineEnd
  end
  else if Key.kind = Std.Console.KeyKind.PageUp then
  begin
    mutable var Page: integer := Viewport.Height;
    if Page < 1 then
    begin
      Page := 1
    end;
    var TargetLine: integer := TuiTextAreaClampLine(Text, Position.Line - Page);
    NextCaret := TuiTextAreaCaretAtDisplayColumn(Text, TargetLine, Position.DisplayColumn)
  end
  else if Key.kind = Std.Console.KeyKind.PageDown then
  begin
    mutable var Page: integer := Viewport.Height;
    if Page < 1 then
    begin
      Page := 1
    end;
    var TargetLine: integer := TuiTextAreaClampLine(Text, Position.Line + Page);
    NextCaret := TuiTextAreaCaretAtDisplayColumn(Text, TargetLine, Position.DisplayColumn)
  end
  else
  begin
    Handled := false
  end;

  if not Handled then
  begin
    return None
  end;
  var NextOffset: TuiPoint := TuiTextAreaEnsureCaretVisible(NextText, NextCaret, Offset, TuiSize.Create(Viewport.Width, Viewport.Height));
  if (((NextText = Text) and (NextCaret = Caret)) and (NextOffset.X = Offset.X)) and
     (NextOffset.Y = Offset.Y) then
  begin
    return None
  end;

  return Some(TuiMsg.TextAreaChanged(Id, ChangeAction, NextText, NextCaret, NextOffset))
end;

// Routes a pointer position into a complete controlled text-area state proposal.
//
// Parameters:
// - `Id`: Identifier assigned to the created or selected value.
// - `Text`: Text processed or displayed by the operation.
// - `Offset`: Scroll offset or position applied by the operation.
// - `ChangeAction`: Application action emitted when the value changes.
// - `Viewport`: Visible input or text-area viewport.
// - `Point`: Point tested by the operation.
public function TuiRouteTextAreaPointer(
  Id: TuiControlId;
  Text: string;
  Offset: TuiPoint;
  ChangeAction: TuiAction;
  Viewport: TuiRect;
  Point: TuiPoint
): TuiMsg;
begin
  var Line: integer := TuiTextAreaClampLine(Text, Offset.Y + (Point.Y - Viewport.Y));
  var Column: integer := Offset.X + (Point.X - Viewport.X);
  var Caret: integer := TuiTextAreaCaretAtDisplayColumn(Text, Line, Column);
  var NextOffset: TuiPoint := TuiTextAreaEnsureCaretVisible(Text, Caret, Offset, TuiSize.Create(Viewport.Width, Viewport.Height));
  return TuiMsg.TextAreaChanged(Id, ChangeAction, Text, Caret, NextOffset)
end;

unit Std.Tui.Runtime.TerminalSession;

uses Std.Console;

mutable var
  TuiTerminalSessionOpen: boolean := false;

// Acquires the process terminal for one interactive Tui host.
//
// `Std.Console` performs transactional mode acquisition and reverse-order rollback.
public procedure TuiTerminalSessionAcquire();
begin
  AcquireInteractiveTerminal();
  TuiTerminalSessionOpen := true
end;

// Releases the process terminal when this Tui host owns it.
public procedure TuiTerminalSessionRelease();
begin
  if not TuiTerminalSessionOpen then
  begin
    return
  end;

  TuiTerminalSessionOpen := false;
  ReleaseInteractiveTerminal()
end;

unit Std.Tui.Text.Input;

uses Std.Console, Std.Str;

public type
  // Derived horizontal viewport for a one-line input.
  TuiInputViewport = record
    // Zero-based character index at which the viewport starts.
    public Start: integer;
    // Exclusive zero-based character index of the viewport.
    public EndIndex: integer;
    // Whether text is clipped on the left.
    public LeftClipped: boolean;
    // Whether text is clipped on the right.
    public RightClipped: boolean;
    // Zero-based terminal column of the caret.
    public CaretColumn: integer;
  end;

function TuiInputWidth(Text: string; Start: integer; EndIndex: integer): integer;
begin
  if EndIndex <= Start then
  begin
    return 0
  end;

  return Std.Console.DisplayWidth(Std.Str.Substring(Text, Start, EndIndex - Start))
end;

// Derives the smallest viewport that keeps the controlled caret visible.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
// - `Width`: Width in terminal cells.
public function TuiInputViewportFor(Text: string; Caret: integer; Width: integer): TuiInputViewport;
begin
  mutable var Start: integer := 0;
  if Width <= 0 then
  begin
    return record
      Start := Caret;
      EndIndex := Caret;
      LeftClipped := Caret > 0;
      RightClipped := Caret < Std.Str.Length(Text);
      CaretColumn := 0;
    end
  end;

  while Start < Caret do
  begin
    if TuiInputWidth(Text, Start, Caret) >= Width then
    begin
      Start := Start + 1
    end
    else
    begin
      break
    end
  end;
  mutable var EndIndex: integer := Start;
  while EndIndex < Std.Str.Length(Text) do
  begin
    if TuiInputWidth(Text, Start, EndIndex + 1) <= Width then
    begin
      EndIndex := EndIndex + 1
    end
    else
    begin
      break
    end
  end;

  return record
    Start := Start;
    EndIndex := EndIndex;
    LeftClipped := Start > 0;
    RightClipped := EndIndex < Std.Str.Length(Text);
    CaretColumn := TuiInputWidth(Text, Start, Caret);
  end
end;

// Maps one content-relative terminal column to a text caret.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
// - `Viewport`: Visible input or text-area viewport.
// - `Column`: Zero-based terminal display column.
public function TuiInputCaretAtColumn(Text: string; Viewport: TuiInputViewport; Column: integer): integer;
begin
  if Column <= 0 then
  begin
    return Viewport.Start
  end;
  mutable var Width: integer := 0;
  for Index: integer := Viewport.Start to Viewport.EndIndex - 1 do
  begin
    var GlyphWidth: integer := Std.Console.DisplayWidth(Std.Str.CharAt(Text, Index));
    if Column < Width + GlyphWidth then
    begin
      return Index
    end;

    Width := Width + GlyphWidth
  end;

  return Viewport.EndIndex
end;

unit Std.Tui.Text.TextArea;

uses Std.Arrays, Std.Console, Std.Str, Std.Tui.Geometry.Point, Std.Tui.Geometry.Size;

public type
  // Logical and terminal-cell location of one controlled text-area caret.
  TuiTextAreaPosition = record
    // Zero-based logical line index.
    public Line: integer;
    // Character index at which the logical line starts.
    public LineStart: integer;
    // Exclusive character index of the logical line.
    public LineEnd: integer;
    // Zero-based terminal display column.
    public DisplayColumn: integer;
  end;

// Returns the number of logical LF-separated lines, including a trailing empty line.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
public function TuiTextAreaLineCount(Text: string): integer;
begin
  return Std.Arrays.Length(Std.Str.Split(Text, Std.Str.Chr(10)))
end;

// Returns one zero-based logical line without its LF separator.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
// - `Line`: Zero-based logical line index.
public function TuiTextAreaLineText(Text: string; Line: integer): string;
begin
  var Lines: array of string := Std.Str.Split(Text, Std.Str.Chr(10));
  if (Line < 0) or (Line >= Std.Arrays.Length(Lines)) then
  begin
    panic('Tui text area line must be within its text')
  end;

  return Lines[Line]
end;

function TuiTextAreaLineStartAt(Text: string; Line: integer): integer;
begin
  var Lines: array of string := Std.Str.Split(Text, Std.Str.Chr(10));
  mutable var Target: integer := Line;
  if Target < 0 then
  begin
    Target := 0
  end;

  if Target >= Std.Arrays.Length(Lines) then
  begin
    Target := Std.Arrays.Length(Lines) - 1
  end;
  mutable var Start: integer := 0;
  for Index: integer := 0 to Target - 1 do
  begin
    Start := (Start + Std.Str.Length(Lines[Index])) + 1
  end;

  return Start
end;

// Locates a validated character-index caret in logical-line and terminal-column coordinates.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
public function TuiTextAreaLocate(Text: string; Caret: integer): TuiTextAreaPosition;
begin
  if (Caret < 0) or (Caret > Std.Str.Length(Text)) then
  begin
    panic('Tui text area caret must be within its text')
  end;
  var Lines: array of string := Std.Str.Split(Text, Std.Str.Chr(10));
  mutable var LineStart: integer := 0;
  for Line: integer := 0 to Std.Arrays.Length(Lines) - 1 do
  begin
    var LineEnd: integer := LineStart + Std.Str.Length(Lines[Line]);
    if Caret <= LineEnd then
    begin
      var Prefix: string := Std.Str.Substring(Lines[Line], 0, Caret - LineStart);
      return record
        Line := Line;
        LineStart := LineStart;
        LineEnd := LineEnd;
        DisplayColumn := Std.Console.DisplayWidth(Prefix);
      end
    end;

    LineStart := LineEnd + 1
  end;

  panic('Tui text area caret must be within its text')
end;

// Returns a caret on `Line` nearest to the requested terminal display column.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
// - `Line`: Zero-based logical line index.
// - `DisplayColumn`: Requested zero-based terminal display column.
public function TuiTextAreaCaretAtDisplayColumn(Text: string; Line: integer; DisplayColumn: integer): integer;
begin
  mutable var TargetColumn: integer := DisplayColumn;
  if TargetColumn < 0 then
  begin
    TargetColumn := 0
  end;
  var Start: integer := TuiTextAreaLineStartAt(Text, Line);
  var LineText: string := TuiTextAreaLineText(Text, Line);
  for Column: integer := 0 to Std.Str.Length(LineText) - 1 do
  begin
    var Prefix: string := Std.Str.Substring(LineText, 0, Column + 1);
    if Std.Console.DisplayWidth(Prefix) > TargetColumn then
    begin
      return Start + Column
    end
  end;

  return Start + Std.Str.Length(LineText)
end;

// Returns minimum content size for all logical lines before viewport constraints.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
public function TuiTextAreaContentSize(Text: string): TuiSize;
begin
  var Lines: array of string := Std.Str.Split(Text, Std.Str.Chr(10));
  mutable var Width: integer := 1;
  for Index: integer := 0 to Std.Arrays.Length(Lines) - 1 do
  begin
    var LineWidth: integer := Std.Console.DisplayWidth(Lines[Index]);
    if LineWidth > Width then
    begin
      Width := LineWidth
    end
  end;

  return TuiSize.Create(Width, Std.Arrays.Length(Lines))
end;

// Adjusts a non-negative model offset only as much as needed to reveal the caret.
//
// Parameters:
// - `Text`: Text processed or displayed by the operation.
// - `Caret`: Zero-based character index of the caret.
// - `Offset`: Scroll offset or position applied by the operation.
// - `Viewport`: Visible input or text-area viewport.
public function TuiTextAreaEnsureCaretVisible(
  Text: string;
  Caret: integer;
  Offset: TuiPoint;
  Viewport: TuiSize
): TuiPoint;
begin
  mutable var Next: TuiPoint := Offset;
  if (Viewport.Width <= 0) and (Viewport.Height <= 0) then
  begin
    return Next
  end;
  var Position: TuiTextAreaPosition := TuiTextAreaLocate(Text, Caret);
  if Viewport.Width > 0 then
  begin
    if Position.DisplayColumn < Next.X then
    begin
      Next.X := Position.DisplayColumn
    end
    else if Position.DisplayColumn >= Next.X + Viewport.Width then
    begin
      Next.X := (Position.DisplayColumn - Viewport.Width) + 1
    end
  end;

  if Viewport.Height > 0 then
  begin
    if Position.Line < Next.Y then
    begin
      Next.Y := Position.Line
    end
    else if Position.Line >= Next.Y + Viewport.Height then
    begin
      Next.Y := (Position.Line - Viewport.Height) + 1
    end
  end;

  return Next
end;

unit Std.Version;

public const
