// Covers default and mutable HTTP request limits.
program HttpRequestLimitsTest;

uses Std.Http, Std.Test;

begin
  mutable var RequestValue: Request := Request.Get('http://localhost/');
  AssertEquals(65536, RequestValue.MaxHeaderBytes);
  AssertEquals(16777216, RequestValue.MaxResponseBytes);
  AssertEquals(5, RequestValue.MaxRedirects);
  RequestValue.MaxHeaderBytes := 1024;
  RequestValue.MaxRedirects := 0;
  AssertEquals(1024, RequestValue.MaxHeaderBytes);
  AssertEquals(0, RequestValue.MaxRedirects)
end.

// Covers HTTP server-loop defaults and request-handler typing.
program HttpServerLoopTypesTest;

uses Std.Http, Std.Test;

// Returns a response whose reason phrase mirrors the request method.
//
// Parameters:
// - `RequestValue`: Request supplied through the handler type.
function Handle(RequestValue: ServerRequest): ServerResponse;
begin
  return ServerResponse.Create(200, RequestValue.Method)
end;

begin
  var Options: ServerOptions := ServerOptions.Create();
  AssertEquals(65536, Options.MaxHeaderBytes);
  AssertEquals(1048576, Options.MaxBodyBytes);
  AssertEquals(30000, Options.ConnectionTimeoutMillis);
  AssertEquals(8, Options.MaxConcurrentRequests);
  AssertEquals(0, Options.MaxRequests);
  var HandlerValue: RequestHandler := Handle;
  var RequestValue: ServerRequest := record
    Method := 'OK';
    Target := '/';
    Headers := [];
    Body := [];
  end;
  var ResponseValue: ServerResponse := HandlerValue(RequestValue);
  AssertEquals(200, ResponseValue.StatusCode);
  AssertEquals('OK', ResponseValue.ReasonPhrase)
end.

// Covers HTTP server response construction and mutable fields.
program HttpServerTypesTest;

uses Std.Arrays, Std.Http, Std.Net.Utf8, Std.Test;

begin
  mutable var ResponseValue: ServerResponse := ServerResponse.Create(201, 'Created');
  ResponseValue.Headers := [Header.Create('Content-Type', 'text/plain')];
  ResponseValue.Body := Std.Net.Utf8.Encode('ok');
  AssertEquals(201, ResponseValue.StatusCode);
