program ServerFailureTest;

uses Std.Server, Std.Net, Std.Task, Std.Results, Std.Test, Std.Arrays;

function BindListener(): result of Std.Net.Listener, string;
begin
  for Port: integer := 28200 to 28299 do
  begin
    var Opened: result of Std.Net.Listener, string := Listen('127.0.0.1', Port);
    if IsOk(Opened) then
    begin
      return Opened
    end
  end;

  return Error('no test port available')
end;

begin
  var Life: ServerLifetime := Unwrap(CreateLifetime(1000, false));
  var Group: TaskGroup := GetWorkGroup(Life);
  var Worker: task := StartTaskInGroup(Group, function(Token: CancellationToken): result of boolean, string begin
    return Error('session failed')
  end);
  var Listener: Std.Net.Listener := Unwrap(BindListener());
  OwnListener(Life, Listener);
  // Deliberate ownership misuse: cleanup must preserve this failure.
  CloseListener(Listener);
  RequestStop(Life);
  var Failures: array of TaskFailure := CloseTaskGroup(Group);
  AssertEquals(1, Std.Arrays.Length(Failures));
  AssertEquals('session failed', Failures[0].Message);
  AssertEquals(1, Std.Arrays.Length(ShutdownErrors(Life)));
  AssertTrue(Unwrap(FinishShutdown(Life)))
end.

program ServerLifetimeTest;

uses Std.Server, Std.Task, Std.Time, Std.Results, Std.Test, Std.Arrays;

begin
  AssertTrue(IsError(CreateLifetime(-1, false)));
  AssertTrue(IsError(CreateLifetime(86400001, false)));
  var Life: ServerLifetime := Std.Results.Unwrap(CreateLifetime(20, false));
  var Group: TaskGroup := GetWorkGroup(Life);
  var Gate: channel of boolean := CreateChannel(1);
  var Worker: task := StartTaskInGroup(Group, function(Token: CancellationToken): boolean begin
    return Std.Results.Unwrap(Receive(Gate))
  end);
  AssertTrue(IsReady(Life));
  AssertTrue(not IsCancellationRequested(GetStopToken(Life)));
  AssertTrue(IsError(FinishShutdown(Life)));
  AssertTrue(RequestStop(Life));
  AssertTrue(not IsReady(Life));
  AssertTrue(IsCancellationRequested(GetStopToken(Life)));
  AssertTrue(not RequestStop(Life));
  AssertTrue(IsError(CloseTaskGroupWithTimeout(Group, RemainingMillis(Life))));
  AssertEquals(0, RemainingMillis(Life));
  AssertTrue(IsError(FinishShutdown(Life)));
  AssertTrue(not RequestStop(Life));
  AssertEquals(0, RemainingMillis(Life));
  Send(Gate, true);
  AssertEquals(0, Std.Arrays.Length(CloseTaskGroup(Group)));
  AssertTrue(Std.Results.Unwrap(FinishShutdown(Life)));
  AssertTrue(Std.Results.Unwrap(FinishShutdown(Life)));
  AssertEquals(0, Std.Arrays.Length(ShutdownErrors(Life)));
  CloseChannel(Gate)
end.

program ServerListenerTest;

uses Std.Server, Std.Net, Std.Task, Std.Results, Std.Test, Std.Arrays;

function BindListener(): result of Std.Net.Listener, string;
begin
  for Port: integer := 28100 to 28199 do
  begin
    var Opened: result of Std.Net.Listener, string := Listen('127.0.0.1', Port);
    if IsOk(Opened) then
    begin
      return Opened
    end
  end;

  return Error('no test port available')
end;

begin
  var Life: ServerLifetime := Unwrap(CreateLifetime(1000, false));
  var Other: ServerLifetime := Unwrap(CreateLifetime(1000, false));
  var Listener: Std.Net.Listener := Unwrap(BindListener());
  AssertTrue(Unwrap(OwnListener(Life, Listener)));
  AssertTrue(not Unwrap(OwnListener(Life, Listener)));
  AssertTrue(IsError(OwnListener(Other, Listener)));
  AssertTrue(RequestStop(Life));
  AssertTrue(IsError(Accept(Listener)));
  AssertTrue(IsError(OwnListener(Life, Listener)));
  AssertEquals(0, Std.Arrays.Length(CloseTaskGroup(GetWorkGroup(Life))));
  AssertTrue(Unwrap(FinishShutdown(Life)));
  AssertEquals(0, Std.Arrays.Length(ShutdownErrors(Life)));
  RequestStop(Other);
  CloseTaskGroup(GetWorkGroup(Other));
  AssertTrue(Unwrap(FinishShutdown(Other)))
end.

