program TuiBackgroundPendingTest;

uses Std.Results, Std.Task, Std.Test, Std.Time, Std.Tui;

type
  PendingModel = record
    Gate: channel of boolean;
    Ready: channel of boolean;
    Started: channel of boolean;
    FailOld: boolean;
    Failures: integer;
  end;

function Update(State: PendingModel; Msg: TuiMsg; Cmd: TuiCmdOutput): PendingModel;
begin
  case Msg of
    TuiMsg.Started:
    begin
      var Gate: channel of boolean := State.Gate;
      var Ready: channel of boolean := State.Ready;
      var FailOld: boolean := State.FailOld;
      Cmd.ReplaceSubscription(1, function(Token: CancellationToken): result of boolean, string begin
        Send(Ready, true);
        if FailOld then
        begin
          Receive(Gate);
          return Error('old source failed')
        end;

        ReceiveWithCancellation(Gate, Token);
        return Ok(true)
      end)
    end;
    TuiMsg.Tick(Delta):
    begin
      if Delta = 1 then
      begin
        var Started: channel of boolean := State.Started;
        Cmd.ReplaceSubscription(1, function(Token: CancellationToken): result of boolean, string begin
          Send(Started, true);
          return Ok(true)
        end)
      end
      else if Delta = 2 then
      begin
        Cmd.CancelSubscription(1)
      end
    end;
    TuiMsg.BackgroundFailed(Id, Kind, Message, Code, Line, Column):
    begin
      AssertEquals(1, Id);
      AssertTrue(Kind = TaskFailureKind.ReturnedError);
      AssertEquals('old source failed', Message);
      mutable var Next: PendingModel := State;
      Next.Failures := State.Failures + 1;
      return Next
    end
    else
    begin
    end
  end;

  return State
end;

function UpdateMessage(State: PendingModel; Message: integer; Cmd: TuiCmdOutput): PendingModel;
begin
  return State
end;

function View(State: PendingModel): TuiElement;
begin
  return TuiElementBuilders.MakeLabel('pending cancellation')
end;

begin
  var Inbox: channel of integer := CreateChannel(1);
  var Gate: channel of boolean := CreateChannel(1);
  var Ready: channel of boolean := CreateChannel(1);
  var Started: channel of boolean := CreateChannel(1);
  var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(24, 4));
  mutable var State: PendingModel := App.RunBackgroundIterations(record
    Gate := Gate;
    Ready := Ready;
    Started := Started;
    FailOld := true;
    Failures := 0;
  end, Inbox, Update, UpdateMessage, View, 1, 0);
  AssertTrue(Unwrap(ReceiveWithTimeout(Ready, 5000)));
  App.Inject(TuiMsg.Tick(1));
  App.Inject(TuiMsg.Tick(2));
  State := App.RunBackgroundIterations(State, Inbox, Update, UpdateMessage, View, 2, 0);
  Send(Gate, true);
  var Deadline: integer := MonotonicMillis() + 5000;
  while (State.Failures = 0) and (MonotonicMillis() < Deadline) do
  begin
    State := App.RunBackgroundIterations(State, Inbox, Update, UpdateMessage, View, 1, 0);
    Sleep(1)
  end;

  AssertEquals(1, State.Failures);
  AssertTrue(IsError(ReceiveWithTimeout(Started, 0)));
  App.CloseWithBackground(Inbox);
  var SecondInbox: channel of integer := CreateChannel(1);
  var SecondApp: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(24, 4));
  State.FailOld := false;
  State := SecondApp.RunBackgroundIterations(State, SecondInbox, Update, UpdateMessage, View, 1, 0);
  AssertTrue(Unwrap(ReceiveWithTimeout(Ready, 5000)));
  SecondApp.Inject(TuiMsg.Tick(1));
  State := SecondApp.RunBackgroundIterations(State, SecondInbox, Update, UpdateMessage, View, 1, 0);
  SecondApp.CloseWithBackground(SecondInbox);
  AssertTrue(IsError(ReceiveWithTimeout(Started, 0)));
  CloseChannel(Gate);
  CloseChannel(Ready);
  CloseChannel(Started)
end.

program TuiBackgroundResponsivenessTest;

uses Std.Results, Std.Task, Std.Test, Std.Time, Std.Tui;

type
  Model = record
    Generation: integer;
    Gate: channel of boolean;
    Started: channel of integer;
    Painted: channel of integer;
  end;

procedure Replace(State: Model; Cmd: TuiCmdOutput);
begin
  var Generation: integer := State.Generation;
  var Gate: channel of boolean := State.Gate;
  var Started: channel of integer := State.Started;
  Cmd.ReplaceSubscription(1, function(Token: CancellationToken): result of boolean, string begin
    Send(Started, Generation);
    if Generation = 0 then
    begin
      // Deliberately defer cooperation to prove that the host remains responsive.
      Receive(Gate)
    end;

    return Ok(true)
  end)
end;

function Update(State: Model; Msg: TuiMsg; Cmd: TuiCmdOutput): Model;
begin
  case Msg of
    TuiMsg.Started:
    begin
      Replace(State, Cmd)
    end;
    TuiMsg.Tick(Delta):
    begin
      if Delta > 0 then
      begin
        mutable var Next: Model := State;
        Next.Generation := State.Generation + 1;
        Replace(Next, Cmd);
        return Next
      end
    end
    else
    begin
    end
  end;

  return State
end;

function UpdateMessage(State: Model; Message: integer; Cmd: TuiCmdOutput): Model;
begin
  return State
end;

function View(State: Model): TuiElement;
begin
  if State.Generation = 3 then
  begin
    TrySend(State.Painted, 3)
  end;

  return TuiElementBuilders.MakeLabel('responsive')
end;

function ReleaseAfterPaint(Painted: channel of integer; Gate: channel of boolean): boolean;
begin
  // A timeout releases the gate even on the old blocking implementation.
  var Paint: result of integer, string := ReceiveWithTimeout(Painted, 3000);
  Send(Gate, true);
  return IsOk(Paint)
end;

begin
  var Inbox: channel of integer := CreateChannel(1);
  var Gate: channel of boolean := CreateChannel(1);
  var Started: channel of integer := CreateChannel(4);
  var Painted: channel of integer := CreateChannel(1);
  var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(20, 4));
  mutable var State: Model := App.RunBackgroundIterations(record
    Generation := 0;
    Gate := Gate;
    Started := Started;
    Painted := Painted;
  end, Inbox, Update, UpdateMessage, View, 1, 0);
  AssertEquals(0, Unwrap(ReceiveWithTimeout(Started, 5000)));
  var Observer: task := go ReleaseAfterPaint(Painted, Gate);
  for Index: integer := 1 to 3 do
  begin
    App.Inject(TuiMsg.Tick(1));
    State := App.RunBackgroundIterations(State, Inbox, Update, UpdateMessage, View, 1, 0);
    AssertEquals(Index, State.Generation)
  end;

  AssertTrue(Wait(Observer));
  mutable var Replacement: result of integer, string := ReceiveWithTimeout(Started, 0);
  var Deadline: integer := MonotonicMillis() + 5000;
  while IsError(Replacement) and (MonotonicMillis() < Deadline) do
  begin
    State := App.RunBackgroundIterations(State, Inbox, Update, UpdateMessage, View, 1, 0);
    Replacement := ReceiveWithTimeout(Started, 1)
  end;

  AssertEquals(3, Unwrap(Replacement));
  AssertTrue(IsError(ReceiveWithTimeout(Started, 0)));
  App.CloseWithBackground(Inbox);
  CloseChannel(Gate);
  CloseChannel(Started);
  CloseChannel(Painted)
end.

program TuiBackgroundSubscriptionTest;

uses Std.Results, Std.Task, Std.Test, Std.Tui;

type
  SubscriptionModel = record
    Gate: channel of boolean;
    Started: channel of integer;
    Stopped: channel of integer;
    Generation: integer;
  end;

procedure ReplaceWorker(State: SubscriptionModel; Cmd: TuiCmdOutput);
begin
  var Gate: channel of boolean := State.Gate;
  var Started: channel of integer := State.Started;
  var Stopped: channel of integer := State.Stopped;
  var Generation: integer := State.Generation;
  Cmd.ReplaceSubscription(1, function(Token: CancellationToken): result of boolean, string begin
    Send(Started, Generation);
    if IsError(ReceiveWithCancellation(Gate, Token)) then
    begin
      Send(Stopped, Generation)
    end;

    return Ok(true)
  end)
end;

function UpdateFramework(State: SubscriptionModel; Msg: TuiMsg; Cmd: TuiCmdOutput): SubscriptionModel;
begin
  case Msg of
    TuiMsg.Started:
    begin
      ReplaceWorker(State, Cmd);
      return State
    end;
    TuiMsg.Tick(Delta):
    begin
      if Delta = 0 then
      begin
        return State
      end;
      var Next: SubscriptionModel := record
        Gate := State.Gate;
        Started := State.Started;
        Stopped := State.Stopped;
        Generation := State.Generation + 1;
      end;

      ReplaceWorker(Next, Cmd);
      return Next
    end
    else
    begin
      return State
    end
  end
end;

function UpdateApplication(State: SubscriptionModel; Message: integer; Cmd: TuiCmdOutput): SubscriptionModel;
begin
  return State
end;

function View(State: SubscriptionModel): TuiElement;
begin
  return TuiElementBuilders.MakeLabel('subscription')
end;

begin
  var Inbox: channel of integer := CreateChannel(1);
  var Gate: channel of boolean := CreateChannel(1);
  var Started: channel of integer := CreateChannel(2);
  var Stopped: channel of integer := CreateChannel(2);
  var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(24, 4));
  mutable var Model: SubscriptionModel := App.RunBackgroundIterations(record
    Gate := Gate;
    Started := Started;
    Stopped := Stopped;
    Generation := 0;
  end, Inbox, UpdateFramework, UpdateApplication, View, 1, 0);
  AssertEquals(0, Unwrap(ReceiveWithTimeout(Started, 10000)));
  App.Inject(TuiMsg.Tick(1));
  Model := App.RunBackgroundIterations(Model, Inbox, UpdateFramework, UpdateApplication, View, 1, 0);
  AssertEquals(1, Model.Generation);
  AssertEquals(0, Unwrap(ReceiveWithTimeout(Stopped, 10000)));
  Model := App.RunBackgroundIterations(Model, Inbox, UpdateFramework, UpdateApplication, View, 1, 0);
  AssertEquals(1, Unwrap(ReceiveWithTimeout(Started, 10000)));
  App.CloseWithBackground(Inbox);
  AssertEquals(1, Unwrap(ReceiveWithTimeout(Stopped, 10000)));
  AssertTrue(IsError(TrySend(Inbox, 1)));
  CloseChannel(Gate);
  CloseChannel(Started);
  CloseChannel(Stopped)
end.

