  AssertEquals('H', Std.Options.Unwrap(Surface.TryCellAt(TuiPoint.Create(0, 3))).Glyph);
  AssertEquals('i', Std.Options.Unwrap(Surface.TryCellAt(TuiPoint.Create(1, 3))).Glyph);
