program TuiTextAreaPointerTest;

uses Std.Str, Std.Test, Std.Tui;

type
  PointerModel = record
    Focus: integer;
    Text: string;
    Caret: integer;
    Offset: TuiPoint;
  end;

function ViewTextArea(State: PointerModel): TuiElement;
begin
  mutable var Focused: option of TuiControlId := None;
  if State.Focus > 0 then
  begin
    Focused := Some(TuiControlId.Create(State.Focus))
  end;

  return TuiElementBuilders.MakeDesktop(Focused, [
                                                   TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), State.Text, State.Caret, State.Offset, TuiAction.Create(9))
                                                 ])
end;

function UpdateTextArea(State: PointerModel; Msg: TuiMsg; Cmd: TuiCmdOutput): PointerModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(Id):
        begin
          return record
            Focus := Id.Value;
            Text := State.Text;
            Caret := State.Caret;
            Offset := State.Offset;
          end
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, Offset):
    begin
      AssertEquals(1, Source.Value);
      AssertEquals(9, Action.Value);
      return record
        Focus := State.Focus;
        Text := Text;
        Caret := Caret;
        Offset := Offset;
      end
    end
    else
    begin
      return State
    end
  end
end;

function Click(
  App: TuiApplication;
  State: PointerModel;
  X: integer;
  Y: integer;
  Iterations: integer
): PointerModel;
begin
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Down, TuiPointerButton.Left, TuiPoint.Create(X, Y)));
  return App.RunIterations(State, UpdateTextArea, ViewTextArea, Iterations, 0)
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(6, 3));
  mutable var Model: PointerModel := record
    Focus := 0;
    Text := (('zero' + Std.Str.Chr(10)) + 'one') + (Std.Str.Chr(10) + 'three');
    Caret := 0;
    Offset := TuiPoint.Create(0, 0);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Click(App, Model, 2, 1, 2);
  AssertEquals(1, Model.Focus);
  AssertEquals(7, Model.Caret);
  Model := Click(App, Model, 5, 1, 1);
  AssertEquals(8, Model.Caret);
  Model := record
    Focus := 1;
    Text := Model.Text;
    Caret := Model.Caret;
    Offset := TuiPoint.Create(2, 1);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Click(App, Model, 1, 1, 1);
  AssertEquals(12, Model.Caret);
  AssertEquals(2, Model.Offset.X);
  AssertEquals(1, Model.Offset.Y);
  App.Close()
end.

program TuiTextAreaSnapshotTest;

uses Std.Str, Std.Test, Std.Tui;

type
  SnapshotModel = record
    Focused: boolean;
  end;

function ViewTextArea(State: SnapshotModel): TuiElement;
begin
  mutable var Focus: option of TuiControlId := None;
  if State.Focused then
  begin
    Focus := Some(TuiControlId.Create(1))
  end;
  var Text: string := (('012345' + Std.Str.Chr(10)) + 'alpha') + (Std.Str.Chr(10) + 'omega');
  return TuiElementBuilders.MakeDesktop(Focus, [
                                                 TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), Text, 9, TuiPoint.Create(1, 1), TuiAction.Create(9))
                                               ])
end;

function UpdateTextArea(State: SnapshotModel; Msg: TuiMsg; Cmd: TuiCmdOutput): SnapshotModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  return State
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(4, 2));
  App.RunIterations(record
    Focused := true;
  end, UpdateTextArea, ViewTextArea, 0, 0);
  var Focused: TuiSurfaceSnapshot := App.SurfaceSnapshot();
  AssertEquals('l▏ha', Focused.LineAt(0));
  AssertEquals('mega', Focused.LineAt(1));
  AssertTrue(Focused.CellAt(1, 0).Role = TuiStyleRole.Focused);
  App.RunIterations(record
    Focused := false;
  end, UpdateTextArea, ViewTextArea, 0, 0);
  var Unfocused: TuiSurfaceSnapshot := App.SurfaceSnapshot();
  AssertEquals('lpha', Unfocused.LineAt(0));
  AssertEquals('mega', Unfocused.LineAt(1));
  AssertTrue(Unfocused.CellAt(1, 0).Role = TuiStyleRole.Normal);
  App.Close()
end.

program TextAreaUnicodeBoundariesTest;

uses Std.Str, Std.Test, Std.Tui;

type
  Model = record
    Text: string;
    Caret: integer;
  end;

function View(State: Model): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [
                                                                        TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), State.Text, State.Caret, TuiPoint.Create(0, 0), TuiAction.Create(1))
                                                                      ])
end;

function Update(State: Model; Msg: TuiMsg; Cmd: TuiCmdOutput): Model;
begin
  Cmd.Set(TuiCmd.NoCommand);
  return State
end;

procedure CheckCaret(App: TuiApplication; Text: string; Caret: integer; X: integer; Y: integer);
begin
  App.RunIterations(record
    Text := Text;
    Caret := Caret;
  end, Update, View, 0, 0);
  AssertTrue(App.SurfaceSnapshot().CellAt(X, Y).Role = TuiStyleRole.Focused)
end;

begin
  var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(8, 4));
  var Text: string := ((((('e' + Std.Str.Chr(769)) + '界') + Std.Str.Chr(10)) + Std.Str.Chr(10)) + 'x') +
                      Std.Str.Chr(10);
  CheckCaret(App, Text, 0, 0, 0);
  CheckCaret(App, Text, 2, 1, 0);
  CheckCaret(App, Text, 3, 3, 0);
  CheckCaret(App, Text, 4, 0, 1);
  CheckCaret(App, Text, 5, 0, 2);
  CheckCaret(App, Text, 6, 1, 2);
  CheckCaret(App, Text, 7, 0, 3);
  CheckCaret(App, '', 0, 0, 0);
  App.Close()
end.

program TuiThemeSwitchTest;

uses Std.Test, Std.Tui;

function ViewTheme(State: integer): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(None, [TuiElementBuilders.MakeLabel('theme')])
end;

function UpdateTheme(State: integer; Msg: TuiMsg; Cmd: TuiCmdOutput): integer;
begin
  Cmd.SetPalette(TuiPalette.Default()
                   .WithRole(TuiStyleRole.Normal, TuiStyle.FromColors(TuiColor.FromRgb(1, 2, 3), TuiColor.FromRgb(4, 5, 6))));
  return State
end;

begin
  var Initial: TuiPalette := TuiPalette.Default()
                               .WithRole(TuiStyleRole.Normal, TuiStyle.FromColors(TuiColor.FromRgb(10, 20, 30), TuiColor.FromRgb(40, 50, 60)));
  var App: TuiApplication := TuiApplication.OpenForTestWithPalette(TuiSize.Create(10, 2), Initial);
  AssertEquals(10, App.Palette().Normal.Foreground.Red);
  App.Inject(TuiMsg.Tick(0));
  var _: integer := App.RunIterations(0, UpdateTheme, ViewTheme, 1, 0);
  AssertEquals(1, App.Palette().Normal.Foreground.Red);
  AssertEquals(6, App.Palette().Normal.Background.Blue);
  App.Close()
end.
